insert into public.topics (id, subject_id, slug, title, priority, marks_hint, content, viva, vignette, tags) overriding system value values
(1, 1, 'ameloblastoma', 'Ameloblastoma', 'must_know', '10-mark essay', '{"definition":"A benign but locally aggressive epithelial odontogenic tumour arising from remnants of the dental lamina, the enamel organ, the lining of odontogenic cysts or the basal cells of the oral mucosa. It is the most common clinically significant odontogenic tumour.","classification":["WHO 2022: Conventional, Unicystic, Peripheral (extraosseous), Metastasizing ameloblastoma; Adenoid ameloblastoma (new entity)","Histological patterns: Follicular (most common), Plexiform, Acanthomatous, Granular cell, Basal cell, Desmoplastic","Unicystic subtypes (Ackermann): Luminal, Intraluminal (plexiform), Mural"],"clinical_features":["Peak in the 3rd–5th decade; unicystic type is seen in younger patients (2nd–3rd decade)","About 80% occur in the mandible, mostly in the molar–ramus region","Painless, slow-growing swelling with expansion of the cortical plates; egg-shell crackling","Tooth mobility and displacement; paraesthesia is rare"],"investigations":["OPG / CBCT: multilocular \"soap-bubble\" (large loculi) or \"honeycomb\" (small loculi) radiolucency","Knife-edge root resorption of adjacent teeth; cortical thinning and expansion","Desmoplastic type: mixed radiolucent–radiopaque lesion, often in the anterior maxilla, mimicking a fibro-osseous lesion","Incisional biopsy for diagnosis; BRAF V600E mutation is common in mandibular tumours"],"histopathology":["Follicles or islands of odontogenic epithelium in a fibrous stroma","Peripheral tall columnar ameloblast-like cells showing palisading and reverse polarity of nuclei","Central loosely arranged stellate reticulum-like cells, often with cystic degeneration","Vickers–Gorlin criteria: hyperchromatic basal nuclei, reverse polarity, subnuclear cytoplasmic vacuolation"],"management":["Conventional: segmental or marginal resection with 1–1.5 cm bony margins","Reconstruction, e.g. with a vascularised fibula free flap or a non-vascularised iliac graft","Unicystic (luminal/intraluminal): enucleation with Carnoy''s solution or peripheral ostectomy; mural type is treated like the conventional tumour","Long-term follow-up: recurrence after simple curettage of conventional ameloblastoma is very high (50–90%)"],"viva_pearls":["Most common pattern: follicular. The histological pattern does not change behaviour – prognosis depends on the clinical type (conventional vs unicystic vs peripheral).","Desmoplastic ameloblastoma is the exception: anterior maxilla, mixed density, mimics a fibro-osseous lesion.","Ameloblastic carcinoma ≠ metastasizing ameloblastoma: the latter is histologically benign yet metastasises (usually to the lung)."]}'::jsonb, '[{"q":"Define ameloblastoma.","keywords":["benign","locally aggressive|locally invasive|aggressive","odontogenic","epithelial|epithelium","tumour|tumor|neoplasm"],"probe":"Is it benign or malignant, and how does it behave locally?"},{"q":"Describe its radiographic appearance.","keywords":["multilocular","soap bubble|soap-bubble|honeycomb","radiolucen","root resorption|knife edge|knife-edge|resorption","expansion|cortical"],"probe":"Tell me about the locularity, and what happens to the roots of adjacent teeth."},{"q":"Describe the histopathology of the follicular type.","keywords":["follicle|islands","columnar","reverse polarity|reversed polarity","stellate reticulum","palisad"],"probe":"What are the Vickers–Gorlin criteria?"},{"q":"How will you manage a conventional ameloblastoma of the mandible?","keywords":["resection","margin|1 cm|1.5 cm|safe margin","reconstruct|fibula|graft","recurrence|follow"],"probe":"Why is curettage alone not acceptable for the conventional type?"}]'::jsonb, 'A 35-year-old man has a painless, slowly enlarging swelling of the right posterior mandible over 2 years. There is buccal and lingual cortical expansion with egg-shell crackling. The OPG shows a multilocular radiolucency in the molar–ramus region with resorption of the adjacent molar roots.', array['odontogenic tumour','multilocular']::text[]),
(2, 1, 'odontogenic-keratocyst', 'Odontogenic Keratocyst (OKC)', 'must_know', '10-mark essay', '{"definition":"A developmental odontogenic cyst arising from remnants of the dental lamina, lined by a thin, uniform parakeratinised stratified squamous epithelium. It is known for its aggressive growth and high recurrence. (WHO 2005 called it keratocystic odontogenic tumour; WHO 2017/2022 re-classified it as a cyst.)","classification":["Solitary (sporadic)","Multiple – associated with Gorlin–Goltz (nevoid basal cell carcinoma) syndrome","Orthokeratinised odontogenic cyst is now a separate, less aggressive entity"],"clinical_features":["2nd–4th decade; male predilection","Mandible (about 70%), especially the posterior body and ramus","Grows antero-posteriorly through medullary bone, so expansion is minimal until late","Often asymptomatic; may present with pain, swelling or discharge if infected"],"investigations":["Radiograph: unilocular or multilocular radiolucency with smooth, scalloped, corticated borders","Aspirate: low soluble protein (< 4 g/dL) with keratin squames","Biopsy is diagnostic; PTCH1 gene mutation is seen in syndromic and many sporadic cases"],"histopathology":["Uniform parakeratinised stratified squamous epithelium, 6–8 cell layers thick","Corrugated (wavy) parakeratin surface","Palisaded, hyperchromatic basal cells – \"tombstone\" appearance","Flat epithelium–connective tissue interface; satellite (daughter) cysts in the fibrous wall"],"management":["Enucleation with peripheral ostectomy and/or Carnoy''s solution (modified Carnoy''s without chloroform)","Decompression or marsupialisation for large lesions, followed by enucleation","Excise the overlying attached mucosa if it is adherent","Long-term follow-up (at least 5–10 years); recurrence is about 25–60% after simple enucleation"],"viva_pearls":["Why does it recur? Thin, friable lining; satellite cysts; residual dental lamina rests; high mitotic activity of the epithelium.","Gorlin–Goltz: multiple OKCs, multiple basal cell carcinomas, bifid ribs, calcified falx cerebri, palmar/plantar pits."]}'::jsonb, '[{"q":"What is an odontogenic keratocyst?","keywords":["developmental","odontogenic","dental lamina","parakeratin","recurrence|aggressive|recur"],"probe":"What is its origin, and what kind of keratin lines it?"},{"q":"Describe the histopathology.","keywords":["corrugated|wavy","parakeratin","palisad|tombstone","uniform|6|8 cell","satellite|daughter"],"probe":"Describe the basal cell layer and the surface keratin."},{"q":"Why does an OKC recur so often?","keywords":["thin|friable","satellite|daughter","dental lamina|rests","mitotic|proliferat"],"probe":"Think about the lining and what is left behind in the cyst wall."},{"q":"Which syndrome is associated with multiple OKCs? List its features.","keywords":["gorlin|nevoid basal cell","basal cell carcinoma","bifid rib","falx|calcification","ptch|pits"],"probe":"Name the skin malignancy and the skeletal anomaly in this syndrome."},{"q":"How do you manage it?","keywords":["enucleation","carnoy","ostectomy|peripheral ostectomy","marsupial|decompression","follow"],"probe":"What adjunct do you use to reduce recurrence?"}]'::jsonb, 'A 24-year-old man has a vague swelling of the left ramus. The OPG shows a large radiolucency with scalloped, corticated margins extending along the body of the mandible, with very little bony expansion. Aspiration yields thick, cheesy, creamy material.', array['developmental cyst','Gorlin']::text[]),
(3, 1, 'radicular-cyst', 'Radicular (Periapical) Cyst', 'must_know', '5-mark short note', '{"definition":"An inflammatory odontogenic cyst arising from the epithelial cell rests of Malassez in the periodontal ligament, following periapical inflammation caused by a non-vital tooth. It is the most common odontogenic cyst.","classification":["Periapical (apical) radicular cyst","Lateral radicular cyst (from a lateral/accessory canal)","Residual cyst (remains after the tooth is extracted)"],"etiology":["Pulp necrosis → periapical granuloma → proliferation of the rests of Malassez","Phases: initiation, cyst formation, enlargement","Enlargement by osmotic / hydrostatic pressure and bone resorption by prostaglandins"],"clinical_features":["3rd–6th decade; most common in the maxillary anterior region","Always associated with a non-vital tooth","Usually asymptomatic; slow expansion; may become infected"],"investigations":["Pulp vitality test: non-vital","Well-defined round or ovoid radiolucency at the apex with a corticated border and loss of lamina dura","Cannot be reliably differentiated from a periapical granuloma on radiographs – histology confirms"],"histopathology":["Non-keratinised stratified squamous epithelium of variable thickness, with arcading","Rushton (hyaline) bodies in the epithelium","Cholesterol clefts, foam cells and chronic inflammatory cells in the capsule"],"management":["Root canal treatment – small lesions often heal","Periapical surgery (apicectomy with enucleation and retrograde filling) for persistent lesions","Extraction with curettage if the tooth is non-restorable; marsupialisation for very large cysts"],"viva_pearls":["Tooth must be non-vital – a vital tooth with an apical radiolucency points to another diagnosis.","Rushton bodies are seen in radicular and dentigerous cysts."]}'::jsonb, '[{"q":"Define a radicular cyst.","keywords":["inflammatory","malassez","non vital|non-vital|necrotic|nonvital","periapical|apex|apical"],"probe":"From which epithelial rests does it arise?"},{"q":"Explain its pathogenesis.","keywords":["initiation","proliferat|formation","enlargement|osmotic|hydrostatic","granuloma"],"probe":"What are the three phases?"},{"q":"Describe the histopathology.","keywords":["non keratin|non-keratin|nonkeratin","rushton|hyaline","cholesterol","arcad","inflammat"],"probe":"Which bodies are seen in the lining?"},{"q":"How will you treat it?","keywords":["root canal|rct|endodontic","apicectomy|apicoectomy|periapical surgery","enucleation","extraction|marsupial"],"probe":"Can a small radicular cyst heal without surgery?"}]'::jsonb, 'A 32-year-old woman has a discoloured, non-vital maxillary left central incisor that was traumatised years ago. An IOPA radiograph shows a well-defined, round, corticated radiolucency about 1.5 cm across at the apex.', array['inflammatory cyst']::text[]),
(4, 2, 'osmf', 'Oral Submucous Fibrosis', 'must_know', '10-mark essay', '{"definition":"A chronic, insidious, progressive, potentially malignant disorder of the oral mucosa, characterised by juxta-epithelial inflammation and progressive fibrosis of the submucosa, leading to stiffness and restricted mouth opening (Pindborg & Sirsat, 1966).","etiology":["Areca nut – arecoline stimulates fibroblasts; tannins/flavonoids inhibit collagenase; high copper increases lysyl oxidase activity","Chillies (capsaicin) – controversial","Nutritional deficiency – iron, vitamin B complex","Genetic and immunological factors (HLA associations)"],"classification":["Khanna & Andrade (surgical grouping): I very early; II early (opening 26–35 mm); III moderately advanced (15–26 mm); IVa advanced (< 15 mm, extensive fibrosis); IVb advanced with premalignant/malignant change"],"clinical_features":["Earliest symptom: burning sensation with spicy food; vesicles","Blanching (marble-like) of the mucosa; palpable vertical fibrous bands","Progressive restriction of mouth opening; difficulty in eating and speech","Shrunken, bud-like or hockey-stick uvula; depapillated tongue; hearing loss from Eustachian tube involvement"],"investigations":["Measure interincisal distance at every visit","Incisional biopsy to look for dysplasia","Haemoglobin, serum iron, B12"],"histopathology":["Atrophic epithelium with loss of rete ridges","Juxta-epithelial hyalinisation; dense collagen with reduced vascularity","Chronic inflammatory infiltrate; epithelial dysplasia in some cases"],"management":["Stop the habit – the single most important step","Nutritional and antioxidant supplements (lycopene, vitamins, iron)","Intralesional injections – dexamethasone or triamcinolone with hyaluronidase; pentoxifylline orally","Physiotherapy – mouth-opening exercises (ice-cream sticks, Heister''s jaw opener)","Surgery for advanced cases – fibrotomy with buccal pad of fat or nasolabial flap reconstruction","Lifelong follow-up for malignant transformation (reported around 7–13%)"],"viva_pearls":["Arecoline → fibroblast proliferation; copper → lysyl oxidase → collagen cross-linking.","OSMF is irreversible – treatment halts progression and improves opening, it does not cure."]}'::jsonb, '[{"q":"Define oral submucous fibrosis.","keywords":["chronic","progressive|insidious","fibrosis","submucosa|submucosal","potentially malignant|premalignant|precancer"],"probe":"Is it reversible, and is it a potentially malignant disorder?"},{"q":"What is its aetiology?","keywords":["areca|arecoline|betel","copper","chilli|capsaicin","nutrition|iron|vitamin","genetic|immun|hla"],"probe":"What is the role of copper in areca nut?"},{"q":"What are the clinical features?","keywords":["burning","blanch|marble","fibrous band|bands","mouth opening|trismus","uvula"],"probe":"What is usually the earliest complaint?"},{"q":"How will you manage this patient?","keywords":["stop|cessation|quit|habit","intralesional","hyaluronidase","steroid|dexamethasone|triamcinolone","physiotherapy|exercise","surgery|fibrotomy|buccal fat|buccal pad"],"probe":"Which drugs are given intralesionally, and what do you advise for mouth opening?"}]'::jsonb, 'A 28-year-old man who has chewed gutka for 8 years complains of a burning sensation with spicy food and gradually increasing difficulty opening his mouth. The interincisal opening is 22 mm, with palpable vertical fibrous bands in both buccal mucosae and a blanched soft palate.', array['OPMD','areca nut']::text[]),
(5, 2, 'leukoplakia', 'Oral Leukoplakia', 'must_know', '10-mark essay', '{"definition":"A predominantly white plaque of questionable risk, having excluded other known diseases or disorders that carry no increased risk for cancer (WHO / Warnakulasuriya 2007). It is a clinical, not a histological, term.","classification":["Homogeneous – uniformly flat, thin, white","Non-homogeneous – speckled (erythroleukoplakia), nodular, verrucous","Proliferative verrucous leukoplakia (PVL) – multifocal, highest malignant potential","OLEP staging uses size (L1–L3) and pathology (P0, P1)"],"etiology":["Tobacco (smoked and smokeless) – most important","Alcohol","Candida albicans (candidal leukoplakia)","Sanguinaria, UV light (lip), idiopathic"],"clinical_features":["Middle-aged and elderly men; buccal mucosa and commissure are most common in India","High-risk sites: floor of mouth, ventral/lateral tongue, soft palate","Usually asymptomatic; speckled forms may be sore"],"investigations":["Remove irritants and review in 2–4 weeks","Toluidine blue staining to select the biopsy site","Incisional biopsy from the most suspicious (red/nodular) area","Exfoliative / brush cytology as an adjunct"],"histopathology":["Hyperkeratosis (ortho- or para-), acanthosis","With or without epithelial dysplasia, graded mild / moderate / severe","Carcinoma in situ or early invasion in some"],"management":["Stop tobacco and alcohol","No dysplasia: monitor; medical therapy (retinoids, lycopene, beta-carotene) has limited evidence","Dysplasia: surgical excision, CO2 laser ablation or cryotherapy","Long-term follow-up – recurrence and new lesions are common"],"viva_pearls":["High-risk features: non-homogeneous type, high-risk site, dysplasia, female non-smoker, size > 200 mm², candidal infection, long duration.","Erythroplakia carries a much higher malignant potential than leukoplakia."]}'::jsonb, '[{"q":"Define leukoplakia.","keywords":["white","plaque|patch","questionable risk|risk","exclud|exclusion"],"probe":"Is it a clinical or a histological diagnosis? What must be excluded first?"},{"q":"Classify leukoplakia.","keywords":["homogeneous","non homogeneous|non-homogeneous|nonhomogeneous","speckled|erythroleukoplakia","nodular","verrucous|proliferative"],"probe":"What are the subtypes of the non-homogeneous form?"},{"q":"Which features suggest a higher risk of malignant transformation?","keywords":["non homogeneous|non-homogeneous|speckled","floor of mouth|ventral|tongue","dysplasia","female|non smoker|non-smoker","size|candida|duration"],"probe":"Think about type, site, histology and the patient."},{"q":"How will you manage this patient?","keywords":["tobacco|habit|cessation|stop","biopsy","excision|laser|cryo","follow|review"],"probe":"From where will you take the biopsy?"}]'::jsonb, 'A 55-year-old bidi smoker has a 2 × 3 cm white, slightly fissured patch on the left buccal mucosa near the commissure. It does not rub off and has a small red, granular area at one margin.', array['OPMD','tobacco']::text[]),
(6, 2, 'oral-lichen-planus', 'Oral Lichen Planus', 'must_know', '5-mark short note', '{"definition":"A chronic, T-cell–mediated immunological mucocutaneous disease affecting stratified squamous epithelium. WHO lists it as an oral potentially malignant disorder.","classification":["Reticular (most common – Wickham''s striae)","Papular","Plaque-like","Atrophic","Erosive / ulcerative","Bullous"],"clinical_features":["Middle-aged women","Bilateral, symmetrical lesions – buccal mucosa most common; tongue and gingiva (desquamative gingivitis)","Skin: 6 Ps – pruritic, purple, polygonal, planar papules and plaques; Koebner phenomenon","Erosive form causes burning and pain"],"investigations":["Incisional biopsy","Direct immunofluorescence – shaggy fibrinogen at the basement membrane","Rule out lichenoid reactions (drugs, amalgam contact)"],"histopathology":["Hyperkeratosis (parakeratosis) with saw-tooth rete ridges","Liquefaction (hydropic) degeneration of the basal cell layer","Dense band-like subepithelial lymphocytic infiltrate","Civatte (colloid) bodies; Max-Joseph spaces"],"management":["Asymptomatic reticular: reassurance and review","Symptomatic: topical corticosteroids (clobetasol, triamcinolone in orabase), topical tacrolimus","Severe / recalcitrant: systemic corticosteroids","Treat secondary candidiasis; replace amalgam in lichenoid reactions; follow up long term"],"viva_pearls":["Wickham''s striae = reticular OLP.","Civatte bodies are apoptotic keratinocytes."]}'::jsonb, '[{"q":"Define lichen planus.","keywords":["chronic","immun|t cell|t-cell","mucocutaneous"],"probe":"What type of immune mechanism is involved?"},{"q":"What are the oral clinical forms and features?","keywords":["wickham","reticular","erosive","bilateral|symmetrical","buccal mucosa"],"probe":"What are the striae called, and which is the most common type?"},{"q":"Describe the histopathology.","keywords":["saw tooth|saw-tooth","band like|band-like|band","lymphocyt","civatte|colloid","liquefaction|hydropic|basal"],"probe":"What happens to the basal cell layer?"},{"q":"How will you treat erosive lichen planus?","keywords":["corticosteroid|steroid","clobetasol|triamcinolone","tacrolimus","follow|review"],"probe":"Which topical agents would you prescribe?"}]'::jsonb, 'A 45-year-old woman has bilateral lace-like white striae on both buccal mucosae, with an erosive, painful area on the right side. She also has itchy purple papules on her wrists.', array['OPMD','immune-mediated']::text[]),
(7, 3, 'impacted-third-molar', 'Impacted Mandibular Third Molar', 'must_know', '10-mark essay', '{"definition":"An impacted tooth is one that fails to erupt into its normal functional position within the expected time because of an obstruction (adjacent tooth, bone or soft tissue) or an abnormal path of eruption.","classification":["Winter''s (angulation): mesioangular (most common), vertical, distoangular, horizontal, buccoangular, linguoangular, inverted","Pell & Gregory – relation to ramus: Class I, II, III","Pell & Gregory – depth relative to the occlusal plane: Position A, B, C","Winter''s WAR lines (White, Amber, Red) to judge depth and difficulty"],"clinical_features":["Recurrent pericoronitis (most common indication)","Caries or resorption of the second molar","Cyst or tumour formation","Orthodontic / prosthetic reasons; unexplained pain"],"investigations":["OPG / IOPA; CBCT if the roots are close to the inferior alveolar canal","Rood & Shehab signs (roots): darkening, deflection, narrowing, dark and bifid apex","Rood & Shehab signs (canal): interruption of the white lines, diversion, narrowing","Pederson difficulty index"],"management":["Ward''s or modified Ward''s incision, raise a mucoperiosteal flap","Bone removal (buccal guttering) and odontectomy – sectioning the crown or roots","Elevation, debridement, irrigation and closure","Coronectomy when the roots are intimately related to the IAN"],"viva_pearls":["Complications: dry socket, IAN / lingual nerve paraesthesia, trismus, bleeding, damage to adjacent tooth, mandibular fracture.","Most common impaction: mesioangular; most difficult: distoangular."]}'::jsonb, '[{"q":"How do you classify impacted mandibular third molars?","keywords":["winter","pell|gregory","mesioangular|angulation","ramus|occlusal plane|depth"],"probe":"Which classification uses the ramus and the occlusal plane?"},{"q":"What are Winter''s WAR lines?","keywords":["white","amber","red"],"probe":"Name the three lines and what each tells you."},{"q":"Which radiographic signs suggest proximity to the inferior alveolar canal?","keywords":["rood|shehab","darkening","deflection","narrowing","interruption|white line|diversion"],"probe":"List the root signs and the canal signs."},{"q":"What complications would you warn the patient about?","keywords":["dry socket|alveolar osteitis","paraesthesia|paresthesia|nerve|numbness","trismus","bleeding|haemorrhage|hemorrhage","fracture|swelling"],"probe":"Which nerves are at risk?"}]'::jsonb, 'A 22-year-old woman has recurrent pain and swelling around her lower right third molar region. The OPG shows a mesioangular impacted 48 at the level of the occlusal plane, partly within the ramus, with its roots overlapping the inferior alveolar canal.', array['exodontia','Winter','Pell & Gregory']::text[]),
(8, 3, 'le-fort-fractures', 'Le Fort Fractures of the Maxilla', 'must_know', '10-mark essay', '{"definition":"René Le Fort (1901) classified midface fractures from cadaver experiments into three patterns along lines of weakness. All three involve the pterygoid plates.","classification":["Le Fort I (Guérin / horizontal): above the apices – floor of nose, lateral maxillary walls, lower pterygoid plates; \"floating palate\"","Le Fort II (pyramidal): nasal bones, frontal process of maxilla, medial orbital wall, orbital floor, infraorbital margin, zygomaticomaxillary region, pterygoid plates","Le Fort III (craniofacial dysjunction): frontonasal and frontozygomatic sutures, orbital floor, zygomatic arch, pterygoid plates"],"clinical_features":["Guérin''s sign – ecchymosis at the greater palatine foramen (Le Fort I)","Anterior open bite with premature posterior contact; mobility of the maxilla","Dish-face deformity and lengthening of the face (II, III)","Circumorbital ecchymosis (\"raccoon eyes\"), step at the infraorbital margin (II), CSF rhinorrhoea (II, III)"],"investigations":["CT scan with axial, coronal and 3-D reconstruction (gold standard)","Occipitomental (Waters) view","Beta-2 transferrin test for CSF leak"],"management":["ATLS: airway, breathing, circulation, cervical spine first","Disimpaction with Rowe''s forceps; restore occlusion with intermaxillary fixation","Open reduction and internal fixation with miniplates along the vertical buttresses (nasomaxillary, zygomaticomaxillary, pterygomaxillary)","Manage CSF leak conservatively (head elevation, avoid nose blowing)"],"viva_pearls":["All Le Fort fractures involve the pterygoid plates.","CSF rhinorrhoea → avoid nasal intubation and nasogastric tubes."]}'::jsonb, '[{"q":"Classify Le Fort fractures.","keywords":["le fort i|guerin|guérin|horizontal","pyramidal","craniofacial dysjunction|dysjunction","pterygoid"],"probe":"Which structure is involved in all three types?"},{"q":"What clinical signs would you look for?","keywords":["guerin|guérin","open bite","dish face|dish-face","raccoon|circumorbital|periorbital","csf|rhinorrh","step"],"probe":"What is Guérin''s sign?"},{"q":"Which investigations will you order?","keywords":["ct|computed tomography","water|occipitomental","beta 2 transferrin|beta-2|transferrin"],"probe":"How would you confirm a CSF leak?"},{"q":"Outline the management.","keywords":["airway|abc|atls","occlusion|imf|mmf|intermaxillary","orif|miniplate|plate","buttress","rowe|disimpaction"],"probe":"Along which buttresses are plates placed?"}]'::jsonb, 'A 30-year-old man after a road traffic accident has bilateral circumorbital ecchymosis, an elongated "dish face", an anterior open bite and clear fluid dripping from the nose. The whole midface moves when the anterior maxilla is rocked.', array['trauma','midface']::text[]),
(9, 4, 'mta', 'Mineral Trioxide Aggregate (MTA)', 'must_know', '5-mark short note', '{"definition":"A hydrophilic calcium silicate–based cement developed by Mahmoud Torabinejad at Loma Linda University (1993), which sets in the presence of moisture and is highly biocompatible.","classification":["Grey MTA","White MTA (less iron, less discolouration)","Newer calcium silicates: Biodentine, BioAggregate, EndoSequence bioceramics"],"clinical_features":["Composition: tricalcium silicate, dicalcium silicate, tricalcium aluminate, tetracalcium aluminoferrite, calcium sulphate (gypsum), bismuth oxide (radiopacifier)","Mixed with sterile water in a 3:1 powder : liquid ratio","pH 10.2 on mixing, rising to about 12.5 at 3 hours","Setting time about 2 h 45 min (165 min); compressive strength increases over days"],"investigations":["Mechanism: hydration releases calcium hydroxide → Ca²⁺ and OH⁻ release, hydroxyapatite-like layer at the dentine interface, induction of cementum and dentine bridge"],"management":["Uses: direct pulp capping, pulpotomy, apexification (apical plug), root-end filling, perforation repair (furcal/lateral), resorption repair, regenerative endodontics barrier","Advantages: excellent seal, biocompatibility, sets in moisture, antibacterial (high pH), induces hard tissue","Disadvantages: long setting time, tooth discolouration (bismuth oxide), difficult handling, cost"],"viva_pearls":["Biodentine sets in about 12 minutes – a key advantage over MTA.","Place a moist cotton pellet over MTA when it is used in a single sitting under a temporary seal."]}'::jsonb, '[{"q":"What is MTA?","keywords":["calcium silicate|tricalcium silicate|silicate","torabinejad","hydrophilic|moisture"],"probe":"Who introduced it, and how does it behave with moisture?"},{"q":"What is its composition?","keywords":["tricalcium silicate","dicalcium silicate","aluminate","bismuth oxide","gypsum|calcium sulphate|calcium sulfate"],"probe":"What provides its radiopacity?"},{"q":"What are its important properties?","keywords":["ph|12.5","setting time|165|2 hours|2 h","biocompatib","seal","antibacterial|hard tissue"],"probe":"What are its pH and setting time?"},{"q":"List its clinical uses.","keywords":["perforation","apexification|apical plug","pulp capping","root end|root-end|retrograde","pulpotomy"],"probe":"Would you use it for perforation repair? What else?"}]'::jsonb, 'During access opening of tooth 36, a furcal perforation of about 1.5 mm is created. Bleeding is controlled. You decide to repair it in the same visit.', array['bioceramic','endodontics']::text[]),
(10, 5, 'gingival-enlargement', 'Drug-Induced Gingival Enlargement', 'desirable', '5-mark short note', '{"definition":"An increase in the size of the gingiva caused by certain systemic drugs, made worse by plaque-induced inflammation. \"Enlargement\" is preferred over hyperplasia or hypertrophy.","classification":["Carranza: inflammatory, drug-induced, associated with systemic conditions (conditioned or systemic disease), neoplastic, false enlargement","Grading: 0 – none; I – confined to interdental papilla; II – papilla and marginal gingiva; III – covering three-quarters or more of the crown"],"etiology":["Anticonvulsants – phenytoin (about half of patients), valproate","Immunosuppressants – cyclosporine","Calcium-channel blockers – nifedipine, amlodipine, diltiazem, verapamil"],"clinical_features":["Begins as painless, bead-like enlargement of the interdental papilla","Firm, pink, lobulated; does not bleed easily unless inflamed","More common anteriorly and on the labial surface; may interfere with speech and aesthetics"],"investigations":["Detailed drug history; consult the physician","Biopsy if the appearance is atypical"],"management":["Professional scaling and meticulous plaque control","Ask the physician to substitute the drug (e.g. tacrolimus for cyclosporine, another antihypertensive)","Azithromycin may help cyclosporine-induced enlargement","Surgical: gingivectomy (external bevel) or flap surgery; laser; recurrence is common if the drug continues"],"viva_pearls":["Mechanism: increased fibroblast collagen synthesis, reduced collagenase activity, reduced folic acid uptake (phenytoin); inflammation is a co-factor."]}'::jsonb, '[{"q":"Classify gingival enlargement.","keywords":["inflammatory","drug","systemic|conditioned","neoplastic","false"],"probe":"Give me Carranza''s classification."},{"q":"Name the drugs that cause it.","keywords":["phenytoin","cyclosporin","nifedipine|calcium channel","amlodipine|diltiazem|verapamil"],"probe":"Which three drug groups are classically implicated?"},{"q":"What is the mechanism?","keywords":["fibroblast","collagen","folic|folate","inflammation|plaque","collagenase"],"probe":"What is the role of plaque?"},{"q":"How will you manage it?","keywords":["plaque control|scaling|oral hygiene","substitut|change|physician","gingivectomy|flap","azithromycin|laser"],"probe":"Whom will you consult before stopping the drug?"}]'::jsonb, 'A 50-year-old hypertensive man on amlodipine has firm, pink, lobulated overgrowth of the interdental papillae covering about a third of the crowns of his anterior teeth. Plaque control is poor.', array['gingiva','drugs']::text[]),
(11, 6, 'kennedy-classification', 'Kennedy Classification & Applegate''s Rules', 'must_know', '5-mark short note', '{"definition":"Edward Kennedy (1925) classified partially edentulous arches by the location of the edentulous spaces relative to the remaining teeth. It is the most widely used classification for removable partial dentures.","classification":["Class I – bilateral edentulous areas posterior to the remaining teeth (bilateral distal extension)","Class II – unilateral edentulous area posterior to the remaining teeth (unilateral distal extension)","Class III – unilateral edentulous area with natural teeth both anterior and posterior to it (bounded)","Class IV – single, bilateral edentulous area anterior to the remaining teeth, crossing the midline","Applegate added Class V and Class VI"],"management":["Applegate''s 8 rules – e.g. classify after extractions; missing third molars not to be replaced are ignored; a third molar used as an abutment is considered","The most posterior edentulous area determines the class; other areas are modification spaces","Only the number of modification spaces counts, not their extent","Class IV has no modification spaces"],"clinical_features":["Class I & II: tooth–tissue supported – need functional impressions, indirect retainers, stress breakers / RPI design","Class III: tooth supported – anatomic impression is adequate"],"viva_pearls":["The question in this vignette (only 33–43 present) is Kennedy Class I."]}'::jsonb, '[{"q":"Describe Kennedy''s classification.","keywords":["bilateral distal|bilateral posterior|class i","unilateral distal|unilateral posterior|class ii","bounded|class iii","anterior|midline|class iv"],"probe":"What defines Class IV?"},{"q":"What are Applegate''s rules?","keywords":["applegate","extraction|after","third molar","most posterior","modification"],"probe":"Which area determines the class?"},{"q":"Which classes are tooth-supported and which are tooth–tissue supported? Why does it matter?","keywords":["tooth supported|tooth-supported|tooth borne","tissue|mucosa","functional impression|impression","indirect retainer|stress breaker|rpi"],"probe":"How does a distal extension change your impression technique?"}]'::jsonb, 'A 60-year-old patient has a mandibular arch with only 33 to 43 remaining and wants a removable partial denture.', array['RPD']::text[]),
(12, 7, 'pulpotomy-primary', 'Pulpotomy in Primary Teeth', 'desirable', '5-mark short note', '{"definition":"Removal of the coronal pulp, leaving the vital radicular pulp, which is treated with a medicament to preserve its vitality and function.","classification":["Devitalisation – formocresol","Preservation – ferric sulphate, glutaraldehyde","Regeneration – MTA, Biodentine, calcium hydroxide","Non-pharmacological – electrosurgery, laser"],"clinical_features":["Indications: carious or mechanical exposure of a vital primary tooth; haemorrhage controlled within about 5 minutes; no radiographic pathology; restorable tooth","Contraindications: spontaneous pain, swelling or sinus, pathological mobility, furcation radiolucency, internal/external resorption, uncontrollable bleeding"],"management":["LA and rubber dam → caries removal → de-roof the pulp chamber","Amputate the coronal pulp with a spoon excavator or large round bur","Haemostasis with a moist cotton pellet","Apply medicament: Buckley''s formocresol (1:5 dilution) for 5 min; ferric sulphate 15.5% for 15 s; or MTA","Zinc oxide eugenol base; final restoration with a stainless steel crown"],"viva_pearls":["Buckley''s formocresol: 19% formaldehyde, 35% cresol, 15% glycerine in water."]}'::jsonb, '[{"q":"Define pulpotomy.","keywords":["coronal pulp","radicular","vital|vitality","medicament"],"probe":"Which part of the pulp is removed and which is preserved?"},{"q":"What are the indications?","keywords":["vital","exposure","bleeding|haemorrhage|hemorrhage|haemostasis","no radiographic|radiograph","restorable"],"probe":"How long may bleeding continue before you abandon pulpotomy?"},{"q":"Name the medicaments used.","keywords":["formocresol","ferric sulphate|ferric sulfate","mta","biodentine","electrosurg|laser|glutaraldehyde"],"probe":"Which medicament acts by haemostasis through protein agglutination?"},{"q":"What is the composition of Buckley''s formocresol?","keywords":["19|formaldehyde","35|cresol","glycerine|glycerin","1:5|one fifth|dilution"],"probe":"Give the percentages."}]'::jsonb, 'A 6-year-old child has a deep carious lesion in 84 with a carious pulp exposure during excavation. There is no spontaneous pain, the bleeding stops with a moist cotton pellet in 3 minutes, and the radiograph shows no furcation involvement.', array['vital pulp therapy']::text[]),
(13, 8, 'dental-amalgam', 'Dental Amalgam', 'desirable', '10-mark essay', '{"definition":"An alloy of mercury with one or more other metals. Dental amalgam alloy is mainly silver and tin, with copper and sometimes zinc.","classification":["Copper content: low copper (< 6%) and high copper (> 6%) – admixed (dispersed) or single-composition (unicompositional)","Particle shape: lathe-cut, spherical, admixed","Zinc content: zinc-containing (> 0.01%) and zinc-free"],"clinical_features":["Low-copper setting: γ (Ag₃Sn) + Hg → γ₁ (Ag₂Hg₃) + γ₂ (Sn₇₋₈Hg) + unreacted γ","γ₂ is the weakest, most corrosion-prone phase","High-copper alloys eliminate γ₂ by forming Cu₆Sn₅ (η phase) – less creep, corrosion and marginal breakdown"],"etiology":["Delayed (secondary) expansion: zinc-containing alloy + moisture contamination during condensation → hydrogen gas → expansion after 3–5 days, pain and protrusion"],"management":["Manipulation: trituration → condensation → carving → burnishing → polishing after 24 hours","Mercury hygiene: well-ventilated surgery, pre-capsulated alloys, no-touch technique, amalgam separators, safe scrap storage","Minamata Convention (2013) – global phase-down of amalgam use"],"viva_pearls":["In this vignette the cause is delayed expansion: zinc + moisture contamination → H₂."]}'::jsonb, '[{"q":"Write the setting reaction of a low-copper amalgam.","keywords":["gamma|γ","gamma 1|γ1|ag2hg3","gamma 2|γ2|sn7|tin mercury","ag3sn"],"probe":"Name the γ, γ₁ and γ₂ phases."},{"q":"How do high-copper alloys improve amalgam?","keywords":["eliminat|no gamma 2|γ2","cu6sn5|eta|η","corrosion","creep|marginal"],"probe":"Which phase do they remove, and what forms instead?"},{"q":"What is delayed expansion?","keywords":["zinc","moisture|contamination|saliva","hydrogen"],"probe":"Which alloy component reacts with moisture?"},{"q":"What mercury-hygiene measures will you follow?","keywords":["ventilat","capsule|precapsulated|encapsulated","separator","minamata|no touch|gloves"],"probe":"What does the Minamata Convention say?"}]'::jsonb, 'A three-month-old Class II amalgam restoration in a patient''s molar is protruding from the cavity and shows surface blisters. The alloy used was a zinc-containing, low-copper lathe-cut alloy, and the field was not isolated.', array['restorative']::text[]),
(14, 9, 'local-anaesthetics', 'Local Anaesthetics', 'must_know', '10-mark essay', '{"definition":"Drugs that, when applied locally, reversibly block nerve conduction in a restricted area of the body without loss of consciousness.","classification":["Esters: cocaine, procaine, chloroprocaine, tetracaine, benzocaine – hydrolysed by plasma pseudocholinesterase","Amides: lignocaine, mepivacaine, prilocaine, bupivacaine, articaine, ropivacaine – metabolised in the liver (articaine also in plasma)"],"clinical_features":["Mechanism: the non-ionised base crosses the nerve membrane; inside, the ionised form blocks voltage-gated Na⁺ channels from the inner side","Frequency- and voltage-dependent block; small, myelinated fibres are blocked first","Order of loss: autonomic → pain → temperature → touch → pressure → motor"],"etiology":["Infection lowers tissue pH → more of the drug is ionised → less crosses the membrane → reduced effect"],"investigations":["Cartridge: lignocaine 2%, adrenaline 1:80,000–1:200,000 (vasoconstrictor), sodium metabisulphite (antioxidant), sodium chloride (isotonicity), water for injection","Maximum dose: lignocaine 4.4 mg/kg plain (max 300 mg); 7 mg/kg with adrenaline (max 500 mg)"],"management":["Toxicity: CNS excitation (circumoral numbness, tinnitus, tremors, convulsions) then depression; CVS depression","Bupivacaine is the most cardiotoxic; prilocaine causes methaemoglobinaemia (o-toluidine)","Treat toxicity: stop injection, airway and oxygen, benzodiazepine for seizures, lipid emulsion for cardiotoxicity"],"viva_pearls":["Quick rule: amides have two \"i\"s in the name (l-i-docaine, bup-i-vacaine).","Lower pKa → faster onset."]}'::jsonb, '[{"q":"Explain the mechanism of action of local anaesthetics.","keywords":["sodium|na+|na channel","channel","voltage","ionised|ionized|unionised|unionized|non ionised|non-ionised|non ionized","inside|intracellular|inner"],"probe":"Which form crosses the membrane and which form blocks the channel?"},{"q":"Classify them, and how are they metabolised?","keywords":["ester","amide","pseudocholinesterase|plasma cholinesterase|plasma","liver|hepatic"],"probe":"Where are amides metabolised?"},{"q":"What is in a lignocaine cartridge?","keywords":["lignocaine|lidocaine","adrenaline|epinephrine","metabisulphite|metabisulfite|bisulphite|bisulfite","sodium chloride","water"],"probe":"What is the role of sodium metabisulphite?"},{"q":"Why does LA fail in infected tissue?","keywords":["acid|ph","ionised|ionized","less|reduced|fail|decrease","pka|base|membrane"],"probe":"Think about tissue pH and the ionised fraction."},{"q":"What are the signs of LA toxicity, and what is the maximum dose here?","keywords":["cns|convulsion|seizure|tinnitus|circumoral","cardio|cvs|arrhythm|depression","methaemoglobin|methemoglobin|prilocaine","7 mg|420|maximum dose|max"],"probe":"Calculate the maximum lignocaine dose with adrenaline for 60 kg."}]'::jsonb, 'You are about to give an inferior alveolar nerve block for a 40-year-old, 60 kg patient with an acute periapical abscess in 46. She asks why her previous injection "did not work" when the tooth was swollen.', array['LA','lignocaine']::text[]),
(15, 10, 'adc-anaphylaxis', 'Anaphylaxis in the Dental Chair', 'must_know', 'ADC practical – medical emergency', '{"definition":"A severe, potentially life-threatening systemic hypersensitivity reaction of rapid onset, with airway, breathing or circulation problems, usually with skin or mucosal changes.","etiology":["Common dental triggers: latex, antibiotics (e.g. penicillins), chlorhexidine, NSAIDs","True allergy to amide local anaesthetics is very rare – reactions are more often vasovagal or adrenaline effects"],"clinical_features":["Skin/mucosa: urticaria, flushing, angioedema of lips, tongue and face","Airway/breathing: hoarse voice, stridor, wheeze, shortness of breath","Circulation: tachycardia, hypotension, pale and floppy (children), collapse","Gastrointestinal: abdominal pain, vomiting"],"management":["Stop treatment and remove the trigger (take out the latex dam)","Call for help and an ambulance (000)","Lay the patient flat – do not let them stand or walk; sit up only if breathing is difficult","Adrenaline 0.01 mg/kg IM (max 0.5 mg; 0.5 mL of 1:1000) into the anterolateral thigh; repeat every 5 minutes if needed","Oxygen; start CPR if unresponsive and not breathing normally","Transfer to hospital for observation (biphasic reactions), document fully, and refer to a clinical immunologist"],"viva_pearls":["Antihistamines do not treat airway swelling or shock – adrenaline first.","Flag latex allergy in the record and plan latex-free care."]}'::jsonb, '[{"q":"What is your diagnosis and why?","keywords":["anaphylaxis","latex","wheeze|bronchospasm|breathing","hypotension|blood pressure|low bp","angioedema|swelling|urticaria"],"probe":"Which systems are involved, and what is the likely trigger?"},{"q":"What are your immediate actions?","keywords":["remove|stop","help|ambulance|000","flat|lie|supine","adrenaline|epinephrine","oxygen"],"probe":"How will you position her, and who will you call?"},{"q":"Give the adrenaline dose, concentration and route.","keywords":["0.5 mg|0.5mg|500 microgram|0.01 mg/kg","1:1000|1 in 1000","intramuscular|im","thigh","repeat|5 minutes|five minutes"],"probe":"Where exactly do you inject it, and when can you repeat it?"},{"q":"What happens after she recovers?","keywords":["hospital|observation|biphasic","document|record","immunolog|allergist|referral","latex free|latex-free|alert"],"probe":"Why must she still go to hospital?"}]'::jsonb, 'A 34-year-old woman becomes flushed and wheezy, with swelling of her lips, 3 minutes after you place a latex rubber dam. Her pulse is 124/min and blood pressure 80/50 mmHg.', array['ADC','medical emergency']::text[]),
(16, 10, 'adc-consent-notification', 'Consent, Material Risk & Mandatory Notification', 'must_know', 'ADC – ethics & law', '{"definition":"Valid consent is voluntary, informed, specific to the procedure, and given by a person with capacity. In Australia, Rogers v Whitaker (1992) requires practitioners to warn of material risks.","classification":["Implied, verbal and written consent","Mature minors can consent when they fully understand the treatment (Gillick principle, adopted in Marion''s case)","Substitute decision-makers for adults without capacity, as set out by state and territory law"],"clinical_features":["Discuss the diagnosis and the proposed treatment","Explain the risks, both common and serious (e.g. inferior alveolar nerve injury causing numbness)","Explain the alternatives, including coronectomy and no treatment","Discuss cost (informed financial consent) and invite questions"],"management":["\"Do whatever you think is best\" is not informed consent – explain, check understanding and give time","Use a professional interpreter where needed rather than family members","Record the discussion, the risks explained and the patient''s decision","The patient can withdraw consent at any time"],"viva_pearls":["Material risk (Rogers v Whitaker): one a reasonable person in the patient''s position would consider significant, or one the practitioner knows this particular patient would.","Mandatory notification to AHPRA covers practising while intoxicated, sexual misconduct, impairment placing the public at substantial risk, and a significant departure from accepted professional standards."]}'::jsonb, '[{"q":"What makes consent valid?","keywords":["voluntary","inform","capacity|competent|competence","specific"],"probe":"Name the four elements."},{"q":"Which case defines material risk in Australia, and what does it say?","keywords":["rogers|whitaker","material","reasonable person|reasonable patient","particular patient|this patient|significance|significant"],"probe":"Is it judged by what other dentists would do, or by the patient?"},{"q":"What will you discuss with this patient before extracting the tooth?","keywords":["nerve|paraesthesia|paresthesia|numbness","alternative|coronectomy|no treatment","cost|fee|financial","benefit|reason","question|understand"],"probe":"What are her options besides extraction?"},{"q":"When must a dentist make a mandatory notification, and to whom?","keywords":["ahpra","intoxicat|alcohol|drug","sexual","impairment","departure|professional standards"],"probe":"List the four types of notifiable conduct."}]'::jsonb, 'A 52-year-old woman asks you to remove a lower third molar whose roots lie close to the inferior alveolar canal. She is anxious and says, "Just do whatever you think is best."', array['ADC','ethics','AHPRA']::text[]),
(17, 10, 'adc-avulsion', 'Avulsion of a Permanent Incisor', 'must_know', 'ADC – dental trauma', '{"definition":"Complete displacement of a tooth out of its socket. Prognosis depends mainly on extra-oral dry time, the storage medium and the stage of root development.","management":["Phone advice: find the tooth, hold it by the crown, rinse briefly if dirty (do not scrub the root) and replant immediately; otherwise store in milk, saline or saliva and come in at once","In the clinic: rinse with saline, replant with gentle pressure, check the position on a radiograph, and place a flexible splint for about 2 weeks","Open apex: allow a chance of pulp revascularisation and monitor closely; closed apex: start root canal treatment within 2 weeks","Systemic antibiotics (amoxicillin or penicillin in children; doxycycline only over 12 years), check tetanus status, chlorhexidine mouthwash, soft diet","Follow-up: 2 weeks, 4 weeks, 3 months, 6 months, 1 year, then yearly"],"clinical_features":["Dry time over 60 minutes: periodontal ligament cells are non-viable, so replacement resorption (ankylosis) is expected","Avulsed primary teeth are not replanted"],"viva_pearls":["Milk is the best widely available storage medium; Hank''s balanced salt solution is better if available.","IADT guidelines (2020) are the reference for dental trauma management."]}'::jsonb, '[{"q":"What should the mother have been told on the phone?","keywords":["replant","crown|hold","milk|saline|saliva","scrub|touch the root|rinse","immediately|straight away|urgent|at once"],"probe":"How should she handle and store the tooth?"},{"q":"How will you manage this in the clinic?","keywords":["saline|rinse","replant","radiograph|x ray|x-ray","flexible|splint","2 weeks|two weeks"],"probe":"What type of splint, and for how long?"},{"q":"What about the pulp in this 9-year-old?","keywords":["open apex|immature|incomplete","revascular|pulp healing","monitor|review|follow","root canal|endodontic"],"probe":"How does root development change your plan?"},{"q":"What medication and aftercare will you give?","keywords":["antibiotic|amoxicillin|penicillin|doxycycline","tetanus","chlorhexidine|mouthwash","soft diet","follow up|follow-up|review"],"probe":"Which antibiotic is suitable for a 9-year-old, and why not doxycycline?"}]'::jsonb, 'A 9-year-old was hit by a cricket ball 30 minutes ago. His mother has brought the avulsed upper right central incisor wrapped in a dry tissue.', array['ADC','trauma','IADT']::text[]),
(18, 1, 'oral-squamous-cell-carcinoma', 'Oral Squamous Cell Carcinoma', 'must_know', '10-mark essay', '{"definition":"A malignant epithelial neoplasm arising from the oral mucosal epithelium and showing squamous differentiation. It accounts for over 90% of oral cancers.","etiology":["Tobacco – smoked, and smokeless (gutka, khaini, betel quid)","Alcohol (synergistic with tobacco)","Areca nut","Human papillomavirus (HPV-16), especially in the oropharynx","Potentially malignant disorders: leukoplakia, erythroplakia, OSMF","UV light (lower lip); immunosuppression"],"clinical_features":["Commonest site in India: gingivobuccal sulcus and buccal mucosa (tobacco-quid habit); in the West: lateral tongue and floor of mouth","Non-healing ulcer with rolled, everted, indurated margins, or an exophytic growth or a red/white patch","Loose teeth, lip paraesthesia, trismus (spread into bone, nerve, muscle)","Hard, fixed cervical lymph nodes"],"classification":["TNM staging (AJCC 8th edition): depth of invasion is part of T stage; extranodal extension is part of N stage","Broders histological grading: well, moderately and poorly differentiated"],"investigations":["Incisional biopsy from the edge of the lesion (toluidine blue can guide the site)","CT/MRI for local extent; OPG for bone involvement","FNAC of nodes; PET-CT for advanced disease"],"histopathology":["Islands and cords of malignant squamous cells invading the connective tissue","Keratin pearls and individual cell keratinisation (well differentiated)","Nuclear and cellular pleomorphism, hyperchromatism, abnormal mitoses","Pattern at the invasive front predicts behaviour"],"management":["Surgery: wide excision with about 1 cm clinical margins; marginal or segmental mandibulectomy when bone is involved","Neck dissection: selective, modified radical or radical depending on nodal status","Reconstruction: radial forearm, anterolateral thigh, fibula or pectoralis major flaps","Adjuvant radiotherapy or chemoradiotherapy (cisplatin) for high-risk features such as positive margins or extranodal extension","Dental care before radiotherapy (extract unsaveable teeth 2–3 weeks earlier, fluoride trays) to reduce osteoradionecrosis risk"],"viva_pearls":["Gingivobuccal (\"Indian oral cancer\") reflects the tobacco-quid habit.","Biopsy from the margin, not the necrotic centre."]}'::jsonb, '[{"q":"Define oral squamous cell carcinoma.","keywords":["malignant","epithelial|epithelium|squamous","mucosa|mucosal|oral"],"probe":"From which tissue does it arise?"},{"q":"What are the aetiological factors?","keywords":["tobacco|gutka|khaini","alcohol","areca|betel","hpv|papilloma","leukoplakia|potentially malignant|premalignant"],"probe":"Which virus is linked to oropharyngeal cancer?"},{"q":"Describe the clinical features of this lesion.","keywords":["ulcer|non healing|non-healing","everted|rolled","indurat","lymph node|lymphadenopathy","fixed|hard"],"probe":"Describe the margins and the lymph nodes."},{"q":"Describe the histopathology and grading.","keywords":["keratin pearl","pleomorph","invasion|invasive|islands","broders","well|moderately|poorly"],"probe":"Which grading system do you know?"},{"q":"How will you manage this patient?","keywords":["excision|resection|mandibulectomy","margin","neck dissection","radiotherapy|chemo","reconstruct|flap"],"probe":"What do you do with the neck?"}]'::jsonb, 'A 58-year-old man who has chewed tobacco for 30 years has a non-healing ulcer in the left gingivobuccal sulcus for 3 months. It has rolled, everted, indurated margins, and there is a hard, fixed left submandibular lymph node.', array['oral cancer','tobacco']::text[]),
(19, 1, 'pleomorphic-adenoma', 'Pleomorphic Adenoma', 'must_know', '5-mark short note', '{"definition":"The most common salivary gland tumour: a benign \"mixed tumour\" of epithelial and myoepithelial cells in a mesenchymal-like (myxoid, chondroid) stroma.","clinical_features":["Parotid (superficial lobe) is the commonest site; the palate is the commonest intraoral site","30–50 years, female predilection","Painless, slow-growing, firm, rubbery, mobile swelling","Facial nerve weakness or rapid growth suggests malignant change"],"investigations":["FNAC and ultrasound; MRI for deep-lobe tumours","Avoid open incisional biopsy of a parotid lump (tumour seeding)"],"histopathology":["Incomplete fibrous capsule with pseudopod-like extensions","Ductal epithelial cells and myoepithelial cells (plasmacytoid, spindle, clear)","Myxoid, chondroid and hyalinised stroma"],"management":["Superficial parotidectomy with facial nerve preservation (total parotidectomy for deep lobe)","Never enucleate: pseudopods and capsule rupture cause recurrence","Palatal tumours: wide excision including the overlying periosteum","Complications of parotid surgery: facial nerve injury, Frey syndrome (gustatory sweating)"],"viva_pearls":["Long-standing tumours can transform: carcinoma ex pleomorphic adenoma.","Warthin tumour is the second most common parotid tumour."]}'::jsonb, '[{"q":"What is pleomorphic adenoma?","keywords":["benign","mixed","salivary","epithelial|myoepithelial","stroma|chondroid|myxoid"],"probe":"Why is it called a mixed tumour?"},{"q":"Where does it occur and how does it present?","keywords":["parotid","palate","painless","slow","firm|rubbery|mobile"],"probe":"What is the commonest intraoral site?"},{"q":"Describe the histopathology.","keywords":["capsule","pseudopod","myoepithelial","ductal|duct","chondroid|myxoid"],"probe":"What is special about the capsule?"},{"q":"How is it treated, and why not enucleation?","keywords":["superficial parotidectomy|parotidectomy","facial nerve","recurrence","pseudopod|capsule","frey"],"probe":"Which nerve must be preserved, and what late complication can occur?"}]'::jsonb, 'A 40-year-old woman has a painless, firm, rubbery swelling in front of the left ear that has grown slowly for 4 years. Facial nerve function is normal.', array['salivary gland tumour']::text[]),
(20, 2, 'pemphigus-vulgaris', 'Pemphigus Vulgaris', 'must_know', '10-mark essay', '{"definition":"A chronic autoimmune vesiculobullous disease in which IgG autoantibodies against desmoglein 3 (and desmoglein 1) cause loss of keratinocyte adhesion (acantholysis) and an intraepithelial blister.","clinical_features":["40–60 years","Oral lesions are often the first sign: flaccid bullae rupture quickly to leave painful, ragged erosions","Positive Nikolsky sign","Skin: flaccid bullae and crusted erosions"],"investigations":["Perilesional biopsy for H&E and direct immunofluorescence","Serum indirect immunofluorescence and ELISA for anti-desmoglein 1 and 3","Tzanck smear shows acantholytic (Tzanck) cells"],"histopathology":["Suprabasal (intraepithelial) cleft with acantholysis","Basal cells stay attached to the basement membrane – \"row of tombstones\"","DIF: intercellular IgG and C3 in a \"fishnet\" / \"chicken-wire\" pattern"],"management":["Refer to dermatology; systemic corticosteroids (prednisolone)","Steroid-sparing agents: azathioprine, mycophenolate; rituximab for moderate to severe disease","Topical steroids and good oral hygiene for oral lesions","Differential: mucous membrane pemphigoid – subepithelial split, linear basement-membrane IgG/C3"],"viva_pearls":["Intraepithelial split = pemphigus; subepithelial split = pemphigoid."]}'::jsonb, '[{"q":"What is pemphigus vulgaris?","keywords":["autoimmune","desmoglein","acantholysis","intraepithelial|suprabasal"],"probe":"Against which protein are the antibodies directed?"},{"q":"What clinical sign would you elicit?","keywords":["nikolsky","bullae|blister","erosion","flaccid"],"probe":"How do you elicit it?"},{"q":"Describe the histopathology and immunofluorescence.","keywords":["suprabasal","acantholy|tzanck","tombstone","fishnet|chicken wire|intercellular","igg"],"probe":"What pattern does direct immunofluorescence show?"},{"q":"How will you manage it, and how does it differ from pemphigoid?","keywords":["steroid|prednisolone","azathioprine|mycophenolate|rituximab","pemphigoid","subepithelial"],"probe":"Where is the split in pemphigoid?"}]'::jsonb, 'A 48-year-old woman has painful, ragged oral erosions for 2 months. Rubbing the normal-looking buccal mucosa near a lesion causes the epithelium to peel off.', array['vesiculobullous','autoimmune']::text[]),
(21, 2, 'trigeminal-neuralgia', 'Trigeminal Neuralgia', 'must_know', '5-mark short note', '{"definition":"Unilateral, paroxysmal, brief, electric-shock-like pain in the distribution of one or more divisions of the trigeminal nerve, triggered by innocuous stimuli.","etiology":["Classical: neurovascular compression of the trigeminal root, most often by the superior cerebellar artery","Secondary: multiple sclerosis (young, sometimes bilateral), cerebellopontine angle tumours"],"clinical_features":["Usually over 50 years; more common in women","Mandibular and maxillary divisions most often affected","Trigger zones: touching the face, shaving, brushing, eating","Attacks last seconds to 2 minutes, with refractory periods; no sensory loss in classical TN"],"investigations":["Clinical diagnosis","MRI to look for compression or a secondary cause","Diagnostic local anaesthetic block of the trigger zone"],"management":["Carbamazepine is the drug of choice; monitor blood counts, liver function and sodium; HLA-B*1502 screening in Asian patients (risk of SJS/TEN)","Alternatives: oxcarbazepine, baclofen, gabapentin, lamotrigine","Surgery: microvascular decompression (Jannetta)","Percutaneous procedures: radiofrequency rhizotomy, glycerol injection, balloon compression; gamma-knife radiosurgery","Peripheral options: alcohol injection, cryotherapy, peripheral neurectomy"],"viva_pearls":["Pain with sensory loss, or in a young patient, points to secondary TN – get an MRI."]}'::jsonb, '[{"q":"Define trigeminal neuralgia.","keywords":["unilateral","paroxysmal|sudden","electric|shock|lancinating","trigeminal"],"probe":"Describe the character and duration of the pain."},{"q":"What causes it?","keywords":["vascular|artery|compression","superior cerebellar","multiple sclerosis","tumour|tumor"],"probe":"Which vessel is usually responsible?"},{"q":"What is the drug of choice and what must you monitor?","keywords":["carbamazepine","blood count|cbc|haematolog|liver","hla","oxcarbazepine|baclofen|gabapentin"],"probe":"Which genetic test is advised in Asian patients?"},{"q":"What surgical options exist?","keywords":["microvascular decompression","rhizotomy|radiofrequency","glycerol|balloon","gamma knife|radiosurgery","neurectomy|alcohol"],"probe":"Which surgery addresses the cause?"}]'::jsonb, 'A 62-year-old woman has sudden, electric-shock-like pain in the right lower lip and chin, lasting seconds, triggered by brushing her teeth. Between attacks she is pain-free and sensation is normal.', array['orofacial pain']::text[]),
(22, 5, 'periodontitis-staging-grading', 'Periodontitis: 2017 Staging & Grading', 'must_know', '10-mark essay', '{"definition":"The 2017 World Workshop (AAP/EFP) classifies periodontitis by Stage (severity and complexity, I–IV), Grade (rate of progression, A–C) and Extent (localised, generalised, molar–incisor pattern).","classification":["Stage I: interdental CAL 1–2 mm, bone loss < 15% (coronal third), no tooth loss, probing depth ≤ 4 mm","Stage II: CAL 3–4 mm, bone loss 15–33%, no tooth loss, probing depth ≤ 5 mm, mostly horizontal bone loss","Stage III: CAL ≥ 5 mm, bone loss into the middle third or beyond, ≤ 4 teeth lost; probing depth ≥ 6 mm, vertical defects ≥ 3 mm, furcation class II/III","Stage IV: as Stage III plus ≥ 5 teeth lost, or a need for complex rehabilitation (masticatory dysfunction, bite collapse, < 20 remaining teeth)","Grade A: % bone loss ÷ age < 0.25, non-smoker, no diabetes","Grade B: 0.25–1.0, smoker < 10 cigarettes/day, HbA1c < 7%","Grade C: > 1.0, smoker ≥ 10/day or HbA1c ≥ 7%","Extent: localised < 30% of teeth, generalised ≥ 30%, or molar–incisor pattern"],"management":["Step 1: oral hygiene instruction, risk-factor control (smoking cessation, glycaemic control), supragingival debridement","Step 2: subgingival instrumentation (scaling and root planing) ± adjuncts","Step 3: re-evaluate; periodontal surgery for residual deep pockets","Step 4: supportive periodontal therapy at regular recall"],"viva_pearls":["Stage is set by the worst interdental site; complexity factors can raise the stage.","Grade is shifted upward by smoking and diabetes."]}'::jsonb, '[{"q":"What are the components of the 2017 classification of periodontitis?","keywords":["stage","grade","extent|localised|generalised","severity|complexity","progression|rate"],"probe":"What does the stage describe, and what does the grade describe?"},{"q":"What stage is this patient, and why?","keywords":["stage iii|stage 3|three","attachment loss|cal|5 mm|6 mm","middle third","tooth loss|lost 2|four or fewer"],"probe":"Look at CAL, bone loss and tooth loss."},{"q":"What grade is this patient?","keywords":["grade c|c","smok|10 cigarettes","bone loss|age","1.0|ratio"],"probe":"How do smoking and the bone loss/age ratio affect the grade?"},{"q":"Outline the steps of treatment.","keywords":["oral hygiene|risk factor|smoking cessation","scaling|root planing|subgingival","surgery|surgical","maintenance|supportive|recall"],"probe":"What comes after non-surgical therapy?"}]'::jsonb, 'A 42-year-old who smokes 15 cigarettes a day has interdental attachment loss of 6 mm on several molars, bone loss to the middle third of the roots, and has lost 2 molars to periodontitis. Bone loss on the worst tooth is about 50%.', array['2017 classification']::text[]),
(23, 4, 'dental-caries', 'Dental Caries', 'must_know', '10-mark essay', '{"definition":"A biofilm-mediated, sugar-driven, multifactorial, dynamic disease that causes alternating demineralisation and remineralisation of dental hard tissues, leading to net mineral loss.","etiology":["Keyes'' triad – host (tooth), microflora, substrate – with time added by Newbrun","Miller''s chemoparasitic (acidogenic) theory, 1890; proteolysis and proteolysis–chelation theories","Ecological plaque hypothesis (Marsh)","Streptococcus mutans initiates; lactobacilli drive progression; Actinomyces in root caries","Critical pH: about 5.5 for enamel; the Stephan curve shows pH fall after sugar"],"classification":["G.V. Black classes by site","Pit and fissure, smooth surface and root caries","Acute (rampant), chronic, arrested and secondary (recurrent) caries","ICDAS II codes 0–6; Mount and Hume site/size system"],"clinical_features":["White spot lesion – the earliest clinically visible sign (reversible)","Brown spot, then cavitation"],"investigations":["Visual-tactile examination on clean, dry teeth","Bitewing radiographs","Transillumination (FOTI), laser fluorescence (DIAGNOdent)","Caries risk assessment (e.g. CAMBRA)"],"histopathology":["Enamel lesion zones (from the advancing front): translucent zone, dark zone, body of the lesion, surface zone","Dentine zones: fatty degeneration of Tomes'' fibres, dentinal sclerosis, decalcification, bacterial invasion, decomposed dentine"],"management":["Prevention: fluoride, fissure sealants, diet counselling","Remineralisation of non-cavitated lesions (fluoride varnish, CPP-ACP)","Minimal intervention: selective caries removal, then restoration"],"viva_pearls":["The surface zone of an enamel lesion stays relatively intact – the reason white spots can remineralise."]}'::jsonb, '[{"q":"Define dental caries.","keywords":["biofilm|plaque","sugar|carbohydrate","multifactorial","demineralisation|demineralization","dynamic|remineralisation|remineralization"],"probe":"Is it a static or a dynamic process?"},{"q":"Explain its aetiology.","keywords":["keyes|triad","host|tooth","microflora|bacteria|mutans","substrate|sugar","time"],"probe":"Who added time to the triad?"},{"q":"Which theories of caries do you know?","keywords":["miller|acidogenic|chemoparasitic","proteolysis","chelation","ecological"],"probe":"Who proposed the chemoparasitic theory?"},{"q":"Describe the zones of an enamel lesion.","keywords":["translucent","dark","body","surface"],"probe":"Start from the advancing front."},{"q":"How would you manage these white spot lesions?","keywords":["fluoride|varnish","diet","remineral","cpp|casein","sealant|monitor"],"probe":"Do they need drilling?"}]'::jsonb, 'A 19-year-old student who sips sweetened tea through the day has chalky white spots along the gingival margins of several teeth and a cavitated lesion on the occlusal surface of 36.', array['caries','cariology']::text[]),
(24, 4, 'root-canal-irrigants', 'Root Canal Irrigants', 'desirable', '5-mark short note', '{"definition":"Solutions used during cleaning and shaping to flush debris, dissolve pulp tissue, kill microorganisms and remove the smear layer from areas instruments cannot reach.","classification":["Sodium hypochlorite 0.5–5.25%: dissolves organic tissue and is strongly antibacterial; does not remove the inorganic smear layer","EDTA 17%: chelator that removes the inorganic part of the smear layer; final rinse for about 1 minute","Chlorhexidine 2%: substantivity, effective against Enterococcus faecalis; does not dissolve tissue","MTAD (doxycycline, citric acid, detergent); saline as an inert flush"],"management":["Use a side-vented 30-gauge needle 1–2 mm short of working length, never binding in the canal; gentle pressure","Activate irrigants with sonic or ultrasonic agitation, or negative-pressure systems","NaOCl followed directly by chlorhexidine forms a brown precipitate (para-chloroaniline): flush with saline or alcohol in between","NaOCl accident: stop, reassure, give local anaesthetic and analgesics, cold compresses first then warm, antibiotics if infection is likely, and refer urgently if the airway is threatened"],"viva_pearls":["Ideal irrigant: tissue-dissolving, antibacterial, removes smear layer, non-toxic to periapical tissue – no single irrigant does all."]}'::jsonb, '[{"q":"Why do we irrigate root canals?","keywords":["debris|flush","dissolve|tissue","antibacterial|microorganisms|disinfect","smear layer","lubricat"],"probe":"Name four functions."},{"q":"Compare sodium hypochlorite, EDTA and chlorhexidine.","keywords":["hypochlorite|naocl","dissolv","edta|chelat","smear layer","chlorhexidine|substantivity"],"probe":"Which one removes the smear layer?"},{"q":"What happens if you use NaOCl and chlorhexidine one after the other?","keywords":["precipitate","brown|orange","chloroaniline|pca","saline|alcohol|flush"],"probe":"How do you prevent it?"},{"q":"This patient has had a hypochlorite accident. How will you manage it?","keywords":["stop|reassure","analgesic|anaesthe","cold|ice|compress","antibiotic","refer|airway|hospital"],"probe":"What do you do if the swelling threatens the airway?"}]'::jsonb, 'While irrigating a lower premolar with sodium hypochlorite, your patient suddenly complains of severe burning pain, and the cheek starts to swell within seconds.', array['endodontics']::text[]),
(25, 7, 'fluorides', 'Fluorides in Dentistry', 'must_know', '10-mark essay', '{"definition":"Fluoride prevents caries mainly by a topical, post-eruptive action: it enhances remineralisation (forming fluorhydroxyapatite), inhibits demineralisation and interferes with bacterial metabolism (enolase).","classification":["Systemic: community water fluoridation (about 0.7 ppm; lower in hot climates), salt and milk fluoridation, supplements","Professional topical: 1.23% APF gel (12,300 ppm, pH about 3.5, 4 minutes); 2% NaF (Knutson technique: 4 applications a week apart at ages 3, 7, 11, 13); 8% SnF₂; 5% NaF varnish (22,600 ppm); 38% silver diamine fluoride (arrests caries, stains black)","Self-applied: toothpaste 1000–1500 ppm (a rice-grain smear under 3 years, pea-sized from 3 to 6 years), mouthrinses"],"clinical_features":["Acute toxicity doses: probably toxic dose 5 mg F/kg (needs hospital care); safely tolerated dose 8–16 mg/kg; certainly lethal dose 32–64 mg/kg in adults","Chronic excess in childhood causes dental fluorosis (graded by Dean''s index); skeletal fluorosis with high, long-term intake"],"management":["Calculate the dose: 100 g × 1 mg F/g = 100 mg F ÷ 16 kg ≈ 6.25 mg/kg – above the probably toxic dose","Give milk or another calcium source to bind fluoride and send the child to hospital at once","Below 5 mg/kg: oral calcium (milk) and observe for a few hours"],"viva_pearls":["1000 ppm = 1 mg fluoride per gram of toothpaste."]}'::jsonb, '[{"q":"How does fluoride prevent caries?","keywords":["topical|post eruptive|posteruptive","remineral","demineral","fluorapatite|fluorhydroxyapatite","enolase|bacteria"],"probe":"Is the main action systemic or topical?"},{"q":"List the professionally applied topical fluorides.","keywords":["apf|acidulated","sodium fluoride|naf|knutson","stannous|snf","varnish|duraphat","silver diamine|sdf"],"probe":"What is Knutson''s technique?"},{"q":"What are the toxic doses of fluoride?","keywords":["probably toxic|ptd|5 mg","safely tolerated|std","certainly lethal|cld|32"],"probe":"What is the probably toxic dose?"},{"q":"How will you manage this child?","keywords":["calculate|mg/kg|6","milk|calcium","hospital|emergency","observe|monitor"],"probe":"Work out the dose this child took."}]'::jsonb, 'A 4-year-old weighing 16 kg swallowed most of a 100 g tube of 1000 ppm fluoride toothpaste about 20 minutes ago. The parent calls your clinic.', array['prevention','public health']::text[]),
(26, 7, 'behaviour-management', 'Behaviour Management in Children', 'must_know', '10-mark essay', '{"definition":"The set of communication and clinical techniques used to build trust, reduce fear and enable safe, effective dental care for a child, with a positive attitude to dentistry as the long-term goal.","classification":["Frankl scale: 1 definitely negative, 2 negative, 3 positive, 4 definitely positive","Wright''s classification: cooperative, lacking cooperative ability, potentially cooperative"],"management":["Communication: age-appropriate language, euphemisms, active listening","Tell-show-do (Addelston): explain, demonstrate, then perform","Positive reinforcement, distraction, modelling (a sibling or video), desensitisation","Voice control and parental presence/absence (with informed consent)","Protective stabilisation only when necessary, with consent and documentation; hand-over-mouth is no longer an accepted technique","Pharmacological: nitrous oxide–oxygen inhalation sedation (100% oxygen for 3–5 minutes afterwards to prevent diffusion hypoxia), oral midazolam, general anaesthesia for extensive treatment or non-cooperative children"],"viva_pearls":["Start with simple, non-invasive work (prophylaxis, fluoride) on the first visit to build trust."]}'::jsonb, '[{"q":"How do you classify child behaviour?","keywords":["frankl","definitely negative|definitely positive","wright","potentially cooperative|lacking cooperative"],"probe":"Give me the Frankl scale."},{"q":"What is tell-show-do?","keywords":["tell","show","do","addelston","explain|demonstrat"],"probe":"Who introduced it, and how is it done?"},{"q":"Which other non-pharmacological techniques will you use for this child?","keywords":["positive reinforcement|praise","distraction","modelling|modeling","voice control","desensiti|parental presence"],"probe":"Name at least four."},{"q":"If he still cannot cooperate, what are your pharmacological options?","keywords":["nitrous oxide|inhalation","diffusion hypoxia|100% oxygen","midazolam|oral sedation","general anaesthesia|general anesthesia"],"probe":"What must you give at the end of nitrous oxide sedation?"}]'::jsonb, 'A 5-year-old on his first dental visit hides behind his mother, cries and refuses to open his mouth. He needs restorations in two primary molars.', array['child psychology']::text[]),
(27, 11, 'angle-classification', 'Angle''s Classification of Malocclusion', 'must_know', '5-mark short note', '{"definition":"Edward Angle (1899) classified malocclusion by the anteroposterior relationship of the permanent first molars, which he called the \"key to occlusion\".","classification":["Class I: the mesiobuccal cusp of the maxillary first molar occludes in the buccal groove of the mandibular first molar","Class II: the mandibular arch is distal – the mesiobuccal cusp lies mesial to (ahead of) the buccal groove","Class II division 1: proclined maxillary incisors with increased overjet","Class II division 2: retroclined maxillary central incisors, often with flared laterals and a deep bite","Subdivision: the Class II or III relation exists on one side only","Class III: the mandibular arch is mesial to the maxillary arch"],"clinical_features":["Drawbacks: considers only the anteroposterior plane (ignores vertical and transverse)","Describes dental, not skeletal, relationships","Assumes the first molar position is fixed; cannot be used when first molars are missing"],"management":["Other systems: Dewey''s modification (types of Class I), Ackerman–Proffit (Venn diagram), Simon''s three planes, incisor classification (BSI), canine relationship"],"viva_pearls":["This case is Class II division 1 (molars distal bilaterally, proclined incisors, increased overjet)."]}'::jsonb, '[{"q":"What is Angle''s classification based on?","keywords":["first molar|molar","key to occlusion","anteroposterior|sagittal","mesiobuccal cusp","buccal groove"],"probe":"Which tooth did Angle call the key to occlusion?"},{"q":"Describe Class II and its divisions.","keywords":["distal","division 1|proclined","division 2|retroclined","overjet|deep bite","subdivision"],"probe":"How do the incisors differ between the two divisions?"},{"q":"Classify this patient.","keywords":["class ii|class 2","division 1|div 1","bilateral|both sides","overjet"],"probe":"Look at the molars and the incisors."},{"q":"What are the drawbacks of Angle''s classification?","keywords":["anteroposterior only|vertical|transverse","skeletal","missing molar|molar missing","fixed|stable"],"probe":"Which planes does it ignore?"}]'::jsonb, 'A 12-year-old has proclined upper incisors with a 9 mm overjet. With the teeth together, the mesiobuccal cusp of the upper first molar sits mesial to the buccal groove of the lower first molar on both sides.', array['malocclusion']::text[]),
(28, 3, 'mandibular-fractures', 'Fractures of the Mandible', 'must_know', '10-mark essay', '{"definition":"A break in the continuity of the mandible. Its site and direction decide how the muscles displace the fragments and how it is treated.","classification":["By site: condyle, coronoid, ramus, angle, body, parasymphysis, symphysis, dentoalveolar","Favourable or unfavourable, horizontally and vertically, depending on whether muscle pull holds the fragments together or pulls them apart","Simple, compound, comminuted, greenstick, pathological"],"clinical_features":["Step deformity and derangement of occlusion; abnormal mobility; pain and trismus","Sublingual haematoma (Coleman''s sign) in body and parasymphysis fractures","Paraesthesia of the lower lip from inferior alveolar nerve injury","Bilateral parasymphyseal fracture: the tongue can fall back and obstruct the airway","Bilateral condylar fractures: anterior open bite; unilateral: chin deviates to the injured side"],"investigations":["OPG; PA mandible; reverse Towne view for condyles; CT for complex or condylar fractures"],"management":["ATLS: airway first (pull the tongue forward in flail anterior segments), control bleeding, check the cervical spine","Closed reduction and intermaxillary fixation (arch bars, eyelet wiring) for about 4–6 weeks","Open reduction and internal fixation with monocortical miniplates along Champy''s ideal lines of osteosynthesis","Condyle: mostly conservative or closed treatment (especially in children); ORIF for specific indications (e.g. displacement into the middle cranial fossa, inability to restore occlusion)","Antibiotics for compound fractures; assess teeth in the fracture line"],"viva_pearls":["A step between 33 and 34 with lip numbness suggests a body/parasymphysis fracture involving the mental or inferior alveolar nerve."]}'::jsonb, '[{"q":"How do you classify mandibular fractures?","keywords":["condyle|condylar","angle","body|parasymphysis|symphysis","favourable|favorable|unfavourable","compound|comminuted|simple"],"probe":"What makes a fracture favourable?"},{"q":"What signs would you look for?","keywords":["step","occlusion|bite","sublingual haematoma|sublingual hematoma|coleman","paraesthesia|paresthesia|numbness","mobility"],"probe":"What is Coleman''s sign?"},{"q":"Which radiographs will you take?","keywords":["opg|orthopantomogram|panoramic","pa mandible|posteroanterior","towne","ct|computed tomography"],"probe":"Which view shows the condyles best?"},{"q":"How will you treat this fracture?","keywords":["airway|atls","imf|mmf|intermaxillary|arch bar","orif|open reduction|miniplate","champy","antibiotic"],"probe":"Where do you place the miniplates?"}]'::jsonb, 'A 24-year-old was assaulted. He has a step in the lower teeth between 33 and 34, a sublingual haematoma, numbness of the left lower lip and a deranged bite.', array['trauma']::text[]),
(29, 3, 'ludwigs-angina', 'Ludwig''s Angina', 'must_know', '10-mark essay', '{"definition":"A rapidly spreading, bilateral cellulitis (not a localised abscess) involving the submandibular, sublingual and submental spaces, which can rapidly obstruct the airway.","etiology":["Mostly odontogenic – mandibular second and third molars, whose roots lie below the mylohyoid line","Mixed streptococci and oral anaerobes","Risk factors: diabetes, immunosuppression, poor oral hygiene"],"clinical_features":["Bilateral, brawny, board-like swelling of the floor of the mouth and neck","Elevated, protruding tongue; drooling; dysphagia; trismus","Muffled \"hot potato\" voice, stridor, fever and toxicity"],"investigations":["Assess the airway first; CT neck with contrast when safe","Blood count, glucose, cultures of pus"],"management":["Secure the airway: awake fibreoptic intubation or tracheostomy under local anaesthesia","High-dose IV antibiotics (e.g. amoxicillin–clavulanate or penicillin with metronidazole; clindamycin if allergic)","Early surgical decompression: incision and drainage of all involved spaces, with drains","Remove the source (extract the offending tooth), IV fluids, control blood sugar, ICU care"],"viva_pearls":["Complications: airway obstruction, descending mediastinitis, septicaemia – this is an emergency."]}'::jsonb, '[{"q":"What is Ludwig''s angina?","keywords":["cellulitis","bilateral","submandibular","sublingual","submental"],"probe":"Which three spaces are involved, and is it an abscess?"},{"q":"Why do lower molars cause it?","keywords":["mylohyoid","below|apices|roots","second|third molar","submandibular"],"probe":"Relate the root apices to the mylohyoid muscle."},{"q":"What is your first priority?","keywords":["airway","intubation|fibreoptic|fiberoptic","tracheostomy"],"probe":"How will you secure the airway if intubation is difficult?"},{"q":"Describe the rest of the management.","keywords":["antibiotic|amoxicillin|penicillin|clindamycin|metronidazole","incision|drainage|decompression","extract|remove the source","fluids|icu|glucose"],"probe":"Is antibiotic therapy alone enough?"}]'::jsonb, 'A 35-year-old with a decayed 37 has a hard, board-like swelling under both sides of the jaw. The tongue is raised, he is drooling, his voice is muffled and he cannot swallow saliva. Temperature 39 °C.', array['fascial space infection','emergency']::text[]),
(30, 6, 'jaw-relations', 'Jaw Relations in Complete Dentures', 'must_know', '10-mark essay', '{"definition":"Jaw relation is any spatial relationship of the mandible to the maxilla. It is recorded as orientation (face-bow), vertical (VDO and VDR) and horizontal (centric and eccentric) relations.","classification":["Orientation relation: face-bow transfer (arbitrary or kinematic)","Vertical relations: vertical dimension at rest (VDR) and in occlusion (VDO)","Horizontal relations: centric relation and eccentric relations (protrusive, lateral)"],"investigations":["VDO = VDR minus the freeway space (about 2–4 mm)","Vertical dimension methods: physiological rest position, phonetics (\"S\" sounds – closest speaking space; \"M\" to find rest), swallowing, facial measurements (Willis gauge, Niswonger), pre-extraction records","Centric relation methods: Gothic arch (needle-point) tracing, interocclusal records, swallowing and tongue-retrusion techniques"],"clinical_features":["Increased VDO: clicking teeth during speech, sore ridges, strained face, loss of freeway space","Decreased VDO: collapsed lips, angular cheilitis, reduced chewing efficiency, possible TMJ symptoms (Costen''s syndrome)"],"viva_pearls":["Centric relation is a bone-to-bone, reproducible, physiological position – the starting point for complete denture occlusion."]}'::jsonb, '[{"q":"What are jaw relations, and how are they classified?","keywords":["spatial relationship|relationship of mandible","orientation|face bow|face-bow","vertical","horizontal|centric"],"probe":"Name the three groups."},{"q":"How do you determine the vertical dimension?","keywords":["rest|physiologic","freeway space|interocclusal","phonetic|s sound|speech","swallowing","willis|niswonger|facial measurement"],"probe":"What is the freeway space?"},{"q":"What happens with an increased or decreased VDO?","keywords":["clicking|click","sore|ridge","angular cheilitis","collapsed|lips","costen|tmj"],"probe":"Which patient in the case has which error?"},{"q":"How do you record centric relation?","keywords":["gothic arch|needle point|arrow point","interocclusal|record","swallowing|tongue","reproducible|retruded"],"probe":"What does the apex of a Gothic arch tracing represent?"}]'::jsonb, 'A new complete denture patient complains that his teeth "click" when he talks, his ridges are sore and his face looks strained. In another patient the lips look collapsed and there is angular cheilitis.', array['complete denture']::text[]),
(31, 1, 'dentigerous-cyst', 'Dentigerous (Follicular) Cyst', 'must_know', '5-mark short note', '{"definition":"A developmental odontogenic cyst that encloses the crown of an unerupted tooth and is attached at its cemento-enamel junction. It forms by fluid accumulation between the reduced enamel epithelium and the crown. It is the most common developmental odontogenic cyst.","classification":["Radiographic variants: central (crown symmetrically enclosed), lateral, circumferential","Eruption cyst: the soft-tissue counterpart over an erupting tooth"],"clinical_features":["2nd–3rd decade","Mandibular third molars, then maxillary canines","Usually painless; found on radiographs; can cause expansion, displacement of teeth and root resorption"],"investigations":["Well-defined, corticated unilocular radiolucency around the crown, attached at the CEJ","Follicular space wider than about 3–5 mm suggests a cyst rather than a normal follicle","Histology needed to exclude OKC or unicystic ameloblastoma"],"histopathology":["Thin, non-keratinised stratified squamous epithelium, 2–4 cell layers thick, with a flat interface (uninflamed)","Mucous cells, ciliated cells and Rushton bodies may be seen","Fibrous capsule; may contain odontogenic epithelial rests"],"management":["Enucleation with removal of the associated tooth","Marsupialisation (decompression) for large cysts or in children, to let the tooth erupt","Send the lining for histology"],"viva_pearls":["Potential complications: unicystic ameloblastoma, squamous cell carcinoma, mucoepidermoid carcinoma arising in the lining."]}'::jsonb, '[{"q":"Define dentigerous cyst.","keywords":["crown","unerupted|impacted","cemento enamel|cementoenamel|cej","reduced enamel epithelium|enamel epithelium","developmental"],"probe":"Where is it attached to the tooth?"},{"q":"Describe the radiographic features.","keywords":["unilocular","radiolucen","crown","corticat|well defined|well-defined","central|lateral|circumferential"],"probe":"What are the radiographic variants?"},{"q":"Describe the histopathology.","keywords":["non keratin|non-keratin|nonkeratin","thin|2|4 cell","flat","mucous|rushton|ciliated"],"probe":"How thick is the lining?"},{"q":"How will you treat it, and what complications can arise?","keywords":["enucleation","marsupial|decompression","ameloblastoma","carcinoma|mucoepidermoid"],"probe":"When would you choose marsupialisation?"}]'::jsonb, 'A 22-year-old has an unerupted lower right third molar. The OPG shows a well-defined, corticated unilocular radiolucency, about 2 cm across, surrounding the crown and attached at the cemento-enamel junction.', array['odontogenic cyst','impacted tooth']::text[]),
(32, 1, 'fibrous-dysplasia', 'Fibrous Dysplasia of the Jaws', 'must_know', '5-mark short note', '{"definition":"A benign fibro-osseous condition in which normal bone is replaced by cellular fibrous tissue containing irregular woven bone. It results from a post-zygotic activating mutation of the GNAS gene.","classification":["Monostotic (most common; maxilla more often than mandible)","Polyostotic","McCune–Albright syndrome: polyostotic disease, café-au-lait spots (\"coast of Maine\") and endocrinopathy such as precocious puberty","Jaffe–Lichtenstein: polyostotic disease with café-au-lait spots"],"clinical_features":["Children and adolescents","Painless, slow, unilateral expansion causing facial asymmetry","Growth usually slows or stops after skeletal maturity"],"investigations":["Ground-glass (orange-peel) opacity with ill-defined margins blending into normal bone","Narrowing of the PDL space and loss of lamina dura; maxillary lesions can obliterate the sinus","CT for extent; biopsy for confirmation"],"histopathology":["Cellular fibrous stroma with irregular, curved trabeculae of woven bone (\"Chinese letter\" pattern)","Trabeculae lack osteoblastic rimming","Lesional bone fuses with surrounding normal bone (no capsule)"],"management":["Observation for small, stable lesions","Surgical recontouring for cosmetic or functional problems, ideally after growth stops","Bisphosphonates for bone pain in polyostotic disease","Avoid radiotherapy (risk of sarcomatous change)"],"viva_pearls":["Ossifying fibroma differs: well-defined, encapsulated, can be enucleated."]}'::jsonb, '[{"q":"What is fibrous dysplasia?","keywords":["fibro osseous|fibro-osseous|fibrous","woven bone|bone replaced","gnas","benign"],"probe":"Which gene mutation causes it?"},{"q":"Classify fibrous dysplasia.","keywords":["monostotic","polyostotic","mccune|albright","cafe|café|pigment","precocious|endocrin"],"probe":"What is McCune–Albright syndrome?"},{"q":"What are the radiographic features?","keywords":["ground glass|ground-glass|orange peel","ill defined|ill-defined|blend","lamina dura|pdl|periodontal ligament","sinus|expansion"],"probe":"How are the margins?"},{"q":"Describe the histopathology and management.","keywords":["chinese letter|trabeculae","osteoblastic rimming|rimming","recontour|shave","radiotherapy|radiation"],"probe":"Why avoid radiotherapy?"}]'::jsonb, 'A 14-year-old girl has a slowly enlarging, painless swelling of the left maxilla causing facial asymmetry. The radiograph shows an ill-defined "ground-glass" opacity that blends into normal bone.', array['fibro-osseous lesion']::text[]),
(33, 3, 'dry-socket', 'Dry Socket & Complications of Extraction', 'must_know', '5-mark short note', '{"definition":"Alveolar osteitis (dry socket) is post-extraction pain from partial or total loss of the blood clot, leaving exposed bone. It is caused by fibrinolysis of the clot (Birn''s theory).","etiology":["Risk factors: mandibular third molar surgery, traumatic or difficult extraction, smoking, oral contraceptives, previous dry socket, poor oral hygiene","Excessive rinsing or spitting, and vasoconstrictor-heavy local anaesthesia, are also blamed"],"clinical_features":["Onset 2–4 days after extraction","Severe, throbbing pain radiating to the ear and temple, not relieved by ordinary analgesics","Empty socket with exposed bone, halitosis and bad taste; no fever or pus (unlike infection)"],"management":["Rule out a retained root or fracture radiographically if needed","Gentle irrigation with warm saline or chlorhexidine – no curettage","Place an obtundent dressing (e.g. zinc oxide eugenol on gauze, or Alvogyl); change every 1–2 days as needed","Analgesics (NSAIDs); antibiotics are not routinely needed","Prevention: atraumatic technique, chlorhexidine rinse, stopping smoking around the extraction"],"viva_pearls":["Other complications of extraction: haemorrhage, fracture of the tooth or alveolus, oro-antral communication, nerve injury, trismus, displacement into spaces, TMJ dislocation."]}'::jsonb, '[{"q":"What is dry socket?","keywords":["alveolar osteitis","clot","fibrinoly","exposed bone|bare bone"],"probe":"What happens to the clot?"},{"q":"What are the risk factors?","keywords":["third molar|mandibular","trauma|difficult","smok","contracept|ocp","previous"],"probe":"Which hormonal factor increases risk?"},{"q":"How does it present?","keywords":["2|3|4 days|third day","severe|throbbing","ear|radiat","empty socket|exposed","halitosis|foul|bad taste"],"probe":"When does the pain start?"},{"q":"How will you manage it?","keywords":["irrigat|saline","dressing|alvogyl|zinc oxide eugenol|zoe","analgesic|nsaid","no curettage|not curette|avoid curettage"],"probe":"Would you curette the socket?"}]'::jsonb, 'Three days after a difficult extraction of 38, a 30-year-old smoker returns with severe throbbing pain radiating to the ear and a foul taste. The socket is empty with exposed grey bone.', array['exodontia','alveolar osteitis']::text[]),
(34, 6, 'complete-denture-impressions', 'Complete Denture Impressions', 'must_know', '10-mark essay', '{"definition":"A complete denture impression is a negative record of the edentulous denture-bearing tissues, made to achieve retention, stability and support while preserving the ridges and giving good aesthetics.","classification":["Mucocompressive (pressure) theory","Mucostatic theory (Page) – tissues recorded at rest","Selective pressure theory (Boucher) – pressure on stress-bearing areas, relief over sensitive areas; most widely used"],"management":["Primary impression in a stock tray (impression compound or alginate) → diagnostic cast → custom (special) tray","Border moulding with low-fusing (green-stick) compound or polyether/silicone, section by section, to record functional sulcus depth and width","Final (secondary) impression with zinc oxide eugenol paste, light-bodied elastomer or impression plaster","Record the posterior palatal seal area on the maxillary cast (vibrating lines)"],"clinical_features":["Mandibular primary stress-bearing area: buccal shelf","Relief areas – maxilla: incisive papilla, mid-palatine raphe, torus palatinus if present","Relief areas – mandible: sharp crest of a resorbed ridge, mental foramen, genial tubercles, torus mandibularis"],"viva_pearls":["Objectives of an impression (Boucher): retention, stability, support, aesthetics and preservation of the remaining tissues."]}'::jsonb, '[{"q":"What are the objectives of a complete denture impression?","keywords":["retention","stability","support","aesthetic|esthetic","preserv"],"probe":"Name the five objectives."},{"q":"Explain the impression theories.","keywords":["mucocompressive|pressure","mucostatic","selective pressure","boucher|page"],"probe":"Which theory do most clinicians follow?"},{"q":"Describe the steps from primary to final impression.","keywords":["primary|stock tray","special tray|custom tray","border mould|border mold","green stick|compound","zinc oxide eugenol|zoe|final|secondary"],"probe":"What material do you use for border moulding?"},{"q":"Which areas are stress-bearing and which need relief?","keywords":["buccal shelf","incisive papilla","mid palatine raphe|midpalatine|raphe","mental foramen|genial|torus"],"probe":"What is the primary stress-bearing area in the mandible?"}]'::jsonb, 'A 68-year-old edentulous patient has well-formed maxillary and moderately resorbed mandibular ridges. You are making new complete dentures.', array['complete denture']::text[]),
(35, 4, 'obturation', 'Obturation of the Root Canal', 'must_know', '10-mark essay', '{"definition":"Obturation is the three-dimensional filling of the cleaned and shaped root canal system with a core material and sealer, to create a fluid-tight seal and prevent re-infection.","clinical_features":["When to obturate: tooth asymptomatic, canal dry with no exudate or odour, sinus tract (if any) healed"],"classification":["Core material: gutta-percha (cones in the beta phase; thermoplasticised alpha phase), resin-based materials","Sealers: zinc oxide eugenol, epoxy resin (e.g. AH Plus), calcium hydroxide, bioceramic (calcium silicate)","Techniques: cold lateral condensation (most widely taught), warm vertical compaction (Schilder), single-cone with bioceramic sealer, thermoplasticised injection (e.g. Obtura), carrier-based (e.g. Thermafil)"],"investigations":["Radiographic criteria: obturation ending 0.5–1 mm short of the radiographic apex (at the apical constriction), dense, without voids, tapering continuously, and following the canal shape"],"management":["Cold lateral condensation: fit a master cone to working length with tug-back, coat with sealer, use spreaders to create space and add accessory cones, sear off and condense vertically at the orifice","Seal the access cavity coronally without delay – coronal leakage is a major cause of failure"],"viva_pearls":["Overextension = material beyond the apex, regardless of seal; overfill = beyond the apex AND the canal is fully filled."]}'::jsonb, '[{"q":"What is obturation, and when is a canal ready for it?","keywords":["three dimensional|3d|three-dimensional","seal|fluid tight|fluid-tight","asymptomatic","dry|no exudate"],"probe":"What clinical conditions must be met?"},{"q":"Which materials are used?","keywords":["gutta percha|gutta-percha","sealer","zinc oxide eugenol|zoe","epoxy|ah plus|resin","bioceramic|calcium silicate|calcium hydroxide"],"probe":"Name some sealer types."},{"q":"Describe cold lateral condensation.","keywords":["master cone","tug back|tug-back","spreader","accessory cone","sear|condense"],"probe":"What is tug-back?"},{"q":"What are the radiographic criteria of good obturation?","keywords":["0.5|1 mm short|short of the apex|apical constriction","dense|no voids","taper","coronal seal|coronal leakage"],"probe":"Where should the filling end?"}]'::jsonb, 'You have cleaned and shaped the canals of 46. The patient is asymptomatic, the canals are dry and there is no exudate. You plan to obturate today.', array['endodontics']::text[]),
(36, 7, 'space-maintainers', 'Space Maintainers', 'must_know', '10-mark essay', '{"definition":"Appliances that preserve the space left by the premature loss of a primary tooth, so that the successor can erupt and the arch length is not lost.","classification":["Hitchcock: fixed or removable; functional or non-functional; active or passive; banded or bonded","Fixed: band and loop, crown and loop, distal shoe, lingual arch, Nance palatal arch, transpalatal arch","Removable: acrylic partial denture-type maintainers"],"clinical_features":["Space loss is fastest in the first 6 months after extraction","Indications: premature loss with the successor present and not about to erupt (less than half its root formed, or covered by bone)","Contraindications: adequate space with the successor about to erupt, or the successor missing (plan for prosthesis or closure)"],"management":["Single primary first or second molar lost (first permanent molar erupted): band and loop","Primary second molar lost before the first permanent molar erupts: distal shoe (intra-alveolar guide)","Bilateral loss in the mandible after permanent incisors erupt: lingual holding arch","Bilateral loss in the maxilla: Nance palatal arch or transpalatal arch","Review every 3–6 months; remove once the successor erupts"],"viva_pearls":["In this case the first permanent molar has erupted, so a band and loop on 46 is suitable."]}'::jsonb, '[{"q":"What are space maintainers and why are they needed?","keywords":["premature loss","space","successor|permanent tooth","arch length|drift|migration"],"probe":"What happens if you leave the space?"},{"q":"Classify space maintainers.","keywords":["fixed","removable","functional","active|passive","hitchcock"],"probe":"Whose classification is this?"},{"q":"Which appliance suits which situation?","keywords":["band and loop","distal shoe","lingual arch","nance","transpalatal"],"probe":"When is a distal shoe used?"},{"q":"Which appliance will you give this child, and how will you follow up?","keywords":["band and loop","review|follow up|follow-up|recall","remove|eruption"],"probe":"Has the first permanent molar erupted?"}]'::jsonb, 'A 6-year-old has just had 75 (lower right primary second molar) extracted. The lower first permanent molar has erupted and the premolar is still deep in bone.', array['interceptive']::text[]),
(37, 11, 'cleft-lip-palate', 'Cleft Lip and Palate', 'must_know', '10-mark essay', '{"definition":"A congenital defect from failure of fusion of the medial nasal process with the maxillary process (lip and primary palate) and/or of the palatal shelves (secondary palate). It affects roughly 1 in 700 live births.","classification":["Veau: I – soft palate only; II – hard and soft palate; III – complete unilateral cleft of lip and palate; IV – complete bilateral cleft","Kernahan''s \"striped Y\" symbolic classification"],"clinical_features":["Feeding difficulty (needs special bottles and nipples)","Speech problems: hypernasality, nasal escape","Hearing: middle-ear effusion from Eustachian tube dysfunction","Dental: missing or malformed lateral incisor, supernumerary teeth, crossbite, maxillary hypoplasia"],"management":["Multidisciplinary cleft team: surgeon, orthodontist, paediatric dentist, speech therapist, ENT, paediatrician, counsellor","Pre-surgical nasoalveolar moulding (NAM) in the first weeks","Lip repair at about 3 months (\"rule of 10s\": 10 weeks, 10 lb, haemoglobin 10 g/dL)","Palate repair at about 9–18 months, before speech develops","Alveolar bone grafting at about 9–11 years, before the canine erupts","Orthodontics and, if needed, orthognathic surgery after growth is complete"],"viva_pearls":["Veau class III = this baby (complete unilateral cleft of lip and palate)."]}'::jsonb, '[{"q":"What is the embryological basis of cleft lip and palate?","keywords":["fusion|failure","medial nasal","maxillary process","palatal shelves|palatal processes"],"probe":"Which processes fail to fuse in cleft lip?"},{"q":"Classify clefts.","keywords":["veau","soft palate","unilateral","bilateral","kernahan|striped y"],"probe":"Which Veau class is this baby?"},{"q":"What problems will this child face?","keywords":["feeding","speech|hypernasal","hearing|ear|otitis","dental|lateral incisor|crossbite","maxillary hypoplasia|growth"],"probe":"Which ear problem is common?"},{"q":"Outline the treatment timeline.","keywords":["team|multidisciplinary","nasoalveolar|nam","lip repair|3 months|rule of 10","palate repair|9|18 months","bone graft|alveolar"],"probe":"When is alveolar bone grafting done, and why then?"}]'::jsonb, 'A newborn has a complete unilateral cleft of the left lip and the palate. The parents ask what treatment their baby will need and when.', array['congenital','team care']::text[]),
(38, 11, 'functional-appliances', 'Functional Appliances', 'desirable', '10-mark essay', '{"definition":"Appliances that use or modify the forces of the orofacial musculature to influence skeletal growth and tooth position, mainly to correct Class II malocclusion in growing patients.","classification":["Removable: activator (Andresen), bionator (Balters), Frankel function regulator (tissue-borne), twin block (Clark)","Fixed: Herbst appliance, Forsus and other fixed functional devices","Myotonic vs myodynamic; tooth-borne vs tissue-borne"],"clinical_features":["Indications: growing patient (ideally around the pubertal growth spurt), Class II with a retrognathic mandible, good compliance","Growth status assessed with hand–wrist radiographs or cervical vertebral maturation (CVM) stages"],"management":["Construction bite: mandible postured forward (often 5–7 mm, within about 70% of maximum protrusion) with a few millimetres of vertical opening","Effects: forward mandibular positioning and possible growth enhancement, restraint of maxillary growth, retroclination of upper incisors and proclination of lower incisors","Usually followed by fixed appliances to detail the occlusion"],"viva_pearls":["How much true extra mandibular growth functional appliances produce is still debated; much of the correction is dentoalveolar."]}'::jsonb, '[{"q":"What are functional appliances?","keywords":["muscle|musculature|orofacial","growth","growing","class ii|class 2"],"probe":"In which patients do they work?"},{"q":"Classify functional appliances.","keywords":["activator|andresen","bionator|balters","frankel","twin block|clark","herbst|fixed"],"probe":"Which one is tissue-borne?"},{"q":"What is a construction bite?","keywords":["forward|advance|protru","vertical|opening","mm|millimetre|millimeter","posture"],"probe":"How far forward do you posture the mandible?"},{"q":"What are the effects, and when is the best time to treat?","keywords":["mandible|mandibular","maxilla|restrain","incisor|retroclin|proclin","growth spurt|pubertal|cvm|cervical vertebr"],"probe":"How do you judge the growth spurt?"}]'::jsonb, 'An 11-year-old boy in his pre-pubertal growth phase has a skeletal Class II division 1 malocclusion with a retrognathic mandible and an overjet of 10 mm.', array['growth modification','Class II']::text[]),
(39, 12, 'diabetes-dental', 'Diabetes Mellitus: Dental Considerations', 'must_know', '10-mark essay', '{"definition":"A group of metabolic diseases characterised by chronic hyperglycaemia from defective insulin secretion, insulin action, or both.","classification":["Type 1 (autoimmune β-cell destruction)","Type 2 (insulin resistance with relative deficiency – most common)","Gestational diabetes; other specific types"],"investigations":["Fasting plasma glucose ≥ 126 mg/dL, 2-hour OGTT ≥ 200 mg/dL, random ≥ 200 mg/dL with symptoms, or HbA1c ≥ 6.5% (diagnostic thresholds)","HbA1c reflects control over the previous 2–3 months; a usual treatment target is about < 7%","Check capillary glucose before treatment"],"clinical_features":["Oral: periodontitis (a two-way relationship), periodontal abscesses, xerostomia, candidiasis, burning mouth, delayed healing, increased infection risk","Systemic: polyuria, polydipsia, polyphagia; retinopathy, nephropathy, neuropathy, cardiovascular disease"],"management":["Schedule morning appointments after the patient has eaten and taken usual medication; keep them short and stress-free","Have glucose available; recognise hypoglycaemia (sweating, tremor, confusion) and give 15–20 g fast-acting glucose if conscious","Poorly controlled patients (like this HbA1c of 9.2%): liaise with the physician, defer elective surgery, consider antibiotic cover for invasive procedures","Periodontal therapy can modestly improve glycaemic control (HbA1c)"],"viva_pearls":["Hypoglycaemia in the chair is more immediately dangerous than hyperglycaemia."]}'::jsonb, '[{"q":"Define diabetes mellitus and give its types.","keywords":["hyperglyc","insulin","type 1","type 2","gestational"],"probe":"What is the basic defect in type 2?"},{"q":"How is it diagnosed, and what does HbA1c tell you?","keywords":["fasting|126","hba1c|glycated","6.5","2|3 months|three months","ogtt|200"],"probe":"Over how long does HbA1c reflect control?"},{"q":"What are the oral manifestations?","keywords":["periodont","xerostomia|dry mouth","candid","healing","abscess|infection"],"probe":"How are diabetes and periodontitis related?"},{"q":"How will you plan this patient''s treatment safely?","keywords":["morning|after breakfast|eaten","glucose|sugar","hypoglyc","physician|consult","antibiotic|defer|elective"],"probe":"What will you do if he becomes sweaty and confused in the chair?"}]'::jsonb, 'A 52-year-old with type 2 diabetes (on metformin and insulin, last HbA1c 9.2%) needs extractions and periodontal treatment. He has generalised deep pockets and recurrent gum abscesses.', array['medically compromised']::text[]),
(40, 13, 'shock', 'Shock', 'must_know', '10-mark essay', '{"definition":"Shock is acute circulatory failure that causes inadequate tissue perfusion and oxygenation, leading to cellular hypoxia and organ dysfunction.","classification":["Hypovolaemic: haemorrhage, burns, dehydration","Cardiogenic: myocardial infarction, arrhythmia","Distributive: septic, anaphylactic, neurogenic","Obstructive: tension pneumothorax, cardiac tamponade, massive pulmonary embolism"],"clinical_features":["Tachycardia, hypotension, narrow pulse pressure","Cold, clammy, pale skin (early septic shock can be warm)","Oliguria (< 0.5 mL/kg/hour), altered sensorium, raised respiratory rate","Shock index (heart rate ÷ systolic BP) above 1 suggests significant shock","ATLS haemorrhage classes I–IV: hypotension usually appears in class III (30–40% blood loss)"],"management":["ABC: secure the airway, give high-flow oxygen, control bleeding by direct pressure","Two large-bore IV cannulae; send blood for cross-match, Hb, lactate","Fluid resuscitation with warmed crystalloid, then blood products for haemorrhage","Treat the cause: stop bleeding, antibiotics and source control in sepsis, adrenaline in anaphylaxis, vasopressors (noradrenaline) in septic shock","Monitor pulse, BP, urine output (catheter), mental state and lactate"],"viva_pearls":["This patient is in hypovolaemic (haemorrhagic) shock, roughly ATLS class III."]}'::jsonb, '[{"q":"Define shock.","keywords":["circulatory failure|circulation","perfusion","oxygen|hypoxia","organ"],"probe":"What happens at the cellular level?"},{"q":"Classify shock.","keywords":["hypovolaemic|hypovolemic","cardiogenic","septic|distributive","anaphylactic|neurogenic","obstructive"],"probe":"Give an example of obstructive shock."},{"q":"What type and class of shock is this patient in?","keywords":["hypovolaemic|hypovolemic|haemorrhagic|hemorrhagic","class iii|class 3|30|40","tachycardia|128","hypotension|86"],"probe":"Estimate the blood loss."},{"q":"How will you manage him?","keywords":["airway|abc","oxygen","large bore|iv access|cannula","fluid|crystalloid|blood","urine output|catheter|monitor"],"probe":"How will you monitor resuscitation?"}]'::jsonb, 'After a road traffic accident with a mandibular fracture and heavy bleeding from facial lacerations, a 25-year-old is pale and cold, with a pulse of 128/min, BP 86/60 mmHg and poor urine output.', array['emergency']::text[]),
(41, 13, 'wound-healing', 'Wound Healing', 'must_know', '10-mark essay', '{"definition":"Wound healing is the body''s ordered response to injury, restoring tissue continuity by regeneration and repair (scar formation).","classification":["Primary intention: clean, apposed edges (sutured incision)","Secondary intention: open wound fills with granulation tissue and contracts (e.g. extraction socket, infected wound)","Tertiary intention (delayed primary closure): wound left open, then closed after a few days"],"clinical_features":["Phases: haemostasis → inflammation (neutrophils, then macrophages) → proliferation (granulation tissue, angiogenesis, fibroblasts, epithelialisation) → remodelling (type III collagen replaced by type I)","Scar strength reaches about 80% of normal skin by around 3 months"],"etiology":["Local factors delaying healing: infection, foreign body, poor blood supply, movement, tension, haematoma","Systemic factors: diabetes, corticosteroids, malnutrition, vitamin C and zinc deficiency, old age, smoking, radiotherapy, anaemia"],"management":["Debride, clean and close without tension; control infection","Correct systemic factors (glucose, nutrition, smoking)","Complications: infection, dehiscence, hypertrophic scar (within the wound margins), keloid (extends beyond the margins)"],"viva_pearls":["Macrophages are the key cell orchestrating repair."]}'::jsonb, '[{"q":"What are the types of wound healing?","keywords":["primary intention","secondary intention","tertiary|delayed primary","granulation"],"probe":"Which type applies to an extraction socket?"},{"q":"Describe the phases of wound healing.","keywords":["haemostasis|hemostasis","inflammat","proliferat|granulation","remodel|maturation","collagen"],"probe":"Which collagen type replaces type III?"},{"q":"What factors delay healing?","keywords":["infection","diabet","steroid","smok","vitamin c|zinc|nutrition"],"probe":"Name both local and systemic factors."},{"q":"What are the complications of healing?","keywords":["dehiscence","keloid","hypertrophic","beyond|margins"],"probe":"How does a keloid differ from a hypertrophic scar?"}]'::jsonb, 'A clean, sutured facial laceration heals with a fine scar in 7 days, while an infected extraction socket in a diabetic smoker takes weeks to heal by granulation.', array['surgery basics']::text[]),
(42, 14, 'oral-health-indices', 'Oral Health Indices', 'must_know', '5-mark short note', '{"definition":"An index is a numerical value describing the relative status of a population on a graduated scale with defined upper and lower limits, designed to allow comparison between populations.","classification":["Caries: DMFT/DMFS (Klein, Palmer and Knutson, 1938) for permanent teeth; deft/dmft for primary teeth (Gruebbel, 1944)","Periodontal: Community Periodontal Index (WHO); Russell''s Periodontal Index; Ramfjord''s Periodontal Disease Index","Oral hygiene and plaque: OHI-S (Greene and Vermillion, 1964); Plaque Index (Silness and Löe, 1964)","Gingival: Gingival Index (Löe and Silness, 1963)","Fluorosis: Dean''s index; Thylstrup–Fejerskov (TF) index; TSIF"],"clinical_features":["Ideal properties: simple, objective, reliable (reproducible), valid, quick, acceptable to subjects, amenable to statistical analysis"],"management":["DMFT rules: each tooth is counted once; a tooth with both caries and a filling counts as D; teeth extracted for reasons other than caries are not counted as M","For a WHO-style survey of 12-year-olds: DMFT, CPI and Dean''s index"],"viva_pearls":["12 years is the WHO global monitoring age for caries."]}'::jsonb, '[{"q":"What is an index, and what are the properties of an ideal index?","keywords":["numerical|graduated scale","compar","simple","reliable|reproducible","valid"],"probe":"Name four properties."},{"q":"Tell me about the DMF index.","keywords":["klein|palmer|knutson","1938","decayed|missing|filled","permanent","counted once|once"],"probe":"Who introduced it, and how do you count a tooth that is filled and decayed?"},{"q":"Which periodontal and oral hygiene indices do you know?","keywords":["cpi|community periodontal","russell","ohi s|ohi-s|greene","plaque index|silness","gingival index|loe|löe"],"probe":"Who gave OHI-S?"},{"q":"Which indices will you use in this survey of 12-year-olds?","keywords":["dmft","cpi","dean","12 year|global monitoring"],"probe":"Why 12-year-olds?"}]'::jsonb, 'You are planning a school oral health survey of 12-year-olds in Coimbatore and must choose indices for caries, periodontal status, oral hygiene and fluorosis.', array['epidemiology']::text[]),
(43, 9, 'nsaids', 'NSAIDs in Dentistry', 'must_know', '10-mark essay', '{"definition":"Non-steroidal anti-inflammatory drugs are analgesic, antipyretic and anti-inflammatory agents that act mainly by inhibiting cyclo-oxygenase (COX) and so prostaglandin synthesis.","classification":["Non-selective COX inhibitors: aspirin (irreversible), ibuprofen, diclofenac, naproxen, ketorolac","Preferential COX-2 inhibitors: nimesulide, meloxicam, etodolac","Selective COX-2 inhibitors (coxibs): celecoxib, etoricoxib","Paracetamol: analgesic and antipyretic with weak peripheral anti-inflammatory action"],"clinical_features":["COX-1 (constitutive): gastric protection, platelet thromboxane, renal blood flow; COX-2 (inducible): inflammation and pain","Adverse effects: gastric irritation and ulcers, renal impairment, bleeding (aspirin irreversibly blocks platelet function), aspirin-exacerbated respiratory disease, cardiovascular risk with coxibs, Reye''s syndrome with aspirin in children","Interactions: warfarin (bleeding), antihypertensives and diuretics (reduced effect), methotrexate and lithium (toxicity)"],"management":["Dental pain: ibuprofen 400 mg (often combined with paracetamol) is the usual first choice","Peptic ulcer history: paracetamol, or a coxib/NSAID with a proton-pump inhibitor","Aspirin-sensitive asthma: avoid NSAIDs; use paracetamol","On warfarin: prefer paracetamol; avoid NSAIDs"],"viva_pearls":["Aspirin''s antiplatelet effect lasts the life of the platelet (about 7–10 days)."]}'::jsonb, '[{"q":"How do NSAIDs work?","keywords":["cyclo oxygenase|cyclooxygenase|cox","prostaglandin","cox 1|cox-1","cox 2|cox-2"],"probe":"What is the difference between COX-1 and COX-2?"},{"q":"Classify NSAIDs.","keywords":["non selective|nonselective|aspirin|ibuprofen","preferential|nimesulide|meloxicam","selective|celecoxib|etoricoxib|coxib","paracetamol|acetaminophen"],"probe":"Give an example of each group."},{"q":"What are their adverse effects?","keywords":["gastric|ulcer|gi","renal|kidney","bleeding|platelet","asthma|bronchospasm","reye|cardiovascular"],"probe":"Why avoid aspirin in children?"},{"q":"What will you prescribe for each of these three patients?","keywords":["paracetamol","proton pump|ppi|omeprazole|coxib","asthma|avoid","warfarin|bleeding"],"probe":"What is safest with warfarin?"}]'::jsonb, 'After a third molar surgery, you plan analgesia for three patients: one with peptic ulcer history, one with aspirin-exacerbated asthma, and one on warfarin.', array['analgesics']::text[]),
(44, 3, 'tmj-ankylosis', 'TMJ Ankylosis', 'must_know', '10-mark essay', '{"definition":"TMJ ankylosis is fibrous or bony fusion of the condyle to the glenoid fossa, causing progressive limitation of mouth opening.","classification":["Topazian: stage I – ankylotic bone limited to the condylar process; II – extends to the sigmoid notch; III – extends to the coronoid process","Sawhney: types I–IV (fibrous adhesions → bony mass)","False (extra-articular, e.g. coronoid hyperplasia, scarring) vs true (intra-articular)","Fibrous vs bony; unilateral vs bilateral"],"etiology":["Trauma (commonest – intracapsular condylar fracture, especially in childhood)","Infection: otitis media, mastoiditis, septic arthritis","Systemic: rheumatoid or ankylosing spondylitis, juvenile arthritis"],"clinical_features":["Severely reduced mouth opening, poor oral hygiene, rampant caries","Unilateral: deviation of chin to the affected side, fuller face on the affected side, flatter on the normal side","Bilateral: \"bird face\" deformity, micrognathia, Class II, obstructive sleep apnoea","No condylar movement on palpation"],"investigations":["OPG, CT/3D CT to define the ankylotic mass and its relation to the middle cranial fossa and maxillary artery"],"management":["Kaban''s protocol: early surgery, aggressive resection (gap arthroplasty ≥ 1–1.5 cm), ipsilateral coronoidectomy (contralateral if opening is still < 35 mm), interpositional material (temporalis fascia, fat), reconstruction of the ramus (costochondral graft in children), early mobilisation and vigorous physiotherapy for months","Interpositional arthroplasty reduces re-ankylosis","Airway: awake fibre-optic intubation","Correct secondary deformity later (distraction osteogenesis, genioplasty, orthognathic surgery)"],"viva_pearls":["In unilateral ankylosis the chin deviates towards the affected side."]}'::jsonb, '[{"q":"Define TMJ ankylosis and give its causes.","keywords":["fusion|fused","condyle|glenoid","trauma|fall","infection|otitis","arthritis"],"probe":"What is the commonest cause in children?"},{"q":"Classify TMJ ankylosis.","keywords":["topazian","sawhney","true|false","fibrous|bony","unilateral|bilateral"],"probe":"What are Topazian''s stages?"},{"q":"What are the clinical features in this child?","keywords":["mouth opening|trismus","bird face|micrognathia|receding chin","deviat","sleep apnoea|airway|snoring"],"probe":"Why is the midline deviated?"},{"q":"How will you treat it?","keywords":["kaban","gap arthroplasty|resection","coronoidectomy","interpositional|temporalis|fat","costochondral|physiotherapy"],"probe":"What is the role of coronoidectomy?"}]'::jsonb, 'A 9-year-old has a mouth opening of 6 mm, a receding chin ("bird face") and a history of a fall on the chin at age 3. The mandibular midline is deviated to the right.', array['TMJ','trismus']::text[]),
(45, 3, 'zygomatic-fractures', 'Zygomatic Complex Fractures', 'must_know', '10-mark essay', '{"definition":"A fracture of the zygomatic bone and its articulations (frontozygomatic, zygomaticomaxillary, zygomaticotemporal and zygomaticosphenoidal), often called a \"tripod\" or tetrapod fracture.","classification":["Knight and North (1961): group I – no displacement; II – arch fracture; III – unrotated body fracture; IV – medially rotated; V – laterally rotated; VI – complex","Henderson; Rowe and Killey"],"clinical_features":["Flattening of the malar prominence, periorbital oedema and ecchymosis","Subconjunctival haemorrhage without a posterior limit","Step deformity at the infraorbital rim or frontozygomatic suture","Paraesthesia in the infraorbital nerve distribution","Trismus from impingement on the coronoid process","Diplopia, enophthalmos, unilateral epistaxis"],"investigations":["Occipitomental (15° and 30°) and submentovertex views","CT (axial and coronal) is the investigation of choice"],"management":["Undisplaced: conservative, soft diet, avoid pressure","Isolated arch: Gillies temporal approach elevation; also Keen''s intraoral approach","Displaced body: open reduction and internal fixation with miniplates (1-, 2- or 3-point fixation at FZ suture, infraorbital rim, zygomatic buttress)","Orbital floor exploration if there is entrapment or enophthalmos; check vision (retrobulbar haemorrhage is an emergency)"],"viva_pearls":["Knight and North group V (laterally rotated) and II are usually stable after elevation alone."]}'::jsonb, '[{"q":"What is a zygomatic complex fracture?","keywords":["tripod|tetrapod","frontozygomatic","zygomaticomaxillary|maxillary","arch|temporal"],"probe":"Name the articulations involved."},{"q":"Classify these fractures.","keywords":["knight","north","rotated","arch","complex"],"probe":"Which groups are rotated?"},{"q":"What are the clinical features?","keywords":["flatten","subconjunctival","step","paraesthesia|numb|infraorbital","trismus|diplopia"],"probe":"Why does he have trouble opening his mouth?"},{"q":"How will you investigate and treat him?","keywords":["ct|occipitomental|submentovertex","gillies|keen","orif|miniplate|fixation","orbital floor|vision|retrobulbar"],"probe":"Describe the Gillies approach."}]'::jsonb, 'After an assault, a 28-year-old has a flattened left cheek, a step at the infraorbital rim, numbness of the left cheek and upper lip, subconjunctival haemorrhage and difficulty opening his mouth.', array['maxillofacial trauma']::text[]),
(46, 3, 'oro-antral-communication', 'Oro-antral Communication & Fistula', 'must_know', '5-mark short note', '{"definition":"An oro-antral communication (OAC) is an opening between the oral cavity and the maxillary sinus; if it persists and becomes epithelialised it is an oro-antral fistula (OAF).","etiology":["Extraction of maxillary first and second molars or premolars with roots close to the sinus","Removal of cysts or tumours, trauma, implant surgery, osteomyelitis"],"clinical_features":["Positive nose-blowing (Valsalva) test – air bubbles, not done if it may enlarge a small opening","Fluid regurgitation from nose on drinking, change in voice resonance, whistling","Epistaxis on the side, later sinusitis with foul discharge","Later: antral polyp prolapse through the fistula"],"investigations":["Periapical/OPG and occipitomental view or CBCT to look for a root in the sinus and sinusitis"],"management":["Small (< 2 mm): forms a clot – suture, sinus precautions","Larger, fresh openings: immediate closure – buccal advancement flap (Rehrmann), buccal fat pad flap","Palatal rotation flap for fistulas, especially larger or posterior ones","Sinus precautions: no nose blowing, sneeze with mouth open, no straws or smoking; decongestants (nasal drops) and antibiotics (e.g. amoxicillin)","Treat any sinusitis before closing a chronic fistula; remove displaced roots (Caldwell–Luc if needed)"],"viva_pearls":["Sinus floor most closely related to the roots of the maxillary first molar (and second premolar/second molar)."]}'::jsonb, '[{"q":"What is an oro-antral communication, and how does it differ from a fistula?","keywords":["maxillary sinus|antrum","opening|communication","epithelial","persist|chronic"],"probe":"When does a communication become a fistula?"},{"q":"How will you diagnose it?","keywords":["nose blowing|valsalva","bubbles|air","fluid|regurgitat","radiograph|opg|cbct|occipitomental"],"probe":"What is the nose-blowing test?"},{"q":"How will you close it?","keywords":["buccal advancement|rehrmann","buccal fat pad","palatal|rotation","small|clot|suture"],"probe":"What flap would you choose for a chronic fistula?"},{"q":"What instructions and medication will you give?","keywords":["no nose blowing|blow","sneeze|mouth open","decongest|nasal drops","antibiotic|amoxicillin"],"probe":"Why prescribe a decongestant?"}]'::jsonb, 'While extracting 26 in a 40-year-old, you notice a bony fragment with a smooth concavity on the root trifurcation. Air bubbles appear in the socket when the patient blows against a pinched nose.', array['maxillary sinus','exodontia']::text[]),
(47, 8, 'glass-ionomer-cement', 'Glass Ionomer Cement', 'must_know', '10-mark essay', '{"definition":"Glass ionomer cement (GIC, Wilson and Kent, 1972) is a water-based cement formed by an acid–base reaction between a fluoroaluminosilicate glass powder and a polyalkenoic (polyacrylic) acid liquid.","classification":["Type I – luting; II – restorative (II.1 aesthetic, II.2 reinforced); III – liners and bases; IV – fissure sealant; V – orthodontic cement; VI – core build-up; VII – fluoride-releasing; VIII – ART; IX – paediatric","Modified: resin-modified GIC, metal-reinforced (cermet, silver alloy admix), high-viscosity GIC"],"clinical_features":["Composition: powder – silica, alumina, calcium fluoride, sodium and aluminium fluoride; liquid – polyacrylic acid, itaconic and maleic acids, tartaric acid (controls setting) and water","Setting: acid attacks glass → Ca²⁺ and Al³⁺ released → calcium polyacrylate (early) then aluminium polyacrylate (later) cross-links → silica gel matrix","Properties: chemical adhesion to enamel and dentine (chelation with calcium), fluoride release and recharge, coefficient of thermal expansion close to tooth, biocompatible","Drawbacks: sensitive to moisture contamination and dehydration early, low fracture toughness and wear resistance, less aesthetic than composite"],"management":["Condition tooth with 10% polyacrylic acid for 10–20 s","Protect the surface with varnish or resin coat after placement","Uses: cervical and root caries, Class V, primary teeth, ART, luting, liners, sandwich technique"],"viva_pearls":["Tartaric acid sharpens the set and extends working time."]}'::jsonb, '[{"q":"What is glass ionomer cement and who introduced it?","keywords":["wilson|kent","fluoroaluminosilicate|glass","polyacrylic|polyalkenoic","acid base|acid-base"],"probe":"What kind of reaction sets it?"},{"q":"Give the composition and setting reaction.","keywords":["silica|alumina","calcium fluoride|fluoride","tartaric","calcium polyacrylate","aluminium polyacrylate|aluminum polyacrylate"],"probe":"What does tartaric acid do?"},{"q":"What are its advantages and disadvantages?","keywords":["adhesion|chemical bond|chelat","fluoride release|recharge","thermal expansion","moisture|dehydrat","wear|fracture|brittle"],"probe":"How does it bond to the tooth?"},{"q":"How would you use it for this patient?","keywords":["root caries|cervical|class v","polyacrylic acid|condition","varnish|protect|coat","fluoride"],"probe":"What surface treatment do you use before placing it?"}]'::jsonb, 'A 70-year-old with high caries risk has cervical root caries on several teeth and finds it hard to keep his mouth open for long.', array['cements','restorative']::text[]),
(48, 7, 'pit-fissure-sealants', 'Pit and Fissure Sealants', 'must_know', '5-mark short note', '{"definition":"A material placed into the pits and fissures of caries-susceptible teeth that bonds micromechanically to enamel and forms a protective barrier against bacteria and food.","classification":["Resin-based: by generation of curing – first (UV light), second (self-cure), third (visible light), fourth (fluoride-releasing)","Filled vs unfilled; clear vs opaque","Glass ionomer sealants (useful in partially erupted teeth or where isolation is poor)"],"clinical_features":["Indications: deep, retentive fissures; newly erupted teeth; high caries risk; non-cavitated or incipient fissure lesions","Contraindications: well-coalesced self-cleansing fissures, cavitated dentinal caries, teeth unlikely to be isolated (for resin)"],"management":["Clean the fissures (pumice slurry or prophy brush), rinse","Isolate (rubber dam or cotton rolls)","Etch with 37% phosphoric acid for 15–30 s, rinse, dry to a chalky white appearance","Apply sealant, cure, check for voids, occlusion and retention","Review retention at recall; reapply if lost"],"viva_pearls":["Fissure shapes (Nagano): V, U, I and IK types – I and IK are most caries-prone."]}'::jsonb, '[{"q":"What is a pit and fissure sealant?","keywords":["pit|fissure","barrier|seal","bond|micromechanical","caries"],"probe":"How does a resin sealant bond?"},{"q":"Classify sealants.","keywords":["generation","ultraviolet|uv","self cure|self-cure|autopolymer","visible light","glass ionomer|gic"],"probe":"What were the first-generation sealants cured with?"},{"q":"What are the indications?","keywords":["deep|retentive","newly erupted","high caries risk|high risk","non cavitated|non-cavitated|incipient"],"probe":"Would you seal a cavitated lesion?"},{"q":"Describe the technique.","keywords":["clean|pumice","isolat|rubber dam","etch|phosphoric","chalky|frosty","cure|light"],"probe":"How long do you etch?"}]'::jsonb, 'A 7-year-old with high caries risk has recently erupted lower first permanent molars with deep, stained but non-cavitated fissures.', array['prevention']::text[]),
(49, 7, 'oral-habits', 'Oral Habits in Children', 'must_know', '10-mark essay', '{"definition":"A habit is a fixed practice produced by constant repetition. Oral habits such as thumb sucking, tongue thrusting, mouth breathing, lip biting and bruxism can affect the dentition when they persist beyond the age they are normally given up.","classification":["Useful vs harmful","Empty (no underlying cause) vs meaningful (psychological)","Klein: intentional vs unintentional"],"clinical_features":["Thumb sucking (beyond about 4–5 years): proclined upper incisors, retroclined lowers, increased overjet, anterior open bite, narrow maxilla and posterior crossbite (buccinator pressure), clean \"dishpan\" thumb with callus","Tongue thrust: anterior open bite, spacing; tongue visible between teeth on swallowing","Mouth breathing: adenoid facies, long face, incompetent lips, gingivitis in the anterior segment, high palatal vault","Bruxism: attrition, TMJ pain, muscle hypertrophy"],"management":["Psychological approach first: explain to the child, positive reinforcement, reward chart (most effective when the child wants to stop)","Reminder therapy: bitter nail paint, adhesive bandage, glove at night","Mechanical: removable or fixed habit-breaking appliance (palatal crib, rake, quad helix with crib) for about 6 months after stopping","Mouth breathing: ENT referral for adenoids or obstruction; oral screen","Correct residual malocclusion (expansion for crossbite)"],"viva_pearls":["A quad helix with a crib both expands the maxilla and reminds the child not to suck."]}'::jsonb, '[{"q":"What is a habit, and how are oral habits classified?","keywords":["repetition|repeat","useful|harmful","empty|meaningful","intentional|unintentional"],"probe":"What is an \"empty\" habit?"},{"q":"What effects does thumb sucking have?","keywords":["procline|flared","open bite","overjet","crossbite|narrow","callus|dishpan"],"probe":"Why does the maxilla narrow?"},{"q":"How does a mouth breather present?","keywords":["adenoid","long face","incompetent lip","gingivitis","high palat|narrow"],"probe":"Which specialist would you involve?"},{"q":"How will you manage this child?","keywords":["psycholog|counsel|reward","reminder|bitter","crib|rake|habit breaking|appliance","quad helix|expansion"],"probe":"What would you try before an appliance?"}]'::jsonb, 'An 8-year-old still sucks her thumb at night. She has proclined upper incisors, an anterior open bite and a narrow maxillary arch with posterior crossbite.', array['thumb sucking','interceptive']::text[]),
(50, 6, 'rpd-components', 'Removable Partial Denture: Components', 'must_know', '10-mark essay', '{"definition":"A cast partial denture replaces missing teeth and tissues in a partially edentulous arch. Its components work together to give support, retention, stability and reciprocation.","classification":["Major connector: maxillary – palatal bar, palatal strap, anteroposterior bar, horseshoe, complete palate; mandibular – lingual bar (needs ≥ 8 mm from gingival margin to floor of mouth), lingual plate, sublingual bar, Kennedy bar, labial bar","Minor connector: joins clasps, rests and bases to the major connector","Rests: occlusal, cingulum, incisal – provide vertical support","Direct retainers: suprabulge (circumferential, Akers, ring, embrasure) and infrabulge (Roach: I-bar, T-bar, Y-bar) clasps; attachments","Indirect retainers: rests placed anterior to the fulcrum line to resist dislodgement of distal extension bases","Denture base and artificial teeth"],"clinical_features":["Clasp assembly: retentive arm in the undercut, reciprocal arm, rest and minor connector; must encircle more than 180° of the tooth","Survey with a surveyor to find the path of insertion, height of contour and undercuts"],"management":["For distal extension (Class I): RPI system (mesial Rest, distal Proximal plate, I-bar) to reduce torque on abutments","Lingual bar if floor-of-mouth depth allows; lingual plate if not","Functional/altered cast impression for distal extension bases"],"viva_pearls":["RPI system was described by Kratochvil (and Krol)."]}'::jsonb, '[{"q":"Name the components of an RPD.","keywords":["major connector","minor connector","rest","direct retainer|clasp","indirect retainer"],"probe":"What does a rest do?"},{"q":"Describe mandibular major connectors.","keywords":["lingual bar","lingual plate","8 mm|8mm|floor of mouth","kennedy bar|sublingual|labial"],"probe":"How much space does a lingual bar need?"},{"q":"Classify clasps.","keywords":["suprabulge|circumferential|akers","infrabulge|roach|i bar|i-bar","180","reciprocal"],"probe":"How much of the tooth must a clasp encircle?"},{"q":"What design would you use for this Kennedy Class I case?","keywords":["rpi","indirect retainer","fulcrum","altered cast|functional impression"],"probe":"What does RPI stand for?"}]'::jsonb, 'A 50-year-old is missing 35, 36, 37, 45, 46 and 47 (Kennedy Class I) and wants a cast partial denture.', array['RPD']::text[]),
(51, 5, 'peri-implantitis', 'Dental Implants & Peri-implantitis', 'must_know', '10-mark essay', '{"definition":"Osseointegration (Brånemark) is a direct structural and functional connection between living bone and the surface of a load-bearing implant. Peri-implantitis is a plaque-associated inflammatory condition around implants with progressive loss of supporting bone; peri-implant mucositis is reversible inflammation without bone loss.","classification":["2017 World Workshop: peri-implant health, peri-implant mucositis, peri-implantitis, hard and soft tissue deficiencies"],"etiology":["Risk factors: history of periodontitis, poor plaque control, no maintenance, smoking, diabetes, excess cement, poor prosthesis design"],"clinical_features":["Bleeding and/or suppuration on gentle probing","Increased probing depth compared with earlier visits","Bone loss beyond initial remodelling, often saucer- or crater-shaped","Implant may stay immobile until late"],"management":["Mucositis: mechanical debridement, oral hygiene, chlorhexidine","Cumulative Interceptive Supportive Therapy (CIST, Lang): A – mechanical debridement; B – antiseptic (chlorhexidine); C – systemic or local antibiotics; D – surgical (resective or regenerative)","Surgical: access flap, implant surface decontamination, resective surgery or regenerative bone grafting for contained defects","Mobile implant: remove","Stop smoking, control diabetes, strict maintenance"],"viva_pearls":["Success criteria (Albrektsson): no mobility, no radiolucency, bone loss < 0.2 mm per year after the first year, no persistent pain or infection."]}'::jsonb, '[{"q":"What is osseointegration?","keywords":["branemark|brånemark","direct","bone","functional|structural"],"probe":"Who described it?"},{"q":"How does peri-implant mucositis differ from peri-implantitis?","keywords":["mucositis","reversible","bone loss","bleeding|suppuration"],"probe":"Which one has bone loss?"},{"q":"What are the risk factors?","keywords":["periodontitis","plaque|hygiene","smok","diabet","cement"],"probe":"Why is residual cement a problem?"},{"q":"How will you treat this patient?","keywords":["cist|lang","debridement","chlorhexidine|antiseptic","antibiotic","surgical|regenerat|resective"],"probe":"What does CIST involve?"}]'::jsonb, 'Five years after an implant in the 36 region, a 55-year-old smoker has bleeding and suppuration on probing around the implant, a probing depth of 7 mm and crater-like bone loss on the radiograph.', array['implants']::text[]),
(52, 5, 'necrotising-periodontal', 'Necrotising Periodontal Diseases (NUG)', 'must_know', '5-mark short note', '{"definition":"Necrotising periodontal diseases are acute infections with necrosis of the interdental papillae, bleeding and pain, in patients with impaired host defence. They include necrotising gingivitis (NG), necrotising periodontitis (NP) and necrotising stomatitis (NS).","etiology":["Fusospirochaetal complex: Fusobacterium, Treponema, Prevotella intermedia, Selenomonas","Predisposing: stress, smoking, poor oral hygiene, poor sleep and nutrition, HIV/immunosuppression, malnutrition in children"],"clinical_features":["Punched-out, crater-like papillae covered by a grey pseudomembrane","Severe pain, spontaneous bleeding, metallic taste, foul breath (fetor oris)","Lymphadenopathy and fever in more severe cases","Histology (Listgarten zones): bacterial, neutrophil-rich, necrotic, spirochaetal infiltration"],"management":["Day 1: gentle superficial debridement under topical anaesthesia; chlorhexidine 0.12–0.2% or hydrogen peroxide rinses","Metronidazole 400 mg three times daily for 3 days if systemic involvement","Advice: stop smoking, rest, diet, fluids, analgesics","Subsequent visits: full scaling and root planing, correct predisposing factors; consider HIV testing in recurrent or severe cases","Correct residual gingival deformities later"],"viva_pearls":["Old name: acute necrotising ulcerative gingivitis (ANUG), \"trench mouth\" or Vincent''s infection."]}'::jsonb, '[{"q":"What are necrotising periodontal diseases?","keywords":["necro","papilla","gingivitis","periodontitis","stomatitis"],"probe":"Name the three conditions."},{"q":"What causes them?","keywords":["fusobacter|fuso","spirochaet|treponema","stress","smok","hiv|immun"],"probe":"Which bacteria are involved?"},{"q":"Describe the clinical features.","keywords":["punched out|punched-out|crater","pseudomembrane|slough|grey","pain","bleed","foul|fetor|halitosis"],"probe":"What do the papillae look like?"},{"q":"How will you manage this student?","keywords":["debride","chlorhexidine|hydrogen peroxide","metronidazole","smok|stress|rest","scaling|root planing"],"probe":"Which antibiotic, and when?"}]'::jsonb, 'A 21-year-old student in exam season, smoking heavily and sleeping little, has painful bleeding gums, "punched-out" interdental papillae covered with grey slough and a strong foul odour.', array['acute gingival conditions']::text[]),
(53, 2, 'recurrent-aphthous-stomatitis', 'Recurrent Aphthous Stomatitis', 'must_know', '5-mark short note', '{"definition":"Recurrent aphthous stomatitis (RAS) is a common condition of recurrent, painful, round or oval ulcers with a yellow-grey floor and an erythematous halo, on non-keratinised mucosa.","classification":["Minor (Mikulicz): < 1 cm, heal in 7–14 days without scarring – about 80%","Major (Sutton''s, periadenitis mucosa necrotica recurrens): > 1 cm, deep, weeks to months, heal with scarring, may involve the soft palate and fauces","Herpetiform: crops of 10–100 tiny ulcers that may coalesce, heal in 1–2 weeks"],"etiology":["Not fully understood: T-cell-mediated immune response","Triggers: trauma, stress, family history, hormonal changes, food, sodium lauryl sulphate toothpaste, stopping smoking","Associations: iron, folate and B12 deficiency; coeliac and Crohn''s disease; Behçet''s disease; HIV; PFAPA syndrome"],"investigations":["Diagnosis is clinical","Blood count, ferritin, folate, B12 in persistent or severe cases; coeliac screen if suspected"],"management":["Correct any deficiency; avoid triggers","Topical: chlorhexidine mouthwash, benzydamine, topical corticosteroids (triamcinolone in orabase, betamethasone mouthwash), doxycycline mouthwash","Major RAS: intralesional or systemic steroids; refer"],"viva_pearls":["Aphthae affect non-keratinised mucosa; recurrent herpes ulcers favour keratinised mucosa (hard palate, attached gingiva)."]}'::jsonb, '[{"q":"What is recurrent aphthous stomatitis?","keywords":["recurrent","painful","round|oval","halo|erythematous","non keratin|non-keratin"],"probe":"Which mucosa is affected?"},{"q":"Classify aphthous ulcers.","keywords":["minor|mikulicz","major|sutton","herpetiform","scar","1 cm|10 mm"],"probe":"Which type heals with scarring?"},{"q":"What are the predisposing factors and associations?","keywords":["stress|trauma","iron|folate|b12|haematinic","coeliac|crohn","behcet|behçet","hiv|lauryl"],"probe":"Which blood tests would you order?"},{"q":"How will you treat it?","keywords":["steroid|triamcinolone|betamethasone","chlorhexidine","benzydamine|doxycycline","deficien|trigger"],"probe":"What topical steroid would you use?"}]'::jsonb, 'A 19-year-old has had crops of 2–3 small painful round ulcers on the labial mucosa every few weeks since childhood. Each ulcer has a yellow floor and red halo and heals in about 10 days.', array['ulcers']::text[]),
(54, 12, 'infective-endocarditis', 'Infective Endocarditis & Antibiotic Prophylaxis', 'must_know', '10-mark essay', '{"definition":"Infective endocarditis is microbial infection of the endocardial surface of the heart, usually the valves, forming vegetations.","classification":["Acute (Staphylococcus aureus; rapid, destructive) vs subacute (viridans streptococci; insidious)","Native valve, prosthetic valve, intravenous drug user (right-sided, S. aureus)"],"clinical_features":["Fever, malaise, new or changing murmur","Peripheral signs: splinter haemorrhages, Osler''s nodes (painful, finger pulps), Janeway lesions (painless, palms and soles), Roth spots, clubbing, splenomegaly","Embolic events, heart failure"],"investigations":["Three sets of blood cultures before antibiotics","Echocardiography (transoesophageal is more sensitive)","Modified Duke criteria for diagnosis"],"management":["Prolonged high-dose IV antibiotics; surgery for valve destruction or heart failure","Highest-risk groups for dental prophylaxis (AHA 2007/2021): prosthetic valves or valve repair material, previous endocarditis, certain congenital heart disease, cardiac transplant with valvulopathy","Procedures needing prophylaxis in those groups: manipulation of gingival tissue or the periapical region, or perforation of the oral mucosa","Regimen: amoxicillin 2 g orally 30–60 minutes before the procedure (children 50 mg/kg); if allergic, azithromycin or clarithromycin 500 mg, or doxycycline 100 mg (clindamycin no longer recommended by AHA)","This patient: suspected active endocarditis – defer the extraction, refer urgently to a physician","Maintain good oral hygiene – daily bacteraemia from chewing and brushing matters more than procedures"],"viva_pearls":["NICE (UK) does not routinely recommend prophylaxis; know both views."]}'::jsonb, '[{"q":"What is infective endocarditis, and which organisms cause it?","keywords":["endocardi|valve","vegetation","viridans|streptococ","staphylococ|aureus"],"probe":"Which organism links it to the mouth?"},{"q":"What clinical signs would you look for?","keywords":["fever","murmur","splinter","osler|janeway","roth|clubbing|splenomegaly"],"probe":"Which lesion is painful – Osler''s or Janeway?"},{"q":"Who needs antibiotic prophylaxis before dental treatment?","keywords":["prosthetic valve","previous endocarditis","congenital","transplant","gingival|periapical|perforat"],"probe":"Which dental procedures qualify?"},{"q":"What is the regimen, and what will you do for this patient?","keywords":["amoxicillin","2 g|2g","30|60 minutes|one hour","azithromycin|clarithromycin|doxycycline","defer|refer|physician"],"probe":"What if he is allergic to penicillin?"}]'::jsonb, 'A 35-year-old with a prosthetic mitral valve needs extraction of 46. He also describes a fever for two weeks and you notice splinter haemorrhages in his nails.', array['medically compromised','cardiac']::text[]),
(55, 3, 'sterilisation', 'Sterilisation & Disinfection', 'must_know', '10-mark essay', '{"definition":"Sterilisation is the destruction or removal of all microorganisms, including bacterial spores. Disinfection kills or removes most pathogenic organisms but not necessarily spores. Antisepsis is disinfection of living tissue.","classification":["Spaulding: critical (penetrate tissue – sterilise: forceps, scalers, burs), semi-critical (contact mucosa – sterilise or high-level disinfect: mirrors, impression trays, handpieces should still be heat-sterilised), non-critical (contact intact skin – low-level disinfect: light handles, BP cuff)","Physical: moist heat – autoclave 121 °C for 15–20 min at 15 psi, or 134 °C for 3–4 min at 30 psi; dry heat – hot air oven 160 °C for 2 h; glass bead (240 °C, small endo instruments – not recommended now); radiation (gamma for disposables)","Chemical: ethylene oxide; glutaraldehyde 2% (10 h for sterilisation); hypochlorite; alcohols; iodophors; chlorhexidine"],"investigations":["Monitoring: physical (time, temperature, pressure), chemical indicators (autoclave tape, Bowie–Dick test for vacuum autoclaves), biological indicators – Geobacillus stearothermophilus (autoclave), Bacillus atrophaeus (dry heat, ethylene oxide)"],"management":["Cycle: pre-soak → cleaning (ultrasonic) → inspection → packaging → sterilisation → storage","Gutta-percha cones: disinfect chairside in 5.25% sodium hypochlorite for 1 minute","Impressions: rinse, then disinfect (e.g. hypochlorite or iodophor spray/immersion according to material)","Standard precautions for every patient: PPE, hand hygiene, sharps and waste management"],"viva_pearls":["Prions resist standard sterilisation; follow extended autoclave protocols or discard."]}'::jsonb, '[{"q":"Define sterilisation, disinfection and antisepsis.","keywords":["spore","all microorganisms|all micro-organisms","disinfect","living tissue|antisep"],"probe":"What does disinfection fail to kill?"},{"q":"Explain the Spaulding classification.","keywords":["spaulding","critical","semi critical|semi-critical","non critical|non-critical"],"probe":"Into which category do forceps fall?"},{"q":"What are the parameters for autoclaving and hot air oven?","keywords":["121","134","15 psi|psi|pressure","160","2 hours|2 h|two hours"],"probe":"What temperature and time for a hot air oven?"},{"q":"How do you monitor sterilisation?","keywords":["biological indicator|spore test","stearothermophilus","chemical indicator|tape|bowie","atrophaeus|subtilis"],"probe":"Which organism tests the autoclave?"}]'::jsonb, 'You are setting up instrument reprocessing in a new dental clinic and need to decide how to handle handpieces, forceps, impression trays and gutta-percha cones.', array['infection control']::text[]),
(56, 15, 'tooth-development', 'Tooth Development (Odontogenesis)', 'must_know', '10-mark essay', '{"definition":"Odontogenesis is the formation of teeth from oral ectoderm (enamel) and cranial neural crest–derived ectomesenchyme (dentine, pulp, cementum, PDL), through a series of reciprocal epithelial–mesenchymal interactions.","classification":["Initiation: dental lamina forms from oral epithelium at about the 6th week of intrauterine life","Bud stage: epithelial proliferation into ectomesenchyme","Cap stage: enamel organ, dental papilla and dental follicle form the tooth germ; enamel knot (signalling centre)","Bell stage: histodifferentiation and morphodifferentiation – inner and outer enamel epithelium, stellate reticulum, stratum intermedium; crown shape set","Apposition: dentine first, then enamel (reciprocal induction)","Root formation: Hertwig''s epithelial root sheath (HERS) maps the root; its remnants are the epithelial rests of Malassez"],"clinical_features":["Initiation defects: anodontia, hypodontia, supernumerary teeth","Morphodifferentiation defects: peg laterals, macrodontia, dens invaginatus, Carabelli cusp","Histodifferentiation and apposition defects: amelogenesis and dentinogenesis imperfecta, enamel hypoplasia","HERS defects: dilaceration, accessory canals, enamel pearls"],"viva_pearls":["Dentine always forms before enamel; inner enamel epithelium cells become ameloblasts only after odontoblasts lay down dentine.","Reduced enamel epithelium later fuses with oral epithelium to allow eruption and forms the junctional epithelium."]}'::jsonb, '[{"q":"From which tissues do the parts of a tooth develop?","keywords":["ectoderm","neural crest|ectomesenchyme","enamel organ","dental papilla","dental follicle|dental sac"],"probe":"What does the dental papilla form?"},{"q":"Describe the stages of tooth development.","keywords":["bud","cap","bell","apposition","dental lamina|initiation"],"probe":"What happens in the bell stage?"},{"q":"What is Hertwig''s epithelial root sheath?","keywords":["hertwig|hers","root","inner and outer enamel epithelium|enamel epithelium","malassez|rests"],"probe":"What do its remnants become?"},{"q":"Which anomalies arise at each stage?","keywords":["anodontia|hypodontia","supernumerary","peg","amelogenesis|dentinogenesis","hypoplasia|dilaceration"],"probe":"At which stage do peg laterals arise?"}]'::jsonb, 'A child has a missing upper lateral incisor, and his father has a peg-shaped one. In your viva you are asked how and when a tooth forms, and where things can go wrong.', array['oral histology','embryology']::text[]),
(57, 15, 'enamel', 'Enamel: Structure & Histology', 'must_know', '10-mark essay', '{"definition":"Enamel is the hardest calcified tissue in the body, formed by ameloblasts (ectodermal). It is about 96% inorganic hydroxyapatite by weight and is acellular, avascular and cannot regenerate.","clinical_features":["Unit: the enamel rod (prism), \"keyhole\" shaped in cross-section, about 4–5 μm wide; interrod enamel between rods","Tomes'' process of the ameloblast decides rod orientation","Cross-striations: daily (circadian) increments about 4 μm apart","Striae of Retzius: weekly incremental lines; they end on the surface as perikymata; the neonatal line is an accentuated stria","Hunter–Schreger bands: alternating light and dark bands from changing rod direction (optical effect)","Gnarled enamel: twisted rods over cusp tips","Enamel tufts (hypomineralised, from DEJ, look like grass), lamellae (thin leaf-like defects that run the full thickness), spindles (odontoblast processes trapped across the DEJ)","Aprismatic (prismless) enamel on the surface of primary teeth and some permanent teeth"],"classification":["Amelogenesis: pre-secretory, secretory (Tomes'' process; amelogenin, enamelin, ameloblastin), maturation (protein and water removed, mineral increases), protective stages"],"viva_pearls":["Enamel spindles are the only enamel structure of dentinal (odontoblastic) origin."]}'::jsonb, '[{"q":"What is the composition of enamel?","keywords":["96","hydroxyapatite","ameloblast","acellular|avascular|no regenerat"],"probe":"What percentage is inorganic?"},{"q":"Describe the enamel rod.","keywords":["rod|prism","keyhole","interrod","tomes","4|5 μm|micron"],"probe":"What shape is it in cross-section?"},{"q":"What are the incremental lines in enamel?","keywords":["cross striation|cross-striation","retzius","perikymata","neonatal line","hunter|schreger"],"probe":"Where do the striae of Retzius end?"},{"q":"Distinguish tufts, lamellae and spindles.","keywords":["tuft","lamella","spindle","odontoblast","hypomineral"],"probe":"Which structure comes from odontoblasts?"}]'::jsonb, 'A ground section of a premolar shows brown lines running obliquely from the dentinoenamel junction, alternating light and dark bands near the DEJ, and short dark lines from the DEJ into enamel.', array['oral histology']::text[]),
(58, 15, 'dentine', 'Dentine & the Dentine–Pulp Complex', 'must_know', '10-mark essay', '{"definition":"Dentine is a mineralised connective tissue (about 70% inorganic, 20% organic – mainly type I collagen – and 10% water) formed by odontoblasts from the dental papilla. With the pulp it forms one functional unit, the dentine–pulp complex.","classification":["By development: primary (mantle dentine – first formed, coarse collagen/von Korff fibres; circumpulpal dentine), secondary (after root completion, slow, physiological), tertiary (in response to stimuli – reactionary from surviving odontoblasts, reparative from new odontoblast-like cells)","By structure: peritubular (intratubular, highly mineralised) and intertubular dentine","Sclerotic dentine: tubules occluded with mineral (ageing, slow caries) – translucent","Dead tracts: empty tubules after odontoblast death – appear dark in ground sections"],"clinical_features":["Dentinal tubules: S-shaped (primary curvature) in the crown, about 2.5 μm wide near the pulp, more numerous near the pulp","Incremental lines: von Ebner lines (daily), contour lines of Owen (accentuated), neonatal line","Interglobular dentine (hypomineralised areas, crown) and Tomes'' granular layer (root, beneath cementum)","Predentine: unmineralised layer next to odontoblasts"],"management":["Sensitivity: Brännström''s hydrodynamic theory – fluid movement in open tubules stimulates A-delta nerve fibres","Treatment: occlude tubules (fluoride varnish, arginine, bioactive glass, GIC) or desensitise nerves (potassium nitrate)"],"viva_pearls":["Tomes'' granular layer is in root dentine; interglobular dentine is mostly in the crown."]}'::jsonb, '[{"q":"What is the composition of dentine?","keywords":["70","collagen|type i","odontoblast","dental papilla"],"probe":"Which collagen type predominates?"},{"q":"Classify dentine.","keywords":["primary|mantle","secondary","tertiary","reactionary|reparative","peritubular|intertubular|sclerotic"],"probe":"How do reactionary and reparative dentine differ?"},{"q":"Name the incremental and structural features of dentine.","keywords":["von ebner","owen","interglobular","tomes granular|granular layer","predentin"],"probe":"Where is Tomes'' granular layer?"},{"q":"Why is exposed dentine sensitive?","keywords":["hydrodynamic|brannstrom|brännström","fluid","tubule","a delta|a-delta|nerve","occlude|potassium nitrate|fluoride"],"probe":"Explain the hydrodynamic theory."}]'::jsonb, 'A patient with gum recession has sharp pain with cold air on exposed root surfaces. You are asked to explain the structure of dentine and why it is sensitive.', array['oral histology','sensitivity']::text[]),
(59, 15, 'periodontal-ligament', 'Periodontal Ligament', 'must_know', '10-mark essay', '{"definition":"The periodontal ligament is the dense fibrous connective tissue that surrounds the root and attaches it to the alveolar bone. It is about 0.15–0.38 mm wide, narrowest at the middle third of the root.","classification":["Principal fibres (Sharpey''s fibres where embedded): alveolar crest, horizontal, oblique (most numerous; resist vertical forces), apical, interradicular groups","Gingival fibres (not strictly PDL): transseptal (dentogingival group, cause relapse after orthodontics), dentogingival, alveologingival, circular","Oxytalan and elastic fibres; mainly type I and III collagen"],"clinical_features":["Cells: fibroblasts (most numerous), cementoblasts, osteoblasts, osteoclasts, epithelial rests of Malassez, undifferentiated mesenchymal cells, defence cells","Ground substance: glycosaminoglycans and glycoproteins","Rich blood supply and mechanoreceptors (proprioception)"],"management":["Functions: supportive (attachment, shock absorption), formative and remodelling (bone and cementum), sensory (proprioception, pain), nutritive","Clinical relevance: widening in trauma from occlusion; transseptal fibres explain rotation relapse (circumferential supracrestal fibrotomy)"],"viva_pearls":["Oblique fibres are the largest group; they turn vertical bite forces into tension on the bone."]}'::jsonb, '[{"q":"What is the periodontal ligament, and how wide is it?","keywords":["connective tissue","root","alveolar bone","0.15|0.2|0.38|mm","middle third|narrowest"],"probe":"Where is it narrowest?"},{"q":"Name the principal fibre groups.","keywords":["alveolar crest","horizontal","oblique","apical","interradicular"],"probe":"Which group is most numerous?"},{"q":"What cells does it contain?","keywords":["fibroblast","cementoblast","osteoblast|osteoclast","malassez","mesenchymal"],"probe":"Which cell is most numerous?"},{"q":"What are its functions and clinical significance?","keywords":["support|attachment","formative|remodel","sensory|proprioception","nutritive","transseptal|fibrotomy|relapse"],"probe":"Why do rotated teeth relapse?"}]'::jsonb, 'On a radiograph of a tooth in heavy occlusal trauma the PDL space is widened. You are asked to describe the normal PDL and its functions.', array['oral histology','periodontium']::text[]),
(60, 15, 'oral-mucosa', 'Oral Mucous Membrane', 'desirable', '5-mark short note', '{"definition":"The oral mucosa is the moist lining of the oral cavity, made of stratified squamous epithelium over a connective tissue lamina propria, with or without a submucosa.","classification":["Masticatory mucosa (about 25%): gingiva and hard palate – keratinised (ortho- or parakeratinised), firmly bound to bone as a mucoperiosteum","Lining mucosa (about 60%): lips, cheeks, floor of mouth, ventral tongue, soft palate, alveolar mucosa – non-keratinised, elastic, with submucosa","Specialised mucosa (about 15%): dorsum of tongue with papillae and taste buds"],"clinical_features":["Keratinised epithelium layers: stratum basale, spinosum, granulosum, corneum","Non-keratinised: basale, spinosum (prickle cell), intermedium, superficiale","Non-keratinocytes: melanocytes, Langerhans cells (antigen-presenting), Merkel cells (touch), lymphocytes","Tongue papillae: filiform (most numerous, no taste buds), fungiform, circumvallate (8–12, in front of sulcus terminalis, von Ebner glands), foliate","Fordyce''s spots: ectopic sebaceous glands in buccal mucosa and lips"],"viva_pearls":["Filiform papillae have no taste buds; circumvallate papillae have the most."]}'::jsonb, '[{"q":"Classify the oral mucosa.","keywords":["masticatory","lining","specialised|specialized","keratin"],"probe":"Which type covers the hard palate?"},{"q":"Describe the layers of keratinised and non-keratinised epithelium.","keywords":["basale|basal","spinosum|prickle","granulosum","corneum","intermedium|superficiale"],"probe":"Which layer is missing in non-keratinised epithelium?"},{"q":"Which non-keratinocyte cells are present?","keywords":["melanocyte","langerhans","merkel","lymphocyte"],"probe":"What is the function of Langerhans cells?"},{"q":"Describe the papillae of the tongue.","keywords":["filiform","fungiform","circumvallate","foliate","taste bud|von ebner"],"probe":"Which papillae have no taste buds?"}]'::jsonb, 'A biopsy report describes "orthokeratinised stratified squamous epithelium with long rete ridges and a dense lamina propria attached to periosteum". You are asked where in the mouth it came from.', array['oral histology']::text[]),
(61, 16, 'haemostasis', 'Haemostasis & Bleeding Disorders', 'must_know', '10-mark essay', '{"definition":"Haemostasis is the arrest of bleeding from an injured vessel by vascular constriction, platelet plug formation, coagulation and later fibrinolysis.","classification":["Vascular phase: reflex vasoconstriction","Platelet phase (primary haemostasis): adhesion to collagen via von Willebrand factor (GPIb), activation, aggregation (GPIIb/IIIa and fibrinogen), release of ADP and thromboxane A2","Coagulation (secondary haemostasis): extrinsic pathway (tissue factor, VII) and intrinsic pathway (XII, XI, IX, VIII) join the common pathway (X, V, II, I) → fibrin, stabilised by XIII","Fibrinolysis: plasminogen → plasmin by tissue plasminogen activator; breaks fibrin (D-dimers)"],"investigations":["Bleeding time / platelet count – platelet function","PT/INR – extrinsic and common (warfarin monitoring)","aPTT – intrinsic and common (heparin, haemophilia)","Factor assays; von Willebrand factor antigen and activity"],"clinical_features":["Haemophilia A (factor VIII) and B (IX, Christmas disease): X-linked recessive, joint and muscle bleeds, prolonged aPTT, normal PT and bleeding time","von Willebrand disease: commonest inherited bleeding disorder, autosomal; mucosal bleeding, prolonged bleeding time, aPTT may be prolonged","Platelet disorders: petechiae, mucosal bleeding"],"management":["Liaise with the haematologist; factor replacement before surgery for haemophilia","Desmopressin (DDAVP) for mild haemophilia A and type 1 vWD","Antifibrinolytics: tranexamic acid mouthwash and tablets","Local measures: atraumatic extraction, oxidised cellulose or gelatin sponge, sutures, pressure; avoid nerve blocks without cover (risk of haematoma); avoid NSAIDs"],"viva_pearls":["Tranexamic acid inhibits plasminogen activation; saliva is rich in fibrinolytic activity."]}'::jsonb, '[{"q":"Describe the phases of haemostasis.","keywords":["vasoconstrict|vascular","platelet","coagulation|clotting","fibrinoly","von willebrand|vwf"],"probe":"What does von Willebrand factor do?"},{"q":"Explain the coagulation cascade.","keywords":["extrinsic","intrinsic","common","tissue factor|vii","fibrin|thrombin"],"probe":"Which factors are in the intrinsic pathway?"},{"q":"Which tests assess bleeding?","keywords":["bleeding time","platelet count","pt|inr|prothrombin","aptt|ptt","factor assay"],"probe":"Which test is prolonged in haemophilia?"},{"q":"How will you extract a tooth in the haemophilic patient?","keywords":["haematolog|hematolog|physician","factor viii|factor replacement","tranexamic|antifibrinoly","desmopressin|ddavp","local measures|suture|gelatin|oxidised cellulose|nerve block"],"probe":"Why avoid an inferior alveolar nerve block without cover?"}]'::jsonb, 'A 16-year-old with haemophilia A needs extraction of a grossly decayed molar. His brother, on the other hand, bleeds after cuts and has easy bruising with a normal factor VIII.', array['physiology','medically compromised']::text[]),
(62, 16, 'facial-nerve', 'Facial Nerve', 'must_know', '10-mark essay', '{"definition":"The facial nerve (cranial nerve VII) is a mixed nerve: motor to the muscles of facial expression, taste from the anterior two-thirds of the tongue, secretomotor to the submandibular, sublingual and lacrimal glands, and sensation from part of the ear.","clinical_features":["Nuclei: motor nucleus (pons), superior salivatory nucleus, nucleus of tractus solitarius","Course: emerges at the cerebellopontine angle → internal acoustic meatus → facial canal (geniculate ganglion) → exits through the stylomastoid foramen → enters the parotid gland","Intracranial/intratemporal branches: greater petrosal nerve (lacrimal gland via pterygopalatine ganglion), nerve to stapedius, chorda tympani (taste anterior 2/3 tongue; submandibular and sublingual glands via submandibular ganglion)","Extracranial: posterior auricular, nerve to posterior belly of digastric and stylohyoid; terminal branches in the parotid – temporal, zygomatic, buccal, marginal mandibular, cervical (\"To Zanzibar By Motor Car\")"],"classification":["Upper motor neuron lesion (e.g. stroke): paralysis of the lower face only – forehead spared (bilateral cortical supply to the upper face)","Lower motor neuron lesion (Bell''s palsy, parotid tumour, LA in the parotid): whole half of the face, including the forehead; Bell''s phenomenon on trying to close the eye"],"management":["Transient facial palsy after a misplaced IANB (LA deposited in the parotid capsule): reassure, protect the eye with a patch or tape until it resolves in a few hours","Bell''s palsy: oral prednisolone within 72 hours, eye protection"],"viva_pearls":["The level of the lesion can be localised by checking lacrimation, stapedius reflex (hyperacusis) and taste."]}'::jsonb, '[{"q":"What are the components and functions of the facial nerve?","keywords":["facial expression|motor","taste|chorda tympani","submandibular|sublingual|lacrimal|secretomotor","anterior two thirds|anterior 2/3"],"probe":"Which branch carries taste?"},{"q":"Describe its course.","keywords":["internal acoustic meatus|internal auditory","facial canal|geniculate","stylomastoid","parotid"],"probe":"Through which foramen does it leave the skull?"},{"q":"Name its branches.","keywords":["greater petrosal","stapedius","chorda tympani","temporal|zygomatic","buccal|marginal mandibular|cervical"],"probe":"Name the five terminal branches."},{"q":"How do UMN and LMN palsies differ, and what happened after the nerve block?","keywords":["upper motor neuron|umn","forehead|spared","lower motor neuron|lmn|bell","parotid","reassure|eye patch|protect the eye"],"probe":"Why is the forehead spared in a stroke?"}]'::jsonb, 'After an inferior alveolar nerve block, a patient cannot close her eye or wrinkle her forehead on that side. In another patient, a stroke has paralysed only the lower face.', array['anatomy','cranial nerves']::text[]),
(63, 8, 'gypsum-products', 'Gypsum Products', 'must_know', '10-mark essay', '{"definition":"Gypsum products are calcium sulphate hemihydrates (CaSO₄·½H₂O) made by calcining gypsum (calcium sulphate dihydrate). Mixed with water they set back to the dihydrate.","classification":["ADA/ISO: Type I – impression plaster; II – model plaster (β-hemihydrate, porous, irregular particles); III – dental stone (α-hemihydrate, dense prismatic); IV – die stone, high strength, low expansion; V – die stone, high strength, high expansion (compensates alloy shrinkage)"],"clinical_features":["Manufacture: plaster – heated in an open kettle (110–130 °C); stone – heated under steam pressure in an autoclave; die stone – boiled in 30% calcium chloride solution (densite)","Water/powder ratio: plaster about 0.45–0.5, stone about 0.28–0.30, die stone about 0.22–0.24 – lower W/P ratio gives higher strength","Setting theory: dissolution–precipitation (crystalline theory)","Setting expansion (crystal growth outward); hygroscopic expansion is greater when setting under water","Accelerators: potassium sulphate, terra alba (set gypsum), NaCl (low concentrations); retarders: borax, citrates, colloids","Wet strength vs dry strength: dry strength is about twice the wet strength"],"management":["Mix measured powder into water; vacuum mix to avoid voids","Pour soon after disinfection; wait about 45–60 minutes before separating","Store powder in airtight containers – moisture slows the set"],"viva_pearls":["Type IV die stone has the lowest W/P ratio and highest strength with low expansion."]}'::jsonb, '[{"q":"What are gypsum products, and how are they classified?","keywords":["hemihydrate","dihydrate","type iv|die stone","plaster","stone"],"probe":"What is type V used for?"},{"q":"How do plaster, stone and die stone differ in manufacture?","keywords":["open kettle|calcin","autoclave|steam","calcium chloride","alpha|α","beta|β"],"probe":"Which one is made in an autoclave?"},{"q":"What affects setting time and strength?","keywords":["water powder ratio|w/p|water/powder","accelerat|potassium sulphate|terra alba","retard|borax|citrate","spatulat|mixing"],"probe":"Name an accelerator and a retarder."},{"q":"Explain setting and hygroscopic expansion.","keywords":["setting expansion","crystal","hygroscopic","water|under water"],"probe":"Why is hygroscopic expansion greater?"}]'::jsonb, 'Your die cracked when you separated it from an alginate impression too early, and a plaster cast you poured is soft and chalky. You are asked about gypsum and how to handle it.', array['materials','lab']::text[]),
(64, 8, 'elastomeric-impressions', 'Elastomeric Impression Materials', 'must_know', '10-mark essay', '{"definition":"Elastomers are rubber-like, non-aqueous impression materials that polymerise from liquid polymers into elastic solids, giving accurate impressions of undercut preparations.","classification":["Polysulphide (first): long working time, high tear strength, unpleasant odour, lead dioxide catalyst, by-product water","Condensation silicone: by-product ethyl alcohol → more shrinkage; pour quickly","Addition silicone (polyvinyl siloxane): most dimensionally stable, can be poured repeatedly; hydrophobic unless surfactants added; latex gloves (sulphur) inhibit setting; may release hydrogen – wait before pouring","Polyether: hydrophilic, stiff when set (hard to remove from undercuts), absorbs water – do not store wet","Viscosities: putty, heavy, medium (monophase), light body"],"clinical_features":["Order of dimensional stability: addition silicone > polyether > polysulphide > condensation silicone","Most hydrophilic: polyether","Highest tear strength: polysulphide"],"management":["Techniques: putty–wash (one- or two-step), dual-mix, monophase, multiple mix","Gingival retraction before impression; custom tray or rigid stock tray with adhesive","Disinfect (e.g. hypochlorite or glutaraldehyde spray for most; polyether briefly, not prolonged immersion)"],"viva_pearls":["Sulphur compounds in latex gloves inhibit the platinum catalyst of addition silicones."]}'::jsonb, '[{"q":"Classify elastomeric impression materials.","keywords":["polysulphide|polysulfide","condensation silicone","addition silicone|polyvinyl siloxane|pvs","polyether"],"probe":"Which one was introduced first?"},{"q":"Compare their dimensional stability.","keywords":["addition","by product|by-product","alcohol","water","repeated|pour"],"probe":"Why does condensation silicone shrink?"},{"q":"What are the special problems with addition silicones and polyethers?","keywords":["latex|sulphur|sulfur","hydrogen","hydrophobic|surfactant","stiff|rigid","absorb water|hydrophilic"],"probe":"Why do latex gloves matter?"},{"q":"Describe the impression techniques.","keywords":["putty","wash|light body","monophase","dual mix|double mix","retraction|custom tray"],"probe":"What is a two-step putty–wash?"}]'::jsonb, 'You are taking a final impression for a three-unit bridge and must choose between addition silicone, condensation silicone, polyether and polysulphide.', array['impression materials','fixed prosthodontics']::text[]),
(65, 8, 'composite-resins', 'Composite Resins & Bonding', 'must_know', '10-mark essay', '{"definition":"A composite resin is a tooth-coloured restorative material made of a resin matrix (Bis-GMA, UDMA, TEGDMA), inorganic filler particles and a silane coupling agent, set by free-radical polymerisation.","classification":["By filler size: macrofilled (traditional), microfilled (best polish, low strength), hybrid and microhybrid (all-purpose), nanofilled/nanohybrid","By viscosity: flowable, packable/condensable, bulk-fill","By curing: light (camphorquinone + amine), chemical, dual","Bonding agents (generations I–VIII); by strategy: etch-and-rinse (total etch), self-etch, universal"],"clinical_features":["Polymerisation shrinkage (about 2–3%) causes stress, microleakage and post-operative sensitivity; C-factor (bonded/unbonded surfaces) – highest (5) in Class I","Oxygen-inhibited layer on the surface","Hybrid layer (Nakabayashi): resin interlocked with demineralised collagen"],"management":["Etch enamel with 37% phosphoric acid 15–30 s (dentine 15 s), rinse, keep dentine moist (\"wet bonding\")","Apply primer and adhesive, light cure","Incremental placement in layers of 2 mm or less (oblique technique) to reduce shrinkage stress; bulk-fill up to 4–5 mm","Matrix and wedge for contact; finish and polish"],"viva_pearls":["Silane bonds the filler to the matrix; without it fillers pull out and wear increases."]}'::jsonb, '[{"q":"What is the composition of composite resin?","keywords":["bis gma|bis-gma|udma","filler","silane|coupling","camphorquinone|initiator","tegdma|diluent"],"probe":"What does silane do?"},{"q":"Classify composites.","keywords":["macrofill|macro","microfill|micro","hybrid","nano","flowable|packable|bulk"],"probe":"Which type polishes best?"},{"q":"What is polymerisation shrinkage and the C-factor?","keywords":["shrinkage","stress","c factor|c-factor|configuration","bonded|unbonded","incremental|2 mm"],"probe":"Which cavity class has the highest C-factor?"},{"q":"How does bonding to dentine work?","keywords":["etch|phosphoric","primer","hybrid layer|nakabayashi","collagen","wet bonding|moist"],"probe":"What is the hybrid layer?"}]'::jsonb, 'You are restoring a Class II cavity on 25 with composite. The patient asks why it needs "so many steps" compared with amalgam.', array['restorative','adhesion']::text[]),
(66, 8, 'dental-ceramics', 'Dental Ceramics', 'desirable', '10-mark essay', '{"definition":"Dental ceramics are inorganic, non-metallic materials (oxides of silicon, aluminium, zirconium and others) processed at high temperature, valued for aesthetics, biocompatibility and wear resistance but brittle in tension.","classification":["By fusing temperature: high (> 1300 °C), medium (1101–1300 °C), low (850–1100 °C), ultra-low (< 850 °C)","By composition: feldspathic porcelain; glass-ceramics (leucite-reinforced, lithium disilicate); polycrystalline (alumina, zirconia)","By use: metal-ceramic (PFM), all-ceramic, denture teeth","By processing: sintered, heat-pressed, slip-cast (In-Ceram), CAD/CAM milled"],"clinical_features":["Metal–ceramic bond: mainly chemical (oxide layer), also mechanical and compressive (coefficient of thermal expansion of metal slightly higher than porcelain)","Strengthening: dispersion of crystalline phase, ion exchange (chemical tempering), thermal tempering, transformation toughening of zirconia (tetragonal → monoclinic with volume expansion stops cracks), glazing","Lithium disilicate: good aesthetics and strength for anterior and premolar crowns; can be etched (hydrofluoric acid) and bonded","Zirconia: highest strength – posterior bridges; more opaque; not etchable with HF (use air abrasion and MDP primer)"],"management":["Etch silica-based ceramics with hydrofluoric acid then silane before resin cementation"],"viva_pearls":["Zirconia toughening = transformation toughening (stress-induced tetragonal-to-monoclinic change)."]}'::jsonb, '[{"q":"Classify dental ceramics.","keywords":["feldspathic","glass ceramic|lithium disilicate|leucite","zirconia|alumina|polycrystalline","fusing temperature|high fusing|low fusing"],"probe":"Give an example of a glass-ceramic."},{"q":"How does porcelain bond to metal?","keywords":["chemical|oxide","mechanical","compressive","thermal expansion|coefficient"],"probe":"Which bond is the most important?"},{"q":"How are ceramics strengthened?","keywords":["transformation toughening|tetragonal|monoclinic","ion exchange|chemical tempering","thermal tempering","glaz","crystalline|dispersion"],"probe":"What is transformation toughening?"},{"q":"Which ceramic would you choose for each patient, and how will you cement it?","keywords":["lithium disilicate|feldspathic|anterior","zirconia|posterior","hydrofluoric|hf","silane","mdp|air abrasion|sandblast"],"probe":"Can zirconia be etched with HF?"}]'::jsonb, 'A patient wants an all-ceramic crown on a discoloured upper central incisor, and another needs a posterior three-unit bridge in ceramic.', array['prosthodontics','aesthetics']::text[]),
(67, 4, 'endodontic-emergencies', 'Endodontic Emergencies & Flare-ups', 'must_know', '5-mark short note', '{"definition":"An endodontic emergency is pain and/or swelling needing unscheduled treatment. A flare-up is an acute exacerbation of pain or swelling after the start or continuation of endodontic treatment.","classification":["Before treatment: symptomatic irreversible pulpitis, acute apical periodontitis, acute apical abscess, cracked tooth, trauma","During or after treatment (flare-ups): within hours to days of an appointment"],"etiology":["Mechanical: over-instrumentation, extrusion of debris or irrigant beyond the apex (hypochlorite accident), high restoration","Chemical: irritant medicaments or irrigants","Microbial: change in the periapical microbial balance, incomplete debridement","Risk factors: pre-operative pain, necrotic pulp with periapical lesion, retreatment, female patients, anxiety"],"management":["Irreversible pulpitis: pulpectomy (or pulpotomy as emergency), calcium hydroxide dressing, analgesics","Acute apical abscess: drainage through the canal or by incision; antibiotics only if systemic spread or fever","Flare-up: reassure, relieve occlusion, re-open and irrigate if needed, drain any swelling, calcium hydroxide dressing, analgesics (NSAID plus paracetamol); antibiotics only with systemic signs","Hypochlorite accident: stop, irrigate with saline, cold then warm compresses, analgesics, antibiotics if needed, reassure; refer if airway involvement"],"viva_pearls":["Most flare-ups are caused by microbes pushed beyond the apex; antibiotics do not relieve pulpitis pain."]}'::jsonb, '[{"q":"What is a flare-up?","keywords":["acute","pain|swelling","after|during treatment","unscheduled"],"probe":"When does it typically occur?"},{"q":"What causes flare-ups?","keywords":["mechanical|over instrumentation|over-instrumentation","chemical|irrigant","microbial|bacteria","extru|beyond the apex","pre operative|pre-operative|necrotic"],"probe":"Which factor is most common?"},{"q":"How will you manage this patient?","keywords":["occlusion|relieve","drain|incision","irrigat","calcium hydroxide","analgesic|nsaid|antibiotic"],"probe":"When would you give antibiotics?"},{"q":"How do you manage a sodium hypochlorite accident?","keywords":["stop","saline","cold|warm compress","analgesic|antibiotic","reassure|refer|airway"],"probe":"What are the signs of a hypochlorite accident?"}]'::jsonb, 'Two days after you started root canal treatment on 36, the patient returns with severe pain, swelling of the cheek and a tooth that feels "high".', array['endodontics','pain']::text[]),
(68, 11, 'cephalometrics', 'Cephalometrics', 'must_know', '10-mark essay', '{"definition":"Cephalometrics is the measurement of the head from standardised lateral and frontal skull radiographs (cephalograms), introduced by Broadbent (USA) and Hofrath (Germany) in 1931, using a cephalostat to keep the head in a fixed, reproducible position.","classification":["Landmarks: sella (S), nasion (N), point A (subspinale), point B (supramentale), pogonion, menton, gnathion, gonion, porion, orbitale, ANS, PNS, articulare","Planes: SN plane, Frankfort horizontal (porion–orbitale), mandibular plane, palatal plane, occlusal plane","Analyses: Downs (first), Steiner, Tweed (diagnostic triangle), Wits appraisal, McNamara, Ricketts, Burstone"],"clinical_features":["SNA 82° ± 2 (maxilla to cranial base); SNB 80° ± 2 (mandible); ANB 2° (0–4°): > 4° Class II, < 0° Class III","Wits: AO–BO on the occlusal plane – about 0 mm in females and −1 mm in males; avoids the effect of nasion position","Tweed: FMA 25°, IMPA 90°, FMIA 65°","Upper incisor to NA 4 mm / 22°; lower incisor to NB 4 mm / 25° (Steiner); interincisal angle about 130°","High FMA (> 30°) = vertical (long face) grower; low = horizontal grower"],"management":["Uses: diagnosis and classification of skeletal and dental problems, treatment planning, growth prediction, evaluating treatment progress and results, research"],"viva_pearls":["In this case ANB = 6°: skeletal Class II due to a retrognathic mandible (SNB 76°), with a vertical growth pattern (FMA 32°)."]}'::jsonb, '[{"q":"What is cephalometrics, and who introduced it?","keywords":["broadbent","hofrath","1931","cephalostat","standardi"],"probe":"How is the head kept in a fixed position?"},{"q":"Name the important landmarks and planes.","keywords":["sella","nasion","point a|subspinale","point b|supramentale","frankfort|mandibular plane"],"probe":"How is the Frankfort plane defined?"},{"q":"What do SNA, SNB and ANB tell you?","keywords":["82","80","anb","class ii|class 2","maxilla|mandible"],"probe":"What does an ANB of 6° mean?"},{"q":"Interpret this patient''s values.","keywords":["class ii|class 2","retrognathic|retrusive mandible","vertical|high angle|long face","fma|tweed","wits"],"probe":"Why use the Wits appraisal as well?"}]'::jsonb, 'A 13-year-old''s lateral cephalogram tracing shows SNA 82°, SNB 76°, an FMA of 32° and proclined upper incisors.', array['diagnosis','radiography']::text[]),
(69, 11, 'biology-of-tooth-movement', 'Biology of Tooth Movement', 'must_know', '10-mark essay', '{"definition":"Orthodontic tooth movement results from remodelling of the PDL and alveolar bone in response to sustained force: resorption on the pressure side and deposition on the tension side.","classification":["Theories: pressure–tension theory (Schwarz), bone-bending (piezoelectric) theory (Farrar), biological electricity theory","Types of movement: tipping (uncontrolled and controlled), bodily translation, root movement (torque), rotation, extrusion, intrusion","Optimal forces (approx.): tipping 35–60 g, bodily 70–120 g, root uprighting 50–100 g, rotation 35–60 g, extrusion 35–60 g, intrusion 10–20 g (lowest)"],"clinical_features":["Light, continuous force: PDL compressed but vital → frontal (direct) resorption by osteoclasts → smooth movement","Heavy force: PDL vessels occluded → hyalinisation (cell-free, glassy zone) → undermining (indirect) resorption from the marrow side after a lag phase → tooth moves suddenly; more pain and root resorption","Phases (Burstone): initial (displacement in the PDL), lag (hyalinisation), post-lag (movement)","Mediators: prostaglandins, RANKL/OPG, cytokines (IL-1, TNF-α)"],"management":["Use light, continuous forces; reactivate at appropriate intervals","Avoid NSAIDs in large doses during treatment (they slow movement by blocking prostaglandins); paracetamol preferred"],"viva_pearls":["Intrusion needs the lightest force because it concentrates force at the apex."]}'::jsonb, '[{"q":"What are the theories of tooth movement?","keywords":["pressure tension|pressure-tension|schwarz","bone bending|piezoelectric|farrar","bioelectric|biological electricity"],"probe":"Explain the pressure–tension theory."},{"q":"What happens with light versus heavy forces?","keywords":["frontal|direct resorption","hyalin","undermining|indirect","lag","root resorption|pain"],"probe":"What is hyalinisation?"},{"q":"What are the optimal forces for different movements?","keywords":["tipping","bodily","intrusion","10|20 g|grams","extrusion|rotation"],"probe":"Which movement needs the least force?"},{"q":"Explain what happened in this patient.","keywords":["heavy force","hyalin","lag phase|lag","undermining","light|continuous"],"probe":"How would you avoid it?"}]'::jsonb, 'During canine retraction with heavy forces, a patient complains of pain and the tooth stops moving for several weeks, then moves suddenly.', array['orthodontic forces']::text[]),
(70, 1, 'forensic-odontology', 'Forensic Odontology', 'desirable', '5-mark short note', '{"definition":"Forensic odontology is the branch of dentistry that handles, examines and presents dental evidence in the interest of justice: identification, age estimation, bite marks and abuse.","classification":["Comparative identification: post-mortem dental findings compared with ante-mortem records (charts, radiographs, casts)","Reconstructive (profiling): age, sex, ethnicity, habits when no records exist","Bite-mark analysis","Child abuse, neglect and elder abuse recognition","Mass disaster victim identification (DVI, Interpol forms)"],"clinical_features":["Teeth resist fire, decomposition and trauma, so they are valuable for identification","Age estimation in children: tooth development and eruption (Demirjian, Schour and Massler, Moorrees)","Age estimation in adults: Gustafson''s six criteria (attrition, periodontosis, secondary dentine, cementum apposition, root resorption, root transparency); Kvaal (pulp/tooth ratio); root dentine translucency; aspartic acid racemisation","Sex determination: Barr bodies and Y chromatin in pulp cells, DNA from pulp; odontometric measurements (canines)","Others: cheiloscopy (lip prints, Suzuki and Tsuchihashi), rugoscopy (palatal rugae)"],"management":["Dental records are legal documents – keep accurate charts and radiographs","Bite marks: photograph with scale (ABFO No. 2 ruler), swab for saliva DNA, take impressions"],"viva_pearls":["Gustafson (1950) described the first scientific dental age-estimation method for adults."]}'::jsonb, '[{"q":"What is forensic odontology, and why are teeth useful?","keywords":["justice|legal|law","identification","resist|fire|decompos","records"],"probe":"Why do teeth survive fires?"},{"q":"How is a body identified dentally?","keywords":["ante mortem|ante-mortem|antemortem","post mortem|post-mortem|postmortem","comparative","reconstructive|profil","radiograph|records"],"probe":"What if there are no dental records?"},{"q":"How would you estimate age?","keywords":["eruption|development","demirjian|schour|massler","gustafson","kvaal|pulp","translucency|racemi"],"probe":"Name Gustafson''s criteria."},{"q":"What other dental methods help identification?","keywords":["cheiloscopy|lip print","rugoscopy|rugae","bite mark","dna|barr|sex"],"probe":"What is cheiloscopy?"}]'::jsonb, 'After a bus fire, the police ask your department to help identify several badly burnt bodies and estimate the age of an unidentified teenager.', array['identification']::text[]),
(71, 4, 'cavity-design', 'Principles of Cavity Preparation (G.V. Black)', 'must_know', '10-mark essay', '{"definition":"Cavity preparation is the mechanical alteration of a defective tooth to receive a restoration that restores form and function. G.V. Black, the \"father of operative dentistry\", set out classic classifications and principles; modern practice adds minimal intervention.","classification":["G.V. Black classification: Class I – pits and fissures (occlusal, buccal/lingual pits, palatal of upper incisors); II – proximal surfaces of premolars and molars; III – proximal of incisors/canines without the incisal angle; IV – with the incisal angle; V – gingival third of facial or lingual surfaces; VI (Simon) – incisal edges and cusp tips","Mount and Hume (site and size): sites 1 (pit/fissure), 2 (contact area), 3 (cervical); sizes 0–4"],"clinical_features":["Black''s steps – initial: outline form, resistance form, retention form, convenience form","Final: removal of remaining carious dentine, pulp protection, secondary resistance and retention, finishing of walls and margins, cleaning (toilet) of the cavity","\"Extension for prevention\" (Black) – now replaced by \"prevention of extension\" / minimally invasive preparation"],"management":["Amalgam Class II: box with gingival seat, axial wall, buccal and lingual walls clearing contact; cavosurface angle 90° (butt joint) because amalgam is brittle in thin section; occlusal dovetail or retention grooves; rounded axiopulpal line angle","Isthmus about one-quarter to one-third of the intercuspal width","Depth: 1.5–2 mm (pulpal floor about 0.2 mm into dentine)"],"viva_pearls":["Resistance form prevents the tooth and restoration from fracturing; retention form prevents displacement."]}'::jsonb, '[{"q":"Give G.V. Black''s classification of cavities.","keywords":["class i|class 1|pit","class ii|class 2|proximal","class iii|class iv|incisal angle","class v|cervical|gingival third","class vi|simon"],"probe":"Who added Class VI?"},{"q":"What are the steps of cavity preparation?","keywords":["outline form","resistance form","retention form","convenience form","carious dentin|pulp protection|finishing"],"probe":"What is resistance form?"},{"q":"What are the features of a Class II amalgam preparation?","keywords":["gingival seat|box","axial","butt joint|90","dovetail|retention groove","isthmus|1.5|depth"],"probe":"Why a 90° cavosurface angle?"},{"q":"How has cavity design changed since Black?","keywords":["extension for prevention","minimal|minimally invasive","prevention of extension","mount|hume|site and size"],"probe":"What is the Mount and Hume classification?"}]'::jsonb, 'A 25-year-old has proximal caries on the mesial surface of 36 with an intact marginal ridge broken down on the radiograph. You plan an amalgam restoration.', array['operative dentistry']::text[]),
(72, 1, 'oral-candidiasis', 'Oral Candidiasis', 'must_know', '5-mark short note', '{"definition":"Oral candidiasis is an opportunistic infection, usually by Candida albicans, which converts from commensal yeast to invasive hyphal form when local or systemic host defences fail.","classification":["Acute: pseudomembranous (thrush – white plaques that wipe off), acute erythematous (antibiotic sore mouth)","Chronic: chronic erythematous (denture stomatitis), chronic hyperplastic (candidal leukoplakia – does not wipe off, potentially malignant), median rhomboid glossitis","Angular cheilitis (with Staphylococcus aureus)","Chronic mucocutaneous candidiasis syndromes","Newton''s classification of denture stomatitis: type I – pinpoint hyperaemia; II – diffuse erythema; III – papillary hyperplasia"],"etiology":["Local: dentures (especially worn at night), xerostomia, inhaled steroids, smoking, poor hygiene","Systemic: extremes of age, broad-spectrum antibiotics, diabetes, iron/folate/B12 deficiency, HIV, immunosuppression, chemotherapy"],"investigations":["Smear with PAS or Gram stain (hyphae), KOH preparation, culture (Sabouraud agar), germ tube test; biopsy for hyperplastic type"],"management":["Remove the cause: denture hygiene, remove dentures at night, soak in chlorhexidine or hypochlorite, rinse after steroid inhalers","Topical: nystatin suspension, miconazole gel (beware warfarin interaction), amphotericin lozenges","Systemic: fluconazole for resistant or immunocompromised cases","Angular cheilitis: miconazole (antifungal and anti-staphylococcal) cream"],"viva_pearls":["HIV-positive patients with oral candidiasis: it is an early marker of immune suppression."]}'::jsonb, '[{"q":"What causes oral candidiasis and what predisposes to it?","keywords":["candida albicans|candida","opportunistic","denture","antibiotic|steroid","diabet|hiv|immun"],"probe":"Which inhaled drug predisposes to it?"},{"q":"Classify oral candidiasis.","keywords":["pseudomembranous|thrush","erythematous","hyperplastic","angular cheilitis","median rhomboid"],"probe":"Which type does not wipe off?"},{"q":"How will you confirm the diagnosis?","keywords":["smear|cytology","pas|periodic acid","koh|potassium hydroxide","culture|sabouraud","biopsy"],"probe":"What stain shows hyphae?"},{"q":"How will you treat this patient?","keywords":["denture hygiene|remove denture|night","nystatin","miconazole","fluconazole","rinse|inhaler"],"probe":"What drug interaction matters with miconazole?"}]'::jsonb, 'A 72-year-old denture wearer on inhaled steroids has a red, sore palate beneath his upper denture, cracks at the corners of the mouth, and white plaques on the buccal mucosa that wipe off leaving a raw surface.', array['fungal infection']::text[]),
(73, 2, 'salivary-gland-disorders', 'Xerostomia & Sialolithiasis', 'must_know', '10-mark essay', '{"definition":"Sialolithiasis is the formation of calcified stones in a salivary duct or gland. Xerostomia is the subjective feeling of oral dryness, usually from salivary hypofunction (unstimulated flow < 0.1 mL/min).","etiology":["Sialoliths: most in the submandibular gland (about 80–90%) – its saliva is more alkaline, mucous and calcium-rich, and Wharton''s duct is long and runs uphill","Xerostomia: drugs (antidepressants, antihistamines, antihypertensives, anticholinergics – commonest), Sjögren''s syndrome, head and neck radiotherapy, diabetes, dehydration, anxiety, ageing (indirectly)"],"clinical_features":["Sialolith: \"mealtime syndrome\" – pain and swelling on eating; palpable stone in the floor of the mouth; may get secondary sialadenitis with pus","Xerostomia: dry, sticky mucosa, difficulty speaking and swallowing, burning, altered taste, candidiasis, cervical caries, denture retention problems","Sjögren''s syndrome: primary (dry eyes and mouth) or secondary (with RA or SLE); anti-Ro (SSA), anti-La (SSB); labial gland biopsy (focal lymphocytic sialadenitis); risk of MALT lymphoma"],"investigations":["Sialolith: lower occlusal radiograph (submandibular stones are usually radiopaque; parotid stones are often radiolucent), ultrasound, sialography, sialendoscopy","Xerostomia: sialometry, Schirmer test, serology, labial gland biopsy"],"management":["Sialolith: sialogogues, massage and hydration; intraoral removal for distal duct stones; sialendoscopy; excision of the gland for intraglandular or recurrent stones","Xerostomia: treat cause/review drugs, sips of water, saliva substitutes, sugar-free gum, pilocarpine or cevimeline, high-fluoride toothpaste and fluoride varnish, antifungals as needed"],"viva_pearls":["Sialography is contraindicated in acute sialadenitis."]}'::jsonb, '[{"q":"Why are most salivary stones in the submandibular gland?","keywords":["submandibular","alkaline","mucous|viscous","calcium","uphill|long duct|wharton"],"probe":"What about the duct makes stones likely?"},{"q":"How does a sialolith present and how will you investigate it?","keywords":["meal|eating","swelling|pain","occlusal radiograph|radiograph","ultrasound|sialograph","sialendoscop"],"probe":"Which radiograph would you take?"},{"q":"What causes xerostomia?","keywords":["drug|medication","sjogren|sjögren","radiotherapy|radiation","diabet","dehydrat|anxiety"],"probe":"What is the commonest cause?"},{"q":"How will you manage the second patient?","keywords":["saliva substitute","pilocarpine|cevimeline","fluoride","anti ro|anti-ro|ssa|biopsy|schirmer","lymphoma|refer"],"probe":"Which antibodies would you check?"}]'::jsonb, 'A 45-year-old has painful swelling under the left side of the jaw every time she eats, which settles after an hour. A second patient, a 60-year-old woman, has dry mouth, dry eyes and rampant cervical caries.', array['salivary glands']::text[]),
(74, 2, 'radiation-protection', 'Radiation Protection in Dentistry', 'must_know', '5-mark short note', '{"definition":"Radiation protection aims to prevent deterministic effects and keep the risk of stochastic effects (cancer, genetic) as low as reasonably achievable (ALARA, now also ALADA – as low as diagnostically acceptable).","classification":["Principles (ICRP): justification, optimisation, dose limitation","Effects: deterministic (threshold, severity rises with dose – e.g. erythema, cataract) vs stochastic (no threshold, probability rises with dose – cancer, genetic effects)"],"clinical_features":["Patient protection: selection criteria (only justified radiographs), fastest image receptor (F-speed film or digital), rectangular collimation (reduces dose by up to about 60%), long source-to-skin distance (long cone, paralleling), filtration (aluminium – removes low-energy rays), thyroid collar, correct exposure and processing to avoid retakes","Operator protection: stand at least 2 m (6 feet) away, at 90–135° to the primary beam, or behind a protective barrier; never hold the film; personal dosimeters (TLD badges)","Dose limits (ICRP): occupational 20 mSv per year (averaged over 5 years); public 1 mSv per year"],"management":["Pregnancy: dental radiographs give negligible dose to the fetus with good technique; take only those that are clinically necessary; a lead apron is reassuring but not essential with modern equipment","Inverse square law: doubling the distance cuts intensity to one quarter"],"viva_pearls":["Rectangular collimation is the single most effective dose-reducing measure for intraoral radiographs."]}'::jsonb, '[{"q":"What are the principles of radiation protection?","keywords":["alara|alada","justification","optimi","dose limit"],"probe":"What does ALARA stand for?"},{"q":"How do deterministic and stochastic effects differ?","keywords":["deterministic","stochastic","threshold","cancer|genetic","probability|severity"],"probe":"Which has no threshold?"},{"q":"How do you reduce the patient''s dose?","keywords":["collimat|rectangular","fast film|f speed|f-speed|digital","filtrat|aluminium","thyroid collar","long cone|selection criteria|retake"],"probe":"What does filtration do?"},{"q":"How should the operator protect herself?","keywords":["2 m|6 feet|distance","90|135|angle","barrier","dosimeter|tld|badge","never hold"],"probe":"Where exactly should she stand?"}]'::jsonb, 'A pregnant patient asks whether her dental radiograph is safe, and your new clinic assistant asks where she should stand during exposures.', array['radiology','safety']::text[]),
(75, 1, 'tooth-anomalies', 'Developmental Anomalies of Teeth', 'must_know', '10-mark essay', '{"definition":"Developmental disturbances of teeth are abnormalities of number, size, shape, structure, eruption or colour that arise during odontogenesis from genetic or environmental causes.","classification":["Number: anodontia, hypodontia/oligodontia (third molars, lower second premolars, upper laterals most often missing), hyperdontia (mesiodens – commonest supernumerary, distomolar, paramolar)","Size: microdontia (peg laterals), macrodontia","Shape: gemination (one tooth germ tries to divide – normal tooth count), fusion (two germs join – one fewer tooth), concrescence (joined by cementum only), dilaceration, taurodontism, dens invaginatus (dens in dente), dens evaginatus, talon cusp, enamel pearls","Structure: amelogenesis imperfecta (hypoplastic, hypomaturation, hypocalcified), dentinogenesis imperfecta (opalescent teeth, obliterated pulps, with osteogenesis imperfecta in type I), dentin dysplasia, regional odontodysplasia (\"ghost teeth\"), enamel hypoplasia (Turner''s tooth, fluorosis)","Eruption: natal and neonatal teeth, impaction, ankylosis (infraocclusion)"],"clinical_features":["Gemination vs fusion: count the teeth – gemination keeps the normal number; fusion reduces it by one","Dens invaginatus is common in upper laterals – the pit allows early pulp infection; seal it prophylactically"],"management":["Mesiodens: remove to allow eruption of the incisors; orthodontic traction if needed","Peg laterals: composite build-up, veneers or crowns","Seal the palatal pit of dens invaginatus"],"viva_pearls":["Turner''s tooth = localised enamel hypoplasia of a permanent tooth from infection or trauma to its primary predecessor."]}'::jsonb, '[{"q":"Classify developmental anomalies of teeth.","keywords":["number","size","shape","structure","eruption|colour"],"probe":"Give an example of each."},{"q":"How do gemination, fusion and concrescence differ?","keywords":["gemination","fusion","concrescence","cementum","count|number of teeth"],"probe":"How will counting the teeth help?"},{"q":"Describe amelogenesis and dentinogenesis imperfecta.","keywords":["amelogenesis","hypoplastic|hypomaturation|hypocalcif","dentinogenesis","opalescent","osteogenesis imperfecta|pulp obliterat"],"probe":"Which systemic disease goes with dentinogenesis imperfecta?"},{"q":"How will you manage this child?","keywords":["mesiodens","extract|remove","dens invaginatus|pit","seal","composite|veneer|build up"],"probe":"Why seal the palatal pit?"}]'::jsonb, 'A 9-year-old has an extra tooth between the upper central incisors that has delayed their eruption, and his upper lateral incisors are peg-shaped with a deep pit on the palatal surface.', array['developmental']::text[]),
(76, 12, 'anaemia', 'Anaemia: Dental Relevance', 'must_know', '10-mark essay', '{"definition":"Anaemia is a reduction in haemoglobin concentration below the normal for age and sex (WHO: < 13 g/dL in men, < 12 g/dL in non-pregnant women), reducing the oxygen-carrying capacity of blood.","classification":["Microcytic hypochromic (low MCV): iron deficiency (commonest), thalassaemia, sideroblastic, anaemia of chronic disease (sometimes)","Normocytic: acute blood loss, chronic disease, haemolytic, aplastic, renal failure","Macrocytic (high MCV): vitamin B12 deficiency (pernicious anaemia), folate deficiency, alcohol, liver disease","Haemolytic: sickle cell disease, thalassaemia, G6PD deficiency, hereditary spherocytosis"],"clinical_features":["General: fatigue, pallor, breathlessness, palpitations, koilonychia (iron)","Oral: atrophic glossitis (depapillated smooth red tongue), angular cheilitis, recurrent aphthae, candidiasis, burning mouth, pallor of mucosa","B12: Hunter''s (Moeller''s) glossitis, neuropathy, paraesthesia","Plummer–Vinson syndrome: iron deficiency, dysphagia (oesophageal web), glossitis – potentially malignant (post-cricoid cancer)","Thalassaemia major: \"chipmunk\" facies, maxillary expansion, \"hair-on-end\" skull radiograph; sickle cell: \"step-ladder\" trabeculae, bone infarcts"],"investigations":["Full blood count, MCV, peripheral smear, serum ferritin (low in iron deficiency), B12 and folate, haemoglobin electrophoresis"],"management":["Refer to the physician to find and treat the cause (e.g. menorrhagia, GI blood loss, diet)","Dental: avoid elective GA if Hb < 10 g/dL; delayed healing and infection risk; in sickle cell avoid hypoxia, dehydration, cold, long stressful sessions"],"viva_pearls":["This patient most likely has iron-deficiency anaemia (koilonychia, glossitis, angular cheilitis)."]}'::jsonb, '[{"q":"Define and classify anaemia.","keywords":["haemoglobin|hemoglobin","microcytic","normocytic","macrocytic","haemolytic|hemolytic"],"probe":"What is the WHO cut-off for women?"},{"q":"What are the oral manifestations of anaemia?","keywords":["glossitis|depapillat","angular cheilitis","aphth|ulcer","candid","pallor|burning"],"probe":"What does the tongue look like?"},{"q":"What is Plummer–Vinson syndrome?","keywords":["iron","dysphagia","web","glossitis","malignan|carcinoma"],"probe":"Why is it important?"},{"q":"How will you investigate and manage this patient?","keywords":["full blood count|cbc|fbc","ferritin","mcv|smear","physician|refer","iron|cause"],"probe":"What would ferritin show?"}]'::jsonb, 'A 24-year-old woman has a smooth, sore red tongue, angular cheilitis, recurrent mouth ulcers, tiredness and spoon-shaped nails. Her haemoglobin is 8.5 g/dL.', array['haematology','medically compromised']::text[]),
(77, 5, 'furcation-involvement', 'Furcation Involvement', 'must_know', '10-mark essay', '{"definition":"Furcation involvement is the invasion of the bifurcation or trifurcation of multirooted teeth by periodontal disease, with bone loss in the inter-radicular area.","classification":["Glickman: grade I – incipient, pocket into the flute but no bone loss in the furcation; II – cul-de-sac (probe enters but not through); III – through-and-through but covered by soft tissue; IV – through-and-through and clinically visible","Hamp: degree 1 – horizontal loss < 3 mm; 2 – > 3 mm but not through; 3 – through-and-through","Tarnow and Fletcher: vertical subclass A (0–3 mm), B (4–6 mm), C (≥ 7 mm)"],"etiology":["Plaque-induced periodontitis; local factors: cervical enamel projections (Masters and Hoskins), enamel pearls, short root trunk, accessory canals (perio-endo), trauma from occlusion"],"investigations":["Nabers probe (curved) for horizontal assessment; radiographs underestimate furcation bone loss","Mandibular molars: approach from buccal and lingual; maxillary molars: buccal, mesiopalatal and distopalatal"],"management":["Grade I: scaling, root planing, odontoplasty, furcationplasty","Grade II: regenerative therapy (GTR, bone grafts) – best in mandibular molars; or furcationplasty","Grade III/IV: tunnel preparation, root resection (amputation) or hemisection (mandibular molars) with endodontics, or extraction and implant"],"viva_pearls":["This patient has Glickman grade III furcation involvement on 46."]}'::jsonb, '[{"q":"What is furcation involvement?","keywords":["furcation","multirooted|multi-rooted","bone loss","bifurcation|trifurcation|inter radicular|inter-radicular"],"probe":"Which teeth can be affected?"},{"q":"Give Glickman''s classification.","keywords":["glickman","grade i|incipient","cul de sac|cul-de-sac","through and through|through-and-through","visible|soft tissue"],"probe":"How do grade III and IV differ?"},{"q":"What local factors predispose to it, and how do you examine it?","keywords":["enamel projection|cervical enamel","enamel pearl","root trunk","nabers","radiograph"],"probe":"Which probe do you use?"},{"q":"How will you treat each grade, including this tooth?","keywords":["scaling|root planing|odontoplasty","regenerat|gtr|graft","tunnel","hemisection|root resection|amputation","implant|extraction"],"probe":"What is hemisection?"}]'::jsonb, 'A 48-year-old with periodontitis has 46 with a Nabers probe passing from buccal to lingual beneath the furcation, which is covered by gingiva.', array['periodontal therapy']::text[]),
(78, 5, 'periodontal-flap-surgery', 'Periodontal Flap Surgery', 'must_know', '10-mark essay', '{"definition":"A periodontal flap is a section of gingiva and/or mucosa surgically separated from the underlying tissues to give visibility and access to the bone and root surface.","classification":["By bone exposure: full-thickness (mucoperiosteal) vs partial (split) thickness","By placement after surgery: undisplaced vs displaced (apically, coronally, laterally positioned)","By papilla management: conventional vs papilla preservation flap","Named flaps: modified Widman flap (Ramfjord and Nissle), undisplaced flap, apically displaced flap, palatal flap, distal molar surgery (wedge)"],"clinical_features":["Indications: residual pockets ≥ 5 mm after initial therapy, access for root debridement, osseous defects needing resective or regenerative surgery, furcation treatment, crown lengthening","Contraindications: uncontrolled systemic disease, poor plaque control, smoking (relative)"],"management":["Incisions: internal bevel (inverse bevel, primary – removes the pocket lining), crevicular (secondary), interdental (tertiary); vertical releasing incisions when needed","Reflect, remove granulation tissue, debride roots; osseous recontouring or regeneration","Suture: interrupted, sling, continuous or mattress; periodontal dressing (e.g. Coe-Pak) if needed","Post-op: chlorhexidine, analgesics, review at 1 week; maintenance every 3 months"],"viva_pearls":["Modified Widman flap aims for maximum healing with minimal recession – it does not aim to eliminate pockets by apical displacement."]}'::jsonb, '[{"q":"Define a periodontal flap and give its indications.","keywords":["separated|section of gingiva","access|visibility","residual pocket|5 mm","osseous|bone defect","crown lengthening|furcation"],"probe":"When would you plan surgery?"},{"q":"Classify periodontal flaps.","keywords":["full thickness|mucoperiosteal","partial thickness|split","displaced|apically|coronally","undisplaced","papilla preservation"],"probe":"What is a split-thickness flap?"},{"q":"Describe the incisions used.","keywords":["internal bevel|inverse bevel","crevicular","interdental","vertical|releasing"],"probe":"What does the internal bevel incision remove?"},{"q":"What is the modified Widman flap?","keywords":["ramfjord","nissle","internal bevel|inverse bevel","minimal recession|healing","not displaced|close adaptation"],"probe":"Who described it?"}]'::jsonb, 'After scaling and root planing, a 45-year-old still has 7 mm pockets with bleeding around 16 and 17 and angular bone loss on the radiograph.', array['periodontal surgery']::text[]),
(79, 3, 'principles-of-exodontia', 'Principles of Exodontia', 'must_know', '10-mark essay', '{"definition":"Exodontia is the painless removal of a whole tooth or root with minimal trauma to the supporting tissues, so that the wound heals uneventfully and no prosthetic problem is created.","clinical_features":["Indications: non-restorable caries, pulpal or periapical disease not treatable by endodontics, advanced periodontal disease, orthodontic reasons, malposed or impacted teeth, supernumerary teeth, teeth in fracture lines, before radiotherapy, prosthetic reasons","Local contraindications: acute pericoronitis (relative), tooth in a tumour (vascular malformation or malignancy), previous radiotherapy (osteoradionecrosis risk), antiresorptive therapy (MRONJ risk)","Systemic contraindications (relative): uncontrolled diabetes, bleeding disorders, recent MI (within about 6 months), uncontrolled hypertension, pregnancy (first and third trimester for elective work), leukaemia"],"management":["Mechanical principles: expansion of the socket, lever (elevators), wedge (forceps beaks driven apically), wheel-and-axle","Forceps: apply beaks along the long axis on root surface, apical pressure first, then luxation – buccal/lingual, rotation for conical single roots (upper central incisor, lower premolars), traction last","Positioning: maxillary teeth – chair so the occlusal plane is about 60° to the floor and mouth at operator''s shoulder; mandibular – occlusal plane parallel to floor, mouth at elbow level","Post-extraction: compress the socket, check for root fragments, pressure pack, instructions (no rinsing for 24 hours, then warm saline)"],"viva_pearls":["Lower first molar forceps (cowhorn) beaks engage the furcation – use buccolingual luxation, not rotation."]}'::jsonb, '[{"q":"What are the indications for extraction?","keywords":["caries|non restorable","periodontal","orthodontic","impacted|supernumerary","radiotherapy|fracture line"],"probe":"Why extract teeth before radiotherapy?"},{"q":"What are the contraindications?","keywords":["radiotherapy|osteoradionecrosis","bisphosphonate|antiresorptive|mronj","bleeding","myocardial infarction|mi","diabet|hypertension|pregnan"],"probe":"What is the risk after radiotherapy?"},{"q":"Describe the mechanical principles.","keywords":["expansion","lever","wedge","wheel and axle|wheel","elevator"],"probe":"How does an elevator act?"},{"q":"How will you extract 46 with forceps?","keywords":["cowhorn|forceps","apical pressure","buccal|lingual|luxat","traction","positioning|elbow"],"probe":"Why not rotate a lower molar?"}]'::jsonb, 'A 35-year-old needs extraction of a grossly carious 46. Write about the indications, contraindications and the principles of a forceps extraction.', array['extraction']::text[]),
(80, 6, 'articulators', 'Articulators & Face-bow', 'must_know', '10-mark essay', '{"definition":"An articulator is a mechanical device that represents the temporomandibular joints and jaws, to which casts are attached to simulate some or all mandibular movements. A face-bow records the spatial relationship of the maxillary arch to the TMJs (or another reference) and transfers it to the articulator.","classification":["Boucher / GPT: Class I – simple holding instruments, one static relation (hinge, slab); Class II – horizontal but not vertical movements, not oriented to the TMJ (Mean value, e.g. Gysi simplex); Class III – simulate condylar pathways using averages or mechanical equivalents, accept face-bow (semi-adjustable: Hanau H2, Whip-Mix); Class IV – accept three-dimensional dynamic records (fully adjustable: Stuart, Denar D5A)","Arcon (condylar elements on the lower member, as in the body – e.g. Whip-Mix) vs non-arcon (on the upper member – e.g. Hanau H2)","Face-bows: arbitrary (ear-piece) and kinematic (locates the true hinge axis)"],"clinical_features":["Settings on a semi-adjustable articulator: horizontal condylar guidance (from protrusive record), lateral condylar guidance (Hanau formula L = H/8 + 12), incisal guidance","Third point of reference for face-bow: orbitale, nasion relator, or a point 43 mm above the incisal edge"],"management":["Mount the maxillary cast with the face-bow, the mandibular cast with the centric relation record, then set condylar guidance with protrusive and lateral records"],"viva_pearls":["Hanau''s formula: L = H/8 + 12 (L – lateral condylar guidance, H – horizontal condylar guidance)."]}'::jsonb, '[{"q":"What are an articulator and a face-bow?","keywords":["mechanical device|instrument","tmj|temporomandibular","mandibular movement","face bow|face-bow|facebow","maxilla|transfer"],"probe":"What does a face-bow transfer?"},{"q":"Classify articulators.","keywords":["class i|class 1|hinge","mean value|class ii","semi adjustable|semi-adjustable|class iii","fully adjustable|class iv","arcon"],"probe":"Give an example of a semi-adjustable articulator."},{"q":"What is the difference between arcon and non-arcon?","keywords":["arcon","condylar element|condyle","lower member|mandibular member","upper member|non arcon|non-arcon","whip mix|hanau"],"probe":"Which design is more anatomical?"},{"q":"How do you program a semi-adjustable articulator?","keywords":["protrusive record","horizontal condylar","lateral condylar|bennett","hanau formula|h/8","incisal guid"],"probe":"State Hanau''s formula."}]'::jsonb, 'You are mounting casts for a patient''s complete dentures and need to decide whether a simple hinge articulator is enough or a semi-adjustable articulator with a face-bow transfer is needed.', array['occlusion','lab']::text[]),
(81, 6, 'denture-complaints', 'Post-insertion Complaints in Complete Dentures', 'must_know', '10-mark essay', '{"definition":"Post-insertion complaints are problems patients report after denture delivery; most can be traced to errors in extension, occlusion, vertical dimension or tooth position, or to patient adaptation.","clinical_features":["Pain or ulcers: overextended flanges, pressure spots, rough or sharp areas, occlusal errors (deflective contacts); locate with pressure-indicating paste or disclosing wax","Looseness at rest: underextension, poor peripheral seal, posterior palatal seal deficient","Lifting on opening or speaking: overextended flanges or interference with frenum/muscle attachments; teeth set too far buccally or lingually","Cheek biting: insufficient horizontal overlap of posterior teeth (buccal overjet) or teeth set edge-to-edge","Clicking teeth: increased vertical dimension of occlusion (insufficient freeway space)","Tired jaw muscles, sore ridges all over: excess vertical dimension","Angular cheilitis, collapsed face, poor chewing: reduced vertical dimension","Speech: \"s\" sounds (sibilants) affected by palatal contour and incisor position; \"f\" and \"v\" by upper incisor length to the lower lip; \"th\" (linguodental) by incisor labiolingual position","Gagging: overextended or thick posterior border, poor retention, psychological"],"management":["Relieve and adjust using pressure-indicating paste; selective grinding after clinical remount (remount procedure) to perfect occlusion","Reset teeth or remake for vertical dimension errors","Reline/rebase for loss of fit; post-dam correction","Instructions: soft diet first, remove at night, cleaning, review at 24 hours and 1 week"],"viva_pearls":["Normal freeway space (interocclusal rest space) is about 2–4 mm."]}'::jsonb, '[{"q":"Why might a lower denture lift on opening?","keywords":["overextend","frenum|muscle","buccinator|mylohyoid|lingual","teeth position|set|neutral zone"],"probe":"Which muscles could be involved?"},{"q":"What causes cheek biting and clicking of teeth?","keywords":["horizontal overlap|overjet|buccal","edge to edge|edge-to-edge","vertical dimension","freeway space|interocclusal"],"probe":"What happens if the vertical dimension is too high?"},{"q":"How do errors of vertical dimension present?","keywords":["increased|excess","clicking|sore|tired","reduced|decreased","angular cheilitis|collapsed","2|4 mm|freeway"],"probe":"What is the normal freeway space?"},{"q":"How will you manage these complaints?","keywords":["pressure indicating|disclosing","relieve|adjust","remount|selective grinding","reline|rebase|reset","review|instruction"],"probe":"What is a clinical remount?"}]'::jsonb, 'A week after receiving new complete dentures, a 70-year-old complains that the lower denture lifts when he opens wide, his cheeks get bitten, and he clicks his teeth when talking.', array['complete denture','troubleshooting']::text[]),
(82, 6, 'fpd-abutments', 'FPD: Abutment Evaluation & Tooth Preparation', 'must_know', '10-mark essay', '{"definition":"An abutment is a tooth that supports and retains a fixed partial denture. Abutment evaluation and correct preparation determine the longevity of the bridge.","clinical_features":["Crown–root ratio: ideally 2:3, minimum 1:1","Root configuration: wide, divergent, irregular roots are better than conical fused roots","Ante''s law: the combined root surface area of the abutments should be equal to or greater than that of the teeth being replaced","Periodontal health, mobility, pulp vitality, caries, alignment and tilt","Span length: deflection increases with the cube of the length (L³) and decreases with the cube of the pontic height"],"management":["Principles of tooth preparation (Shillingburg): preservation of tooth structure, retention and resistance form, structural durability, marginal integrity, preservation of the periodontium","Taper (total occlusal convergence) of about 6° (2–5° per wall ideally; up to 10–20° accepted clinically)","Occlusal reduction: about 1.5 mm on functional cusps and 1 mm on non-functional cusps (more for ceramics), with a functional cusp bevel","Finish lines: chamfer for metal, heavy chamfer or shoulder for metal-ceramic and all-ceramic, knife edge for tilted teeth","Common path of insertion between abutments; tilted molars – uprighting orthodontically, proximal half crown, telescopic crown or non-rigid connector"],"viva_pearls":["Doubling span length increases deflection eight times."]}'::jsonb, '[{"q":"How will you evaluate an abutment?","keywords":["crown root ratio|crown-root","root configuration|root shape","periodont","ante","vital|mobility"],"probe":"What is the ideal crown–root ratio?"},{"q":"State Ante''s law and the effect of span length.","keywords":["ante","root surface area","equal or greater|greater","cube|l3|eight times","deflection|flex"],"probe":"What happens if the span doubles?"},{"q":"What are the principles of tooth preparation?","keywords":["preservation of tooth structure","retention|resistance","structural durability","marginal integrity","periodontium"],"probe":"What gives resistance form?"},{"q":"How will you handle the tilted 37?","keywords":["path of insertion","upright|orthodontic","proximal half crown","telescop","non rigid|non-rigid connector"],"probe":"What is a proximal half crown?"}]'::jsonb, 'A 40-year-old has lost 36 and wants a fixed bridge from 35 to 37. The 37 is mesially tilted and both abutments have healthy periodontium.', array['fixed prosthodontics']::text[]),
(83, 6, 'overdentures', 'Overdentures & Immediate Dentures', 'desirable', '5-mark short note', '{"definition":"An overdenture is a removable denture that covers and rests on one or more retained natural teeth, roots or implants. An immediate denture is made before extraction and inserted immediately after the teeth are removed.","classification":["Overdenture abutments: non-coping (rounded, unprotected), coping (cast metal coping – short or long), attachments (studs, bars, magnets)","Tooth-supported vs implant-supported overdentures","Immediate dentures: conventional (later replaced) and interim (transitional)"],"clinical_features":["Overdenture advantages: preserves alveolar bone, proprioception (periodontal ligament receptors), better retention and stability, psychological benefit, easier transition to complete dentures","Disadvantages: caries and periodontal disease of abutments, bulk at the abutment, cost; canines and premolars are preferred abutments","Abutments usually need endodontics and are reduced to 2–3 mm above the gingiva with a dome shape","Immediate denture advantages: no edentulous period, aesthetics, maintains vertical dimension and tongue size, acts as a splint/bandage; disadvantages: cannot try in anterior teeth, needs relines as ridges resorb"],"management":["Overdenture: endodontics, reduce and dome abutments, fluoride gel in the denture fitting surface, strict hygiene","Immediate denture: cast surgery on the working cast, surgical template, insert at extraction and review at 24 hours; reline after about 3–6 months"],"viva_pearls":["The mandibular two-implant overdenture is the minimum standard of care for edentulous mandibles (McGill consensus, 2002)."]}'::jsonb, '[{"q":"What is an overdenture, and what are its advantages?","keywords":["retained|roots|teeth","bone|ridge preservation","proprioception","retention|stability","psycholog"],"probe":"Why does it preserve bone?"},{"q":"How do you prepare an overdenture abutment?","keywords":["endodontic|root canal","2|3 mm","dome","coping","attachment|magnet|stud|bar"],"probe":"Which teeth make the best abutments?"},{"q":"What are the problems with overdentures?","keywords":["caries","periodont","fluoride","hygiene","bulk|cost"],"probe":"How do you prevent caries on the abutments?"},{"q":"What is an immediate denture, and what are its pros and cons?","keywords":["before extraction|immediately","aesthetic|no edentulous","try in|try-in","reline|resorption","splint|bandage"],"probe":"When will you reline it?"}]'::jsonb, 'A 62-year-old has only both lower canines left, with good bone support, and is anxious about losing all his teeth. He also wants teeth on the day of extraction for the upper arch.', array['complete denture']::text[]),
(84, 6, 'gingival-retraction', 'Gingival Retraction', 'desirable', '5-mark short note', '{"definition":"Gingival retraction (tissue management) is the temporary displacement of the free gingiva away from the finish line, with control of fluid and bleeding, so that an impression records the margin and some tooth beyond it.","classification":["Mechanical: plain retraction cord, copper bands, rubber dam, compression caps","Chemico-mechanical (most common): cord impregnated with astringent or haemostatic – aluminium chloride, ferric sulphate (stains tissue), aluminium potassium sulphate (alum), racemic epinephrine 8% (avoid in cardiac patients, hyperthyroidism, on MAO inhibitors)","Cordless/paste: aluminium chloride–kaolin paste (e.g. Expasyl), expanding polyvinyl siloxane","Surgical: rotary gingival curettage (gingittage), electrosurgery, lasers"],"clinical_features":["Aims: lateral displacement of about 0.2 mm (enough width of impression material to resist tearing) and vertical access beyond the margin","Healthy gingiva is a prerequisite; inflamed tissue bleeds and recedes"],"management":["Double-cord technique: thin cord left in the sulcus, thicker upper cord removed just before the impression","Leave cord about 4–10 minutes; moisten before removal to avoid tearing the epithelial attachment","Avoid electrosurgery near metal restorations or in thin gingiva"],"viva_pearls":["Ferric sulphate is a good haemostat but stains tissue and can inhibit polyether/PVS set if not rinsed."]}'::jsonb, '[{"q":"What is gingival retraction and why is it needed?","keywords":["displace|retract","finish line|margin","bleeding|fluid","impression"],"probe":"How far should the gingiva be displaced?"},{"q":"Classify retraction methods.","keywords":["mechanical","chemico mechanical|chemico-mechanical|chemical","surgical","electrosurgery|laser|curettage","cordless|paste"],"probe":"Give two surgical methods."},{"q":"Name the chemicals used in retraction cords.","keywords":["aluminium chloride|aluminum chloride","ferric sulphate|ferric sulfate","epinephrine|adrenaline","alum|potassium sulphate"],"probe":"When must you avoid epinephrine cords?"},{"q":"Describe the double-cord technique.","keywords":["double cord|two cords","thin|first cord","remove|second","moisten|wet","minutes"],"probe":"Why leave the first cord in place?"}]'::jsonb, 'You are taking an elastomeric impression for a metal-ceramic crown on 11 with a subgingival finish line and slight bleeding from the gingival sulcus.', array['fixed prosthodontics','impressions']::text[]),
(85, 13, 'neck-dissection', 'Oral Cancer: Lymph Nodes & Neck Dissection', 'must_know', '10-mark essay', '{"definition":"Neck dissection is the surgical removal of cervical lymph nodes and surrounding tissues to treat or stage metastatic disease from head and neck cancer.","classification":["Lymph node levels: I (IA submental, IB submandibular), II (upper jugular, IIA/IIB by the spinal accessory nerve), III (middle jugular), IV (lower jugular), V (posterior triangle), VI (central compartment), VII (superior mediastinal)","Radical neck dissection (Crile, 1906): levels I–V with the spinal accessory nerve, internal jugular vein and sternocleidomastoid","Modified radical: levels I–V preserving one or more of these (type I – accessory nerve; II – plus IJV; III – all three, functional)","Selective: removes only the levels at risk – supraomohyoid (I–III) for oral cancer; lateral (II–IV) for larynx","Extended radical: adds other structures or node groups"],"clinical_features":["Tongue cancer drains to levels I–III (and IV); skip metastasis to level III–IV can occur; tip of tongue to submental nodes; bilateral spread from midline lesions","Hard, fixed or matted nodes suggest metastasis"],"investigations":["FNAC of the node, CT/MRI, PET-CT for distant disease; TNM staging (AJCC 8th edition includes depth of invasion and extranodal extension)"],"management":["Elective (prophylactic) selective neck dissection for N0 neck when depth of invasion is > 3–4 mm","Therapeutic neck dissection for N+ neck","Complications: shoulder dysfunction (accessory nerve), chylous fistula (left side – thoracic duct), carotid blowout, haematoma, marginal mandibular nerve palsy"],"viva_pearls":["Supraomohyoid neck dissection = levels I, II and III."]}'::jsonb, '[{"q":"Describe the lymph node levels of the neck.","keywords":["level i|submental|submandibular","level ii|upper jugular","level iii|middle jugular","level iv|lower jugular","level v|posterior triangle"],"probe":"Which level contains the submandibular nodes?"},{"q":"Classify neck dissections.","keywords":["radical|crile","modified radical","selective","supraomohyoid","extended"],"probe":"What is preserved in a modified radical neck dissection?"},{"q":"What structures are removed in a radical neck dissection?","keywords":["spinal accessory","internal jugular","sternocleidomastoid","levels i v|i–v|i to v"],"probe":"What problem follows removing the accessory nerve?"},{"q":"How will you manage this patient''s neck, and what are the complications?","keywords":["fnac|biopsy","ct|mri|staging","neck dissection","shoulder|accessory","chyle|chylous|thoracic duct"],"probe":"Why is chyle leak more common on the left?"}]'::jsonb, 'A 58-year-old with squamous cell carcinoma of the left lateral tongue has a hard, mobile 2.5 cm node in the left submandibular region.', array['oncology','neck']::text[]),
(86, 13, 'burns', 'Burns', 'must_know', '10-mark essay', '{"definition":"A burn is coagulative destruction of skin and deeper tissues by heat, chemicals, electricity or radiation.","classification":["Depth: superficial (epidermal – red, painful, no blisters), superficial partial thickness (blisters, painful, blanches), deep partial thickness (blotchy, less painful), full thickness (white/charred, leathery, painless – needs grafting); fourth degree into muscle and bone","Extent – Wallace''s rule of nines (adults): head and neck 9%, each upper limb 9%, front of trunk 18%, back 18%, each lower limb 18%, perineum 1%; Lund and Browder chart for children; patient''s palm ≈ 1% TBSA"],"clinical_features":["Inhalational injury: facial burns, singed nasal hairs, hoarseness, stridor, carbonaceous sputum – early intubation","Burn shock from capillary leak; hypothermia; infection (Pseudomonas, Staphylococcus); Curling''s ulcer; contractures; hypertrophic scars"],"management":["First aid: stop the burning, cool with running water for 20 minutes, cover with cling film","ABCDE; secure the airway early in inhalational injury","Fluids for > 15% TBSA in adults (> 10% in children): Parkland formula 4 mL × kg × %TBSA of Ringer''s lactate in the first 24 hours – half in the first 8 hours from the time of the burn, half in the next 16 hours; titrate to urine output 0.5 mL/kg/h (1 mL/kg/h in children)","Escharotomy for circumferential full-thickness burns; tetanus prophylaxis, analgesia, nutrition","Wound care: silver sulfadiazine, early excision and skin grafting; physiotherapy and splinting"],"viva_pearls":["Here TBSA ≈ 9 (face/head) partly + 18 (both arms) + 18 (front trunk) ≈ 40%: Parkland ≈ 4 × 60 × 40 = 9.6 L in 24 hours."]}'::jsonb, '[{"q":"Classify burns by depth.","keywords":["superficial","partial thickness","full thickness","blister","painless|charred|leathery"],"probe":"Which burns are painless and why?"},{"q":"How do you estimate the burnt area?","keywords":["rule of nines|wallace","lund|browder","palm|1%","9|18"],"probe":"Which chart is used for children?"},{"q":"What are the signs of inhalational injury, and what will you do?","keywords":["singed|nasal hair","hoarse|stridor","carbon|soot|sputum","facial burn","intubat|airway"],"probe":"Why intubate early?"},{"q":"Calculate this patient''s fluid requirement.","keywords":["parkland","4 ml|4 x|4 ×","ringer|lactate|crystalloid","half in first 8|8 hours","urine output|0.5"],"probe":"How will you monitor resuscitation?"}]'::jsonb, 'A 60 kg man has blistered and charred burns of the face, both upper limbs and the front of his chest after a gas cylinder explosion. His voice is hoarse and his nostril hairs are singed.', array['emergency','trauma']::text[]),
(87, 13, 'tracheostomy', 'Tracheostomy', 'desirable', '5-mark short note', '{"definition":"Tracheostomy is the surgical creation of an opening in the anterior wall of the trachea, usually through the 2nd–4th tracheal rings, with insertion of a tube to maintain the airway. (Cricothyroidotomy is the emergency surgical airway through the cricothyroid membrane.)","classification":["Emergency vs elective; temporary vs permanent","By level: high (above the isthmus – risk of subglottic stenosis), mid (through the isthmus, 2nd–3rd rings – usual), low (below the isthmus)","Surgical (open) vs percutaneous dilatational"],"clinical_features":["Indications: upper airway obstruction (trauma, infection, tumour, oedema), prolonged ventilation, protecting against aspiration, major head and neck surgery (panfacial fractures, free flaps), bronchial toilet","Advantages over long-term intubation: less dead space (about 50% reduction), easier suction, comfort, less laryngeal damage"],"management":["Steps: neck extended, horizontal incision about 2 cm above the suprasternal notch, retract strap muscles, divide or retract the thyroid isthmus, open trachea (window or Bjork flap) at rings 2–4, insert cuffed tube, secure","Never cut the first ring (subglottic stenosis)","Complications: immediate – haemorrhage, pneumothorax, damage to recurrent laryngeal nerve or oesophagus; early – tube blockage or displacement, surgical emphysema, infection; late – tracheal stenosis, tracheo-oesophageal fistula, tracheo-innominate artery fistula, difficult decannulation","Care: humidification, suction, inner tube cleaning, cuff pressure checks, spare tube and dilator at the bedside"],"viva_pearls":["In a \"can''t intubate, can''t oxygenate\" emergency, cricothyroidotomy is faster and safer than an emergency tracheostomy."]}'::jsonb, '[{"q":"What is a tracheostomy, and where is it done?","keywords":["opening|stoma","trachea","2nd|second|2 4|2-4|rings","isthmus","tube"],"probe":"Why avoid the first ring?"},{"q":"What are the indications?","keywords":["obstruction","prolonged ventilation","aspiration","head and neck surgery|panfacial|maxillofacial","bronchial toilet|secretion"],"probe":"Why is it useful in panfacial fractures?"},{"q":"What are the complications?","keywords":["haemorrhage|hemorrhage|bleeding","pneumothorax","emphysema","stenosis","fistula|blockage|displace"],"probe":"What late complication involves a major artery?"},{"q":"How does it compare with cricothyroidotomy?","keywords":["cricothyroid","emergency","faster|quick","membrane","convert|temporary"],"probe":"Which is preferred in a can''t-intubate emergency?"}]'::jsonb, 'A patient with panfacial fractures and Ludwig''s angina–like swelling of the floor of mouth cannot be intubated orally or nasally and needs a secure airway for surgery.', array['airway','maxillofacial']::text[]),
(88, 7, 'early-childhood-caries', 'Early Childhood Caries', 'must_know', '10-mark essay', '{"definition":"Early childhood caries (ECC, AAPD) is the presence of one or more decayed (cavitated or non-cavitated), missing (due to caries) or filled tooth surfaces in any primary tooth in a child under 6 years. Severe ECC (S-ECC): any smooth-surface caries under 3 years, or dmfs above age-specific thresholds (e.g. ≥ 4 at age 3, ≥ 5 at 4, ≥ 6 at 5).","classification":["Wyne: type I (mild – isolated molars/incisors), type II (moderate – labiolingual maxillary incisors ± molars, lower incisors spared; feeding pattern), type III (severe – including lower incisors)","Older terms: nursing bottle caries, baby bottle tooth decay, rampant caries"],"etiology":["Frequent or prolonged exposure to sugars (night-time bottle or on-demand breastfeeding with sweetened liquids)","Early colonisation by mutans streptococci, often from the mother (vertical transmission)","Reduced salivary flow at night, enamel hypoplasia, low fluoride, low socioeconomic status"],"clinical_features":["Pattern: maxillary incisors first (labial surfaces near the gingiva), then first molars, canines, second molars; mandibular incisors spared – protected by the tongue and sublingual saliva"],"management":["Counselling: stop the night-time bottle, wean by 12–18 months, water only at night, limit sugar frequency, brush twice daily with fluoridated toothpaste (smear under 3 years, pea-size 3–6 years), first dental visit by age 1","Professional: fluoride varnish every 3–6 months, silver diamine fluoride to arrest lesions, sealants","Restorative: GIC, composite strip crowns or zirconia crowns for incisors, stainless steel crowns or Hall technique for molars, pulp therapy or extraction, under GA if needed"],"viva_pearls":["Lower incisors are spared because of the tongue position during sucking and the nearby submandibular/sublingual ducts."]}'::jsonb, '[{"q":"Define ECC and severe ECC.","keywords":["under 6|below 6|six years","decayed|dmf","primary","severe|s ecc|s-ecc","smooth surface|under 3"],"probe":"What makes it \"severe\"?"},{"q":"What causes ECC?","keywords":["bottle|night","sugar|sweet","mutans|streptococcus","mother|vertical transmission","saliva"],"probe":"How do bacteria pass to the child?"},{"q":"Describe the pattern of caries in this child.","keywords":["maxillary incisor|upper incisor","first molar","lower incisor|mandibular incisor","spared","tongue"],"probe":"Why are the lower incisors spared?"},{"q":"How will you manage this child?","keywords":["counsel|diet","fluoride varnish|fluoride","silver diamine|sdf","strip crown|stainless steel crown|ssc","general anaesthesia|ga|pulp"],"probe":"What toothpaste advice will you give?"}]'::jsonb, 'A 3-year-old who falls asleep with a bottle of milk has brown cavities on the upper incisors and first molars; the lower incisors are untouched.', array['caries','prevention']::text[]),
(89, 7, 'stainless-steel-crowns', 'Stainless Steel Crowns', 'must_know', '5-mark short note', '{"definition":"Preformed stainless steel crowns (Humphrey, 1950) are prefabricated metal crowns adapted to primary and young permanent molars – the most durable restoration for extensively decayed primary molars.","classification":["Untrimmed, pretrimmed, precontoured (e.g. 3M ESPE) crowns","Nickel-chromium crowns"],"clinical_features":["Indications: multisurface caries in primary molars, after pulpotomy or pulpectomy, high caries risk, developmental defects (hypoplasia, amelogenesis imperfecta, MIH), fractured teeth, abutment for space maintainers, children needing GA","Contraindications: nickel allergy, tooth near exfoliation, poor cooperation for the conventional technique (consider Hall technique)"],"management":["Conventional preparation: occlusal reduction about 1–1.5 mm, proximal slices to break contacts with a feather-edge finish below the contact, no buccal or lingual reduction except the mesiobuccal bulge of the first molar, round line angles","Select crown by mesiodistal width; trim to about 1 mm below the gingival margin, crimp and contour, check occlusion, cement with GIC","Hall technique: no caries removal or preparation; crown cemented over the tooth with GIC, sealing caries in; orthodontic separators may be needed"],"viva_pearls":["A blanching of the gingiva on seating shows the crown is too long – trim it."]}'::jsonb, '[{"q":"What are stainless steel crowns, and when are they indicated?","keywords":["preformed|prefabricated","multisurface|extensive caries","pulpotomy|pulp therapy","hypoplasia|defect","high caries risk|space maintainer"],"probe":"Who introduced them?"},{"q":"Describe the tooth preparation.","keywords":["occlusal reduction|1 mm|1.5","proximal slice","feather edge|feather-edge","no buccal|buccal","line angle|round"],"probe":"How much occlusal reduction?"},{"q":"How do you adapt and cement the crown?","keywords":["select|size|mesiodistal","trim","crimp|contour","gic|glass ionomer","blanch|occlusion"],"probe":"Which cement do you use?"},{"q":"What is the Hall technique?","keywords":["hall","no preparation|no caries removal","seal|sealed","separator","gic|glass ionomer"],"probe":"How does it stop caries without removing it?"}]'::jsonb, 'A 6-year-old has had a pulpotomy on 84 (lower right first primary molar), which has caries on three surfaces.', array['restorative','primary molars']::text[]),
(90, 4, 'pulp-periapical-diseases', 'Pulp & Periapical Diseases: Classification', 'must_know', '10-mark essay', '{"definition":"Pulp and periapical diseases are inflammatory responses of the pulp and periradicular tissues, mostly to bacterial invasion from caries, trauma or restorative procedures.","classification":["AAE (2009) pulpal: normal pulp, reversible pulpitis, symptomatic irreversible pulpitis, asymptomatic irreversible pulpitis, pulp necrosis, previously treated, previously initiated therapy","AAE periapical: normal apical tissues, symptomatic apical periodontitis, asymptomatic apical periodontitis, chronic apical abscess (with sinus tract), acute apical abscess, condensing osteitis","Grossman (older): pulpitis (reversible/irreversible), pulp degeneration (calcific, internal resorption), necrosis; chronic hyperplastic pulpitis (pulp polyp in young open carious teeth)"],"clinical_features":["Reversible pulpitis: sharp pain to cold that stops within seconds of removing the stimulus","Symptomatic irreversible pulpitis: lingering pain (> 30 s), spontaneous, night pain, referred; heat may worsen, cold may relieve in late stages","Necrosis: no response to vitality tests; may be asymptomatic","Symptomatic apical periodontitis: tender to biting and percussion","Asymptomatic apical periodontitis: periapical radiolucency (granuloma or cyst), no symptoms","Condensing osteitis: diffuse radiopacity around the apex of a tooth with chronic low-grade pulp inflammation"],"investigations":["Thermal (cold – most reliable), electric pulp test, percussion, palpation, mobility, radiographs, test cavity as last resort"],"management":["Reversible: remove cause, restore/protect pulp","Irreversible: pulpectomy and root canal treatment (vital pulp therapy/pulpotomy increasingly used in selected cases)","Necrosis with apical periodontitis: root canal treatment; abscess – drainage"],"viva_pearls":["26 here = symptomatic irreversible pulpitis; 46 = pulp necrosis with symptomatic apical periodontitis."]}'::jsonb, '[{"q":"Give the AAE classification of pulpal diagnoses.","keywords":["normal pulp","reversible","symptomatic irreversible","asymptomatic irreversible","necrosis"],"probe":"What does \"previously initiated therapy\" mean?"},{"q":"How do reversible and irreversible pulpitis differ?","keywords":["seconds|subsides|stops","linger","spontaneous","night","referred"],"probe":"How long does the pain linger in irreversible pulpitis?"},{"q":"Give the periapical classification.","keywords":["symptomatic apical periodontitis","asymptomatic apical periodontitis","chronic apical abscess|sinus","acute apical abscess","condensing osteitis"],"probe":"What is condensing osteitis?"},{"q":"What are your diagnoses for 26 and 46, and the treatment?","keywords":["irreversible","necrosis|non vital|non-vital","apical periodontitis","root canal|pulpectomy","cold test|vitality"],"probe":"Which vitality test is most reliable?"}]'::jsonb, 'A patient has lingering pain to cold for over a minute on 26, keeping him awake at night. Another tooth, 46, is non-vital, tender to percussion and shows a periapical radiolucency.', array['endodontic diagnosis']::text[]),
(91, 1, 'tooth-wear', 'Tooth Wear: Attrition, Abrasion, Erosion, Abfraction', 'must_know', '5-mark short note', '{"definition":"Tooth wear (tooth surface loss) is the non-carious loss of dental hard tissue from mechanical or chemical causes, often several acting together.","classification":["Attrition: tooth-to-tooth contact – flat, shiny facets on occlusal and incisal surfaces, matching wear on opposing teeth (bruxism)","Abrasion: friction from external objects – horizontal brushing, hard brushes and abrasive pastes (V- or wedge-shaped cervical notches), pipe smoking, hair pins, tooth picks","Erosion: chemical dissolution by acids not from bacteria – extrinsic (soft drinks, citrus, wine, swimming pool water) or intrinsic (GERD, bulimia, vomiting in pregnancy) – smooth, glazed, cupped lesions; restorations stand proud; palatal surfaces of upper anteriors in intrinsic erosion (\"perimylolysis\")","Abfraction: cervical wedge-shaped lesions from flexural stress of occlusal loading (Grippo) – sharp, deep, may be subgingival","Resorption: internal (pink spot) or external"],"investigations":["Basic Erosive Wear Examination (BEWE) score 0–3 per sextant; study models and photos to monitor","Diet diary, medical history (reflux, eating disorders), salivary tests"],"management":["Identify and remove the cause: dietary advice (limit acid frequency, use a straw, do not brush within 1 hour of acid), treat reflux (refer), soft brush and correct technique, night guard for bruxism","Fluoride (high-fluoride toothpaste, varnish), desensitising agents","Restore when needed: GIC or composite for cervical lesions, Dahl concept (localised anterior wear), crowns for advanced wear"],"viva_pearls":["In erosion, amalgam restorations stand above the surrounding eroded tooth surface (\"islands\")."]}'::jsonb, '[{"q":"Classify tooth wear.","keywords":["attrition","abrasion","erosion","abfraction","resorption"],"probe":"Which one is chemical?"},{"q":"How does each type look clinically?","keywords":["facet|flat|shiny","wedge|v shaped|v-shaped|notch","cupped|smooth|glazed","restoration|proud","cervical"],"probe":"How would you recognise erosion?"},{"q":"What causes erosion?","keywords":["extrinsic|soft drink|citrus|diet","intrinsic","reflux|gerd|gastro","bulimia|vomit","palatal"],"probe":"Which surfaces does intrinsic acid affect?"},{"q":"How will you manage this patient?","keywords":["cause|diet","refer|reflux|physician","soft brush|technique","fluoride|desensitis","gic|composite|dahl|restore"],"probe":"When should he brush after an acid exposure?"}]'::jsonb, 'A 35-year-old with acid reflux has smooth, cupped lesions on the palatal surfaces of upper incisors, and notched wedge-shaped cervical lesions on premolars where he brushes hard.', array['regressive changes']::text[])
insert into public.flashcards (id, topic_id, front, back) overriding system value values
(1, 1, 'What are the Vickers–Gorlin criteria?', 'Early histological features of ameloblastoma: hyperchromatic basal-cell nuclei, palisading with reverse polarity, and subnuclear cytoplasmic vacuolation.'),
(2, 1, 'Most common histological pattern of ameloblastoma?', 'Follicular.'),
(3, 1, 'Which ameloblastoma mimics a fibro-osseous lesion on radiographs?', 'Desmoplastic ameloblastoma – mixed radiolucent–radiopaque, often in the anterior maxilla.'),
(4, 1, 'Treatment of mural unicystic ameloblastoma?', 'Treat like the conventional tumour – resection with safe bony margins.'),
(5, 2, 'Typical aspirate of an OKC?', 'Thick, cheesy, creamy fluid with keratin squames; soluble protein < 4 g/dL.'),
(6, 2, 'Histology hallmark of OKC?', 'Uniform 6–8 layer parakeratinised epithelium with a corrugated surface and palisaded "tombstone" basal cells.'),
(7, 2, 'Gene mutated in Gorlin–Goltz syndrome?', 'PTCH1 (patched) – a tumour suppressor in the Hedgehog pathway.'),
(8, 3, 'Most common odontogenic cyst?', 'Radicular (periapical) cyst.'),
(9, 3, 'Rushton bodies are seen in?', 'Radicular and dentigerous cysts – hyaline, curved, eosinophilic bodies in the epithelial lining.'),
(10, 4, 'Earliest symptom of OSMF?', 'Burning sensation on eating spicy food (often with vesicles).'),
(11, 4, 'Role of copper in OSMF?', 'Areca nut is rich in copper, which up-regulates lysyl oxidase → increased collagen cross-linking.'),
(12, 4, 'Khanna & Andrade group III mouth opening?', '15–26 mm (moderately advanced).'),
(13, 5, 'Is leukoplakia a clinical or histological term?', 'Clinical – the diagnosis is made by excluding other white lesions.'),
(14, 5, 'Highest-risk type of leukoplakia?', 'Proliferative verrucous leukoplakia (and non-homogeneous / speckled forms).'),
(15, 6, 'Civatte bodies are?', 'Apoptotic (degenerated) basal keratinocytes seen in lichen planus.'),
(16, 6, '6 Ps of cutaneous lichen planus?', 'Pruritic, purple, polygonal, planar papules and plaques.'),
(17, 7, 'Most difficult angulation of mandibular third molar to remove?', 'Distoangular.'),
(18, 7, 'Pell & Gregory Class III?', 'All or most of the third molar lies within the ramus.'),
(19, 7, 'WAR line "Red" indicates?', 'Depth of the tooth / amount of bone to remove – each mm of red line ≈ greater difficulty.'),
(20, 8, 'Structure involved in all Le Fort fractures?', 'Pterygoid plates.'),
(21, 8, 'Guérin''s sign?', 'Ecchymosis in the region of the greater palatine vessels – seen in Le Fort I fracture.'),
(22, 9, 'Radiopacifier in MTA?', 'Bismuth oxide (also a cause of discolouration).'),
(23, 9, 'Setting time of MTA vs Biodentine?', 'MTA ≈ 165 minutes; Biodentine ≈ 12 minutes.'),
(24, 10, 'Antibiotic that may reduce cyclosporine-induced gingival enlargement?', 'Azithromycin.'),
(25, 11, 'Kennedy class with no modification spaces?', 'Class IV.'),
(26, 11, 'Who gave rules for applying Kennedy''s classification?', 'O. C. Applegate – 8 rules.'),
(27, 12, 'Final restoration after pulpotomy in a primary molar?', 'Stainless steel crown.'),
(28, 12, 'Ferric sulphate concentration and time in pulpotomy?', '15.5% for about 15 seconds.'),
(29, 13, 'Phase eliminated in high-copper amalgam?', 'γ₂ (Sn₇₋₈Hg).'),
(30, 13, 'Cause of delayed expansion of amalgam?', 'Zinc-containing alloy contaminated by moisture → hydrogen gas.'),
(31, 14, 'Max dose of lignocaine with adrenaline?', '7 mg/kg (max 500 mg). Without adrenaline: 4.4 mg/kg (max 300 mg).'),
(32, 14, 'LA causing methaemoglobinaemia?', 'Prilocaine (metabolite o-toluidine). Also benzocaine.'),
(33, 14, 'Most cardiotoxic LA?', 'Bupivacaine.'),
(34, 15, 'Adult adrenaline dose for anaphylaxis?', '0.01 mg/kg IM, maximum 0.5 mg (0.5 mL of 1:1000), anterolateral thigh; repeat every 5 minutes if needed.'),
(35, 15, 'Why should a patient in anaphylaxis not stand up?', 'Standing can cause sudden cardiovascular collapse; keep them lying flat (or sitting if breathing is difficult).'),
(36, 16, 'Australian case defining material risk?', 'Rogers v Whitaker (1992), High Court of Australia.'),
(37, 16, 'Four types of notifiable conduct (National Law)?', 'Practising while intoxicated; sexual misconduct in practice; impairment placing the public at substantial risk; significant departure from accepted professional standards.'),
(38, 17, 'Splint for a replanted avulsed permanent tooth?', 'Flexible splint for about 2 weeks.'),
(39, 17, 'Best widely available storage medium for an avulsed tooth?', 'Milk (Hank''s balanced salt solution if available).'),
(40, 18, 'Most common site of oral cancer in India?', 'Gingivobuccal sulcus / buccal mucosa (linked to the tobacco-quid habit).'),
(41, 18, 'Which TNM edition added depth of invasion to oral cancer T staging?', 'AJCC 8th edition (also added extranodal extension to N).'),
(42, 19, 'Most common salivary gland tumour?', 'Pleomorphic adenoma (parotid, superficial lobe).'),
(43, 19, 'Why is enucleation of pleomorphic adenoma avoided?', 'Incomplete capsule with pseudopods – enucleation leaves tumour behind and causes recurrence.'),
(44, 20, 'Target antigen in pemphigus vulgaris?', 'Desmoglein 3 (mucosal) ± desmoglein 1.'),
(45, 20, 'DIF pattern in pemphigus vulgaris?', 'Intercellular IgG/C3 – "fishnet" or "chicken-wire" pattern.'),
(46, 21, 'Drug of choice for trigeminal neuralgia?', 'Carbamazepine (screen HLA-B*1502 in Asian patients).'),
(47, 21, 'Usual vessel compressing the trigeminal root?', 'Superior cerebellar artery.'),
(48, 22, 'Grade C criteria for periodontitis?', '% bone loss ÷ age > 1.0, or smoker ≥ 10/day, or HbA1c ≥ 7%.'),
(49, 22, 'What moves a Stage III case to Stage IV?', '≥ 5 teeth lost to periodontitis or need for complex rehabilitation (e.g. bite collapse, < 20 teeth).'),
(50, 23, 'Four zones of an enamel caries lesion (from the front)?', 'Translucent zone, dark zone, body of the lesion, surface zone.'),
(51, 23, 'Critical pH for enamel demineralisation?', 'About 5.5.'),
(52, 24, 'Irrigant that removes the inorganic smear layer?', 'EDTA 17% (chelating agent).'),
(53, 24, 'NaOCl + chlorhexidine produce?', 'A brown precipitate (para-chloroaniline) – rinse between them.'),
(54, 25, 'Probably toxic dose of fluoride?', '5 mg F per kg body weight – needs immediate treatment and hospital care.'),
(55, 25, 'Concentration of fluoride in 1.23% APF gel?', '12,300 ppm (pH about 3.5).'),
(56, 26, 'Frankl rating "2"?', 'Negative – reluctant to accept treatment, some evidence of negative attitude.'),
(57, 26, 'Why give 100% oxygen after N₂O sedation?', 'To prevent diffusion hypoxia.'),
(58, 27, 'Angle Class II div 2 incisors?', 'Retroclined maxillary central incisors (laterals often flared), deep bite.'),
(59, 27, '"Key to occlusion" per Angle?', 'Maxillary permanent first molar.'),
(60, 28, 'Coleman''s sign?', 'Sublingual haematoma – suggests a fracture of the mandibular body/parasymphysis.'),
(61, 28, 'Bilateral condylar fracture causes?', 'Anterior open bite (posterior gagging of occlusion).'),
(62, 29, 'Spaces involved in Ludwig''s angina?', 'Bilateral submandibular, sublingual and submental spaces.'),
(63, 29, 'First priority in Ludwig''s angina?', 'Securing the airway (fibreoptic intubation or tracheostomy).'),
(64, 30, 'Freeway space?', 'VDR − VDO, about 2–4 mm.'),
(65, 30, 'Clicking of teeth during speech in new dentures suggests?', 'Increased vertical dimension of occlusion.'),
(66, 31, 'Where is a dentigerous cyst attached to the tooth?', 'At the cemento-enamel junction of an unerupted tooth.'),
(67, 31, 'Most common developmental odontogenic cyst?', 'Dentigerous cyst.'),
(68, 32, 'Histological pattern of fibrous dysplasia?', '"Chinese letter" trabeculae of woven bone without osteoblastic rimming.'),
(69, 32, 'Triad of McCune–Albright syndrome?', 'Polyostotic fibrous dysplasia, café-au-lait spots, endocrinopathy (e.g. precocious puberty).'),
(70, 33, 'Theory for the cause of dry socket?', 'Birn''s fibrinolytic theory – lysis of the blood clot.'),
(71, 33, 'Typical onset of dry socket?', '2–4 days after extraction.'),
(72, 34, 'Primary stress-bearing area of the mandibular denture?', 'Buccal shelf.'),
(73, 34, 'Impression theory proposed by Boucher?', 'Selective pressure theory.'),
(74, 35, 'Ideal apical end point of obturation?', '0.5–1 mm short of the radiographic apex, at the apical constriction.'),
(75, 35, 'Overfill vs overextension?', 'Overextension: material beyond the apex regardless of seal. Overfill: beyond the apex with the canal fully obturated.'),
(76, 36, 'Space maintainer when a primary second molar is lost before the first permanent molar erupts?', 'Distal shoe.'),
(77, 36, 'When does most space loss occur after an extraction?', 'Within the first 6 months.'),
(78, 37, 'Rule of 10s for cleft lip repair?', '10 weeks old, 10 lb weight, haemoglobin 10 g/dL.'),
(79, 37, 'Timing of secondary alveolar bone grafting?', 'About 9–11 years, before the permanent canine erupts.'),
(80, 38, 'Tissue-borne functional appliance?', 'Frankel function regulator.'),
(81, 38, 'Ideal timing for functional appliance therapy?', 'Around the pubertal growth spurt (assessed by CVM stage or hand–wrist radiograph).'),
(82, 39, 'HbA1c diagnostic threshold for diabetes?', '≥ 6.5% (reflects the previous 2–3 months).'),
(83, 39, 'Management of conscious hypoglycaemia in the chair?', '15–20 g fast-acting oral glucose; recheck after 10–15 minutes.'),
(84, 40, 'At what ATLS class does hypotension usually appear?', 'Class III (30–40% blood loss).'),
(85, 40, 'Shock index?', 'Heart rate ÷ systolic BP; > 1 suggests significant shock.'),
(86, 41, 'Keloid vs hypertrophic scar?', 'Keloid grows beyond the wound margins; hypertrophic scar stays within them.'),
(87, 41, 'Key cell orchestrating wound repair?', 'Macrophage.'),
(88, 42, 'Who introduced the DMF index and when?', 'Klein, Palmer and Knutson, 1938.'),
(89, 42, 'WHO global monitoring age for caries?', '12 years.'),
(90, 43, 'Why does aspirin''s antiplatelet effect last 7–10 days?', 'It irreversibly acetylates platelet COX-1; platelets cannot make new enzyme.'),
(91, 43, 'Analgesic of choice for a patient on warfarin?', 'Paracetamol (avoid NSAIDs).'),
(92, 44, 'Chin deviation in unilateral TMJ ankylosis?', 'Towards the affected side.'),
(93, 44, 'Graft used to reconstruct the ramus in a child with TMJ ankylosis?', 'Costochondral graft.'),
(94, 45, 'Approach for elevating an isolated zygomatic arch fracture?', 'Gillies temporal approach.'),
(95, 45, 'Nerve causing cheek and upper-lip numbness in zygomatic fractures?', 'Infraorbital nerve.'),
(96, 46, 'Flap described by Rehrmann for OAC closure?', 'Buccal advancement flap.'),
(97, 46, 'Approach for retrieving a root displaced into the maxillary sinus?', 'Caldwell–Luc approach (or through the socket/endoscopically).'),
(98, 47, 'Conditioner used before GIC placement?', '10% polyacrylic acid for 10–20 seconds.'),
(99, 47, 'Role of tartaric acid in GIC?', 'Improves handling: lengthens working time and sharpens the set.'),
(100, 48, 'Most caries-prone fissure types (Nagano)?', 'I and IK types.'),
(101, 48, 'Sealant choice for a partially erupted molar with poor isolation?', 'Glass ionomer sealant.'),
(102, 49, 'Appliance that expands the maxilla and blocks thumb sucking?', 'Quad helix with a palatal crib.'),
(103, 49, 'Facial appearance of a chronic mouth breather?', 'Adenoid facies: long face, incompetent lips, narrow high palate.'),
(104, 50, 'Minimum depth from gingival margin to floor of mouth for a lingual bar?', 'About 8 mm.'),
(105, 50, 'RPI system components?', 'Mesial Rest, distal Proximal plate, I-bar.'),
(106, 51, 'Albrektsson criterion for annual bone loss after year one?', 'Less than 0.2 mm per year.'),
(107, 51, 'Who coined "osseointegration"?', 'Per-Ingvar Brånemark.'),
(108, 52, 'Antibiotic of choice in necrotising gingivitis with systemic signs?', 'Metronidazole (e.g. 400 mg three times daily for 3 days).'),
(109, 52, 'Listgarten''s zones in NUG?', 'Bacterial, neutrophil-rich, necrotic, and spirochaetal infiltration zones.'),
(110, 53, 'Aphthous type that heals with scarring?', 'Major (Sutton''s) aphthae.'),
(111, 53, 'Key systemic disease with oral and genital ulcers and uveitis?', 'Behçet''s disease.'),
(112, 54, 'AHA prophylaxis regimen for adults?', 'Amoxicillin 2 g orally 30–60 minutes before the procedure.'),
(113, 54, 'Painful nodules on finger pulps in endocarditis?', 'Osler''s nodes (Janeway lesions are painless).'),
(114, 55, 'Biological indicator for autoclaves?', 'Geobacillus stearothermophilus spores.'),
(115, 55, 'Chairside disinfection of gutta-percha cones?', '5.25% sodium hypochlorite for about 1 minute.'),
(116, 56, 'Remnants of Hertwig''s epithelial root sheath?', 'Epithelial rests of Malassez (in the PDL).'),
(117, 56, 'Signalling centre in the cap stage?', 'The enamel knot.'),
(118, 57, 'Surface manifestation of striae of Retzius?', 'Perikymata.'),
(119, 57, 'Optical banding from changing rod direction?', 'Hunter–Schreger bands.'),
(120, 58, 'Theory explaining dentine hypersensitivity?', 'Brännström''s hydrodynamic theory (fluid movement in tubules).'),
(121, 58, 'Dentine formed by surviving odontoblasts in response to a mild stimulus?', 'Reactionary (tertiary) dentine.'),
(122, 59, 'Most numerous principal fibre group of the PDL?', 'Oblique fibres.'),
(123, 59, 'Procedure to cut transseptal fibres and reduce rotation relapse?', 'Circumferential supracrestal fibrotomy.'),
(124, 60, 'Tongue papillae with no taste buds?', 'Filiform papillae.'),
(125, 60, 'Ectopic sebaceous glands in the buccal mucosa?', 'Fordyce''s spots (granules).'),
(126, 61, 'Commonest inherited bleeding disorder?', 'von Willebrand disease.'),
(127, 61, 'Haemophilia lab profile?', 'Prolonged aPTT; normal PT, platelet count and bleeding time.'),
(128, 62, 'Exit foramen of the facial nerve from the skull?', 'Stylomastoid foramen.'),
(129, 62, 'Facial palsy sparing the forehead?', 'Upper motor neuron lesion (e.g. stroke).'),
(130, 63, 'W/P ratio of type IV die stone?', 'About 0.22–0.24.'),
(131, 63, 'Setting theory of gypsum?', 'Dissolution–precipitation (crystalline) theory.'),
(132, 64, 'Most dimensionally stable elastomer?', 'Addition silicone (polyvinyl siloxane).'),
(133, 64, 'Elastomer with the highest tear strength?', 'Polysulphide.'),
(134, 65, 'Who described the hybrid layer?', 'Nakabayashi (1982).'),
(135, 65, 'C-factor of a Class I cavity?', '5 (five bonded surfaces to one free surface).'),
(136, 66, 'Ceramic preferred for a posterior all-ceramic bridge?', 'Zirconia (monolithic or layered).'),
(137, 66, 'Surface treatment for lithium disilicate before bonding?', 'Hydrofluoric acid etch, then silane.'),
(138, 67, 'Do antibiotics relieve irreversible pulpitis pain?', 'No – remove the pulp tissue (pulpectomy/pulpotomy) and give analgesics.'),
(139, 67, 'First step in a hypochlorite accident?', 'Stop and irrigate the canal gently with saline.'),
(140, 68, 'Normal ANB angle?', 'About 2° (0–4°); > 4° skeletal Class II, negative = Class III.'),
(141, 68, 'Tweed triangle norms?', 'FMA 25°, IMPA 90°, FMIA 65°.'),
(142, 69, 'Orthodontic movement needing the lightest force?', 'Intrusion (about 10–20 g).'),
(143, 69, 'Resorption type seen after hyalinisation?', 'Undermining (indirect) resorption.'),
(144, 70, 'Study of lip prints?', 'Cheiloscopy (Suzuki and Tsuchihashi classification).'),
(145, 70, 'First adult dental age-estimation method?', 'Gustafson''s method (1950), six criteria.'),
(146, 71, 'Why is the cavosurface angle 90° for amalgam?', 'Amalgam is brittle in thin section – a butt joint prevents marginal fracture.'),
(147, 71, 'Class VI cavity (Simon)?', 'Incisal edges of anterior teeth and cusp tips of posterior teeth.'),
(148, 72, 'Newton type III denture stomatitis?', 'Papillary hyperplasia of the palate.'),
(149, 72, 'Antifungal that interacts dangerously with warfarin?', 'Miconazole (also fluconazole) – raises INR.'),
(150, 73, 'Gland most affected by sialolithiasis?', 'Submandibular gland (about 80–90%).'),
(151, 73, 'Antibodies typical of Sjögren''s syndrome?', 'Anti-Ro (SSA) and anti-La (SSB).'),
(152, 74, 'Occupational dose limit (ICRP)?', '20 mSv per year (averaged over 5 years).'),
(153, 74, 'Most effective way to cut intraoral radiograph dose?', 'Rectangular collimation.'),
(154, 75, 'Commonest supernumerary tooth?', 'Mesiodens (between the upper central incisors).'),
(155, 75, 'Teeth joined by cementum only?', 'Concrescence.'),
(156, 76, 'Triad of Plummer–Vinson syndrome?', 'Iron-deficiency anaemia, dysphagia (oesophageal web), glossitis.'),
(157, 76, 'Radiographic skull sign in thalassaemia major?', '"Hair-on-end" appearance.'),
(158, 77, 'Glickman grade III furcation?', 'Through-and-through bone loss, still covered by soft tissue.'),
(159, 77, 'Probe used to examine furcations?', 'Nabers probe.'),
(160, 78, 'Who described the modified Widman flap?', 'Ramfjord and Nissle (1974).'),
(161, 78, 'Primary incision in flap surgery?', 'Internal (inverse) bevel incision.'),
(162, 79, 'Teeth that may be rotated during extraction?', 'Conical single-rooted teeth – upper central incisors and lower premolars.'),
(163, 79, 'Mechanical principles of exodontia?', 'Expansion, lever, wedge, wheel-and-axle.'),
(164, 80, 'Hanau''s formula?', 'L = H/8 + 12 (lateral from horizontal condylar guidance).'),
(165, 80, 'Arcon articulator?', 'Condylar elements on the lower member, as in the natural joint (e.g. Whip-Mix).'),
(166, 81, 'Complaint from excessive vertical dimension of occlusion?', 'Clicking of teeth, sore ridges, tired muscles; no freeway space.'),
(167, 81, 'Cause of cheek biting with dentures?', 'Insufficient buccal overjet (posterior teeth edge to edge).'),
(168, 82, 'Ante''s law?', 'Abutment root surface area should equal or exceed that of the teeth replaced.'),
(169, 82, 'Effect of doubling pontic span on deflection?', 'Deflection increases eight times (length cubed).'),
(170, 83, 'Preferred teeth for overdenture abutments?', 'Canines (then premolars) – long roots, strategic position.'),
(171, 83, 'McGill consensus (2002)?', 'Two-implant overdenture as the minimum standard for the edentulous mandible.'),
(172, 84, 'Contraindication to epinephrine retraction cord?', 'Cardiovascular disease, hyperthyroidism, patients on MAO inhibitors.'),
(173, 84, 'Minimum lateral gingival displacement for elastomeric impressions?', 'About 0.2 mm.'),
(174, 85, 'Levels removed in a supraomohyoid neck dissection?', 'Levels I, II and III.'),
(175, 85, 'Three structures sacrificed in a classical radical neck dissection?', 'Spinal accessory nerve, internal jugular vein, sternocleidomastoid.'),
(176, 86, 'Parkland formula?', '4 mL × body weight (kg) × %TBSA of Ringer''s lactate in 24 h; half in the first 8 h.'),
(177, 86, 'Area of the patient''s palm in burn estimation?', 'About 1% of total body surface area.'),
(178, 87, 'Usual tracheal rings for tracheostomy?', 'Second to fourth rings (avoid the first – subglottic stenosis).'),
(179, 87, 'Emergency surgical airway of choice?', 'Cricothyroidotomy.'),
(180, 88, 'Teeth spared in nursing-bottle caries?', 'Mandibular incisors.'),
(181, 88, 'Toothpaste amount for a child under 3?', 'A smear (rice-grain size) of fluoridated toothpaste.'),
(182, 89, 'Cement of choice for stainless steel crowns?', 'Glass ionomer cement.'),
(183, 89, 'Hall technique?', 'Cementing a preformed metal crown without caries removal or preparation, sealing the lesion.'),
(184, 90, 'Key feature of irreversible pulpitis?', 'Lingering pain (> 30 seconds) after the stimulus, often spontaneous or at night.'),
(185, 90, 'Diffuse periapical radiopacity with chronic pulpal inflammation?', 'Condensing osteitis.'),
(186, 91, 'Cervical lesion attributed to occlusal flexural stress?', 'Abfraction (Grippo).'),
(187, 91, 'Tooth surfaces affected by intrinsic erosion?', 'Palatal surfaces of maxillary anterior teeth.')
insert into public.spotters (id, subject_id, topic_id, category, title, image_url, stain, key_findings, differentials, distractors, diagnostic_pearl, uses, difficulty) overriding system value values
(1, 1, 1, 'radiograph', 'Ameloblastoma (multilocular radiolucency)', 'spotters/r-ameloblastoma.svg', null, array['Multilocular "soap-bubble" radiolucency in the molar–ramus region','Expansion and thinning of the cortex','Knife-edge resorption of adjacent molar roots']::text[], array['Odontogenic keratocyst','Central giant cell granuloma','Odontogenic myxoma']::text[], array['Odontogenic keratocyst','Central giant cell granuloma','Radicular cyst']::text[], 'Large loculi = soap-bubble; small loculi = honeycomb. Root resorption favours ameloblastoma over OKC.', array[]::text[], 1),
(2, 1, 3, 'radiograph', 'Radicular cyst', 'spotters/r-radicular-cyst.svg', null, array['Well-defined, round, corticated radiolucency at the apex','Associated tooth has deep caries (non-vital)','Loss of lamina dura at the apex']::text[], array['Periapical granuloma','Periapical abscess']::text[], array['Periapical cemento-osseous dysplasia','Dentigerous cyst','Stafne bone cavity']::text[], 'Always check vitality – a radicular cyst is always associated with a non-vital tooth.', array[]::text[], 1),
(3, 1, null, 'radiograph', 'Dentigerous cyst', 'spotters/r-dentigerous-cyst.svg', null, array['Unilocular radiolucency around the crown of an unerupted third molar','Attached at the cemento-enamel junction','Well-corticated margin']::text[], array['Hyperplastic follicle (< 3–4 mm space)','Unicystic ameloblastoma','OKC']::text[], array['Radicular cyst','Odontoma','Calcifying odontogenic cyst']::text[], 'Pericoronal space > 5 mm suggests a dentigerous cyst rather than a normal follicle.', array[]::text[], 1),
(4, 2, null, 'radiograph', 'Osteosarcoma (sunray appearance)', 'spotters/r-osteosarcoma.svg', null, array['Spicules of new bone radiating outward ("sunray / sunburst")','Ill-defined, destructive margins','Symmetrical widening of the PDL space (Garrington sign)']::text[], array['Ewing sarcoma (onion-skin)','Chondrosarcoma','Metastatic prostate carcinoma']::text[], array['Fibrous dysplasia','Paget disease','Osteomyelitis']::text[], 'Garrington sign (symmetric PDL widening) is an early sign of jaw osteosarcoma.', array[]::text[], 2),
(5, 2, null, 'radiograph', 'Fibrous dysplasia (ground-glass)', 'spotters/r-fibrous-dysplasia.svg', null, array['Ground-glass (orange-peel) opacity','Margins blend imperceptibly into normal bone','Expansion with displacement of teeth; maxilla more common']::text[], array['Ossifying fibroma (well-defined)','Paget disease (cotton-wool)']::text[], array['Osteosarcoma','Ameloblastoma','Cherubism']::text[], 'Ill-defined margins = fibrous dysplasia; well-defined with a lucent rim = ossifying fibroma.', array[]::text[], 2),
(6, 1, 1, 'histology', 'Follicular ameloblastoma', 'spotters/h-ameloblastoma.svg', 'H&E, 10×', array['Islands (follicles) of odontogenic epithelium','Peripheral tall columnar cells with reverse polarity','Central stellate reticulum-like cells']::text[], array['Ameloblastic fibroma','Adenomatoid odontogenic tumour']::text[], array['Odontogenic keratocyst','Pleomorphic adenoma','Squamous cell carcinoma']::text[], 'Reverse polarity: nuclei move away from the basement membrane.', array[]::text[], 1),
(7, 1, 2, 'histology', 'Odontogenic keratocyst', 'spotters/h-okc.svg', 'H&E, 20×', array['Thin, uniform epithelium of 6–8 cell layers','Corrugated parakeratin surface','Palisaded "tombstone" basal cells; flat interface']::text[], array['Orthokeratinised odontogenic cyst','Dentigerous cyst']::text[], array['Radicular cyst','Ameloblastoma','Lichen planus']::text[], 'Corrugated parakeratin + palisaded basal layer + flat interface = OKC.', array[]::text[], 2),
(8, 2, 6, 'histology', 'Lichen planus', 'spotters/h-lichen-planus.svg', 'H&E, 10×', array['Saw-tooth rete ridges','Dense band-like subepithelial lymphocytic infiltrate','Basal cell liquefaction; Civatte bodies']::text[], array['Lichenoid drug reaction','Lupus erythematosus']::text[], array['Leukoplakia with dysplasia','Pemphigus vulgaris','Oral submucous fibrosis']::text[], 'Band-like lymphocytes hugging the basement membrane is the key to lichen planus.', array[]::text[], 2),
(9, 1, null, 'histology', 'Well-differentiated squamous cell carcinoma', 'spotters/h-scc.svg', 'H&E, 10×', array['Invasive islands of malignant squamous epithelium in connective tissue','Keratin pearls (concentric lamellated keratin)','Cellular and nuclear pleomorphism']::text[], array['Verrucous carcinoma','Pseudoepitheliomatous hyperplasia']::text[], array['Ameloblastoma','Basal cell carcinoma','Odontogenic keratocyst']::text[], 'Keratin pearls indicate a well-differentiated SCC (Broders grade I).', array[]::text[], 1),
(10, 5, null, 'instrument', 'WHO (CPITN) periodontal probe', 'spotters/i-who-probe.svg', null, array['0.5 mm ball tip','Black band from 3.5 to 5.5 mm','Further markings at 8.5 and 11.5 mm']::text[], array['Williams probe','UNC-15 probe']::text[], array['Williams probe','Nabers probe','Explorer No. 23']::text[], 'Light probing force of about 20–25 g.', array['Community Periodontal Index (CPI / CPITN)','Ball tip detects calculus and avoids over-penetration']::text[], 1),
(11, 3, null, 'instrument', 'Straight elevator', 'spotters/i-straight-elevator.svg', null, array['Straight shank with concave blade','Pear-shaped handle','Works on the wheel-and-axle and wedge principles']::text[], array['Coupland chisel','Periosteal elevator']::text[], array['Cryer''s elevator','Periosteal elevator','Warwick James'' elevator']::text[], 'Never use an adjacent tooth as a fulcrum unless it is also being extracted.', array['Luxation of teeth and roots before forceps extraction','Concave surface faces the tooth to be extracted']::text[], 1),
(12, 3, null, 'instrument', 'Cryer''s elevator (East–West)', 'spotters/i-cryer.svg', null, array['Triangular, pointed blade at right angles to the shank','Used in pairs – right and left','Wheel-and-axle principle']::text[], array['Winter''s cross-bar elevator']::text[], array['Straight elevator','Warwick James'' elevator','Coupland chisel']::text[], 'Also called the triangular or East–West elevator.', array['Removal of a retained root when the other root of a molar has been extracted','Inserted into the empty socket, engages the inter-radicular bone']::text[], 2),
(13, 4, null, 'instrument', 'Amalgam carrier', 'spotters/i-amalgam-carrier.svg', null, array['Hollow barrel at the working end','Spring-loaded plunger with lever','Double-ended in some designs (small and large barrel)']::text[], array[]::text[], array['Amalgam condenser','Burnisher','Composite gun']::text[], 'Do not leave amalgam in the barrel – it sets and jams the plunger.', array['Carries triturated amalgam to the prepared cavity in increments']::text[], 1),
(14, 1, null, 'specimen', 'Compound odontome', 'spotters/s-compound-odontome.svg', null, array['Multiple small, tooth-like structures (denticles)','Enamel, dentine, cementum and pulp in normal relationship','Usually anterior maxilla; may block eruption of a permanent tooth']::text[], array['Complex odontome (disorganised mass, posterior mandible)']::text[], array['Complex odontome','Cementoblastoma','Supernumerary tooth']::text[], 'Compound = anterior maxilla, tooth-like; complex = posterior mandible, amorphous mass.', array[]::text[], 2)
insert into public.mcq_questions (id, subject, question, options, answer, explanation, is_pyq, is_important, exam) values
(1, 'Dental Anatomy', 'Which is usually the first permanent tooth to erupt in the oral cavity?', array['Maxillary central incisor','Mandibular central incisor','Mandibular first molar','Maxillary first molar']::text[], 2, 'The mandibular first molar erupts at about 6 years, usually just before the mandibular central incisor. It is the first succedaneous-free (non-replacing) permanent tooth.', true, true, 'NEET MDS'),
(2, 'Dental Anatomy', 'Cusp of Carabelli is seen on which cusp of the maxillary first molar?', array['Mesiobuccal','Distobuccal','Mesiopalatal','Distopalatal']::text[], 2, 'The cusp of Carabelli is an accessory cusp on the palatal surface of the mesiopalatal (mesiolingual) cusp of the maxillary first molar.', true, true, 'NEET MDS'),
(3, 'Dental Anatomy', 'The longest root in the permanent dentition is seen in:', array['Maxillary central incisor','Maxillary canine','Mandibular canine','Maxillary first premolar']::text[], 1, 'The maxillary canine has the longest root of all teeth, making it a key abutment and the ''cornerstone'' of the arch.', true, false, 'NEET MDS'),
(4, 'Dental Anatomy', 'A ''Y''-shaped occlusal groove pattern is characteristic of:', array['Two-cusp mandibular second premolar','Three-cusp mandibular second premolar','Maxillary first premolar','Mandibular first premolar']::text[], 1, 'The three-cusp (one buccal, two lingual) form of the mandibular second premolar shows a Y-shaped groove; the two-cusp form shows an H or U pattern.', false, true, 'NEET MDS'),
(5, 'Dental Anatomy', 'Which permanent tooth commonly has two roots (buccal and palatal)?', array['Maxillary second premolar','Maxillary first premolar','Mandibular first premolar','Maxillary canine']::text[], 1, 'The maxillary first premolar usually has two roots – buccal and palatal. The second premolar usually has one.', true, false, 'NEET MDS'),
(6, 'Anatomy', 'Muscles of mastication are supplied by:', array['Facial nerve','Maxillary nerve','Mandibular nerve','Hypoglossal nerve']::text[], 2, 'All four muscles of mastication (masseter, temporalis, medial and lateral pterygoid) are supplied by the mandibular division of the trigeminal nerve (V3).', true, true, 'NEET MDS'),
(7, 'Anatomy', 'Which muscle of the tongue is NOT supplied by the hypoglossal nerve?', array['Genioglossus','Hyoglossus','Styloglossus','Palatoglossus']::text[], 3, 'Palatoglossus is supplied by the vagus nerve via the pharyngeal plexus. All other tongue muscles are supplied by the hypoglossal nerve.', true, true, 'NEET MDS'),
(8, 'Anatomy', 'The parotid (Stensen''s) duct opens opposite the:', array['Maxillary first premolar','Maxillary second molar','Mandibular first molar','Maxillary canine']::text[], 1, 'Stensen''s duct pierces the buccinator and opens into the vestibule opposite the crown of the maxillary second molar.', true, false, 'NEET MDS'),
(9, 'Anatomy', 'General sensation from the anterior two-thirds of the tongue is carried by the:', array['Chorda tympani','Glossopharyngeal nerve','Lingual nerve','Hypoglossal nerve']::text[], 2, 'The lingual nerve (V3) carries general sensation from the anterior 2/3. Taste from that area travels in the chorda tympani (VII).', false, true, 'NEET MDS'),
(10, 'Anatomy', 'Which muscle is chiefly responsible for protrusion and depression (opening) of the mandible?', array['Masseter','Temporalis','Medial pterygoid','Lateral pterygoid']::text[], 3, 'The lateral pterygoid pulls the condyle and disc forward, so it protrudes the mandible and helps open the mouth. The other three muscles close it.', true, false, 'NEET MDS'),
(11, 'Physiology', 'Which salivary gland contributes most to unstimulated (resting) saliva?', array['Parotid','Submandibular','Sublingual','Minor salivary glands']::text[], 1, 'At rest the submandibular gland produces about 65–70% of saliva. On stimulation, the parotid''s share rises sharply.', true, true, 'NEET MDS'),
(12, 'Physiology', 'The normal pacemaker of the heart is the:', array['AV node','SA node','Bundle of His','Purkinje fibres']::text[], 1, 'The SA node has the fastest intrinsic rate of depolarisation, so it sets the heart rate.', true, false, 'NEET MDS'),
(13, 'Physiology', 'Which hormone raises serum calcium levels?', array['Calcitonin','Parathormone','Insulin','Glucagon']::text[], 1, 'Parathormone raises serum calcium by increasing bone resorption, renal calcium reabsorption and calcitriol formation. Calcitonin lowers calcium.', false, true, 'NEET MDS'),
(14, 'Physiology', 'Bleeding time mainly assesses:', array['Intrinsic pathway','Extrinsic pathway','Platelet function','Fibrinolysis']::text[], 2, 'Bleeding time reflects platelet number and function (primary haemostasis). PT tests the extrinsic pathway and aPTT the intrinsic pathway.', true, true, 'NEET MDS'),
(15, 'Physiology', 'The vitamin K–dependent clotting factors are:', array['I, II, V, VIII','II, VII, IX, X','III, V, VIII, XI','VIII, IX, XI, XII']::text[], 1, 'Factors II, VII, IX and X (plus proteins C and S) need vitamin K for gamma-carboxylation. Warfarin antagonises this step.', true, true, 'NEET MDS'),
(16, 'Biochemistry', 'Vitamin C deficiency impairs collagen synthesis by affecting:', array['Glycosylation of lysine','Hydroxylation of proline and lysine','Cleavage of procollagen','Cross-linking by lysyl oxidase']::text[], 1, 'Ascorbic acid is a cofactor for prolyl and lysyl hydroxylases. Without it, collagen is unstable, which causes scurvy with bleeding, swollen gums.', true, true, 'NEET MDS'),
(17, 'Biochemistry', 'The most abundant amino acid in collagen is:', array['Proline','Hydroxyproline','Glycine','Lysine']::text[], 2, 'Glycine occupies every third position (Gly-X-Y), which allows the tight triple-helix packing.', true, false, 'NEET MDS'),
(18, 'Pathology', 'Reed–Sternberg cells are characteristic of:', array['Non-Hodgkin lymphoma','Hodgkin lymphoma','Multiple myeloma','Burkitt lymphoma']::text[], 1, 'Reed–Sternberg cells are large ''owl-eye'' cells and are the hallmark of Hodgkin lymphoma.', true, false, 'NEET MDS'),
(19, 'Pathology', 'The most common malignant tumour of the oral cavity is:', array['Adenocarcinoma','Squamous cell carcinoma','Basal cell carcinoma','Melanoma']::text[], 1, 'Over 90% of oral cancers are squamous cell carcinomas.', true, true, 'NEET MDS'),
(20, 'Pathology', '''Starry sky'' appearance on histology is seen in:', array['Hodgkin lymphoma','Burkitt lymphoma','Multiple myeloma','CLL']::text[], 1, 'In Burkitt lymphoma, tingible-body macrophages scattered among sheets of tumour cells give the ''starry sky'' pattern.', false, true, 'NEET MDS'),
(21, 'Microbiology', 'The organism chiefly associated with the initiation of dental caries is:', array['Lactobacillus acidophilus','Streptococcus mutans','Actinomyces viscosus','Porphyromonas gingivalis']::text[], 1, 'S. mutans initiates enamel caries. Lactobacilli are linked more with progression of the lesion.', true, true, 'NEET MDS'),
(22, 'Microbiology', 'Standard autoclave conditions are:', array['100 °C for 30 min','121 °C at 15 psi for 15 min','160 °C for 1 h','134 °C at 5 psi for 1 min']::text[], 1, 'Moist heat at 121 °C and 15 psi for 15 minutes is the standard cycle. The flash cycle is 134 °C at about 30 psi for 3 minutes.', true, true, 'NEET MDS'),
(23, 'Microbiology', 'Localized aggressive periodontitis is most strongly associated with:', array['Treponema denticola','Aggregatibacter actinomycetemcomitans','Fusobacterium nucleatum','Streptococcus sanguinis']::text[], 1, 'A. actinomycetemcomitans (which produces leukotoxin) is the key pathogen in localized aggressive periodontitis.', true, true, 'NEET MDS'),
(24, 'Microbiology', 'Koplik''s spots are seen in:', array['Mumps','Measles','Rubella','Chickenpox']::text[], 1, 'Koplik''s spots are bluish-white spots on the buccal mucosa that appear in the prodrome of measles (rubeola).', true, false, 'NEET MDS'),
(25, 'Pharmacology', 'The drug of choice for anaphylactic shock is:', array['Hydrocortisone IV','Adrenaline IM','Chlorpheniramine','Atropine']::text[], 1, 'Adrenaline 1:1000 at 0.5 mg IM (adult) is first-line. Antihistamines and steroids are only adjuncts.', true, true, 'NEET MDS'),
(26, 'Pharmacology', 'The maximum recommended dose of lignocaine WITH adrenaline is:', array['2 mg/kg','4.4 mg/kg','7 mg/kg','10 mg/kg']::text[], 2, 'About 7 mg/kg with adrenaline (500 mg max), and about 4.4 mg/kg without it (300 mg max). The vasoconstrictor slows absorption.', true, true, 'NEET MDS'),
(27, 'Pharmacology', 'The antidote for heparin overdose is:', array['Vitamin K','Protamine sulfate','Fresh frozen plasma','Tranexamic acid']::text[], 1, 'Protamine sulfate neutralises heparin. Vitamin K reverses warfarin.', true, false, 'NEET MDS'),
(28, 'Pharmacology', 'Which local anaesthetic belongs to the ester group?', array['Lignocaine','Bupivacaine','Procaine','Articaine']::text[], 2, 'Procaine is an ester. The others are amides; a quick check is that amide names contain two ''i''s (e.g. l-i-gnoca-i-ne). Articaine is an amide with an ester side chain.', false, true, 'NEET MDS'),
(29, 'Pharmacology', 'Gingival enlargement is a well-known side effect of:', array['Aspirin','Phenytoin','Paracetamol','Amoxicillin']::text[], 1, 'Phenytoin, cyclosporine and calcium-channel blockers (e.g. nifedipine) cause drug-induced gingival overgrowth.', true, true, 'NEET MDS'),
(30, 'Dental Materials', 'The gamma-2 phase in dental amalgam is:', array['Ag3Sn','Ag2Hg3','Sn7-8Hg','Cu6Sn5']::text[], 2, 'Gamma-2 (Sn–Hg) is the weakest and most corrosion-prone phase. High-copper alloys eliminate it by forming Cu6Sn5 instead.', true, true, 'NEET MDS'),
(31, 'Dental Materials', 'Which restorative material has a coefficient of thermal expansion closest to tooth structure?', array['Amalgam','Composite resin','Glass ionomer cement','Gold alloy']::text[], 2, 'GIC''s coefficient of thermal expansion is close to that of dentine, which helps it seal well.', true, true, 'NEET MDS'),
(32, 'Dental Materials', 'Die stone with high strength and low setting expansion is ADA:', array['Type I','Type II','Type III','Type IV']::text[], 3, 'Type IV (die stone, high strength, low expansion) is used for dies. Type V has high strength with high expansion.', true, false, 'NEET MDS'),
(33, 'Dental Materials', 'The most hydrophilic elastomeric impression material is:', array['Polysulfide','Condensation silicone','Addition silicone','Polyether']::text[], 3, 'Polyether is inherently hydrophilic, but it also absorbs water, so it must not be stored wet.', true, true, 'NEET MDS'),
(34, 'Dental Materials', 'The liquid of zinc phosphate cement is mainly:', array['Polyacrylic acid','Eugenol','Phosphoric acid','Acetic acid']::text[], 2, 'It is buffered phosphoric acid (with Al and Zn salts). Its low initial pH can irritate the pulp.', true, false, 'NEET MDS'),
(35, 'Oral Pathology', 'The most common odontogenic cyst is the:', array['Dentigerous cyst','Radicular cyst','Odontogenic keratocyst','Lateral periodontal cyst']::text[], 1, 'The radicular (periapical) cyst is the most common odontogenic cyst. The dentigerous cyst is the most common developmental one.', true, true, 'NEET MDS'),
(36, 'Oral Pathology', 'A multilocular ''soap-bubble'' radiolucency in the posterior mandible of an adult most likely suggests:', array['Radicular cyst','Ameloblastoma','Odontoma','Cementoblastoma']::text[], 1, 'Ameloblastoma typically shows a multilocular soap-bubble or honeycomb pattern in the molar–ramus region, often with root resorption.', true, true, 'NEET MDS'),
(37, 'Oral Pathology', 'Multiple odontogenic keratocysts are a feature of:', array['Gardner syndrome','Gorlin–Goltz syndrome','Peutz–Jeghers syndrome','Cherubism']::text[], 1, 'Gorlin–Goltz (nevoid basal cell carcinoma) syndrome: multiple OKCs, basal cell carcinomas, bifid ribs, and calcified falx cerebri.', true, true, 'NEET MDS'),
(38, 'Oral Pathology', '''Ghost cells'' are characteristic of:', array['Calcifying odontogenic cyst','Adenomatoid odontogenic tumour','Pindborg tumour','Odontogenic myxoma']::text[], 0, 'Ghost cells are anucleate, swollen keratinised epithelial cells. They are the hallmark of the calcifying odontogenic cyst (Gorlin cyst).', true, false, 'NEET MDS'),
(39, 'Oral Pathology', 'Liesegang ring calcifications and amyloid are seen in:', array['Ameloblastoma','Calcifying epithelial odontogenic tumour','AOT','Ameloblastic fibroma']::text[], 1, 'CEOT (Pindborg tumour) shows amyloid-like material with concentric Liesegang ring calcifications.', false, true, 'NEET MDS'),
(40, 'Oral Medicine & Radiology', 'Hutchinson''s incisors are seen in:', array['Ectodermal dysplasia','Congenital syphilis','Fluorosis','Amelogenesis imperfecta']::text[], 1, 'Hutchinson''s triad = notched screwdriver-shaped incisors, interstitial keratitis and VIII-nerve deafness. Mulberry molars are also seen.', true, true, 'NEET MDS'),
(41, 'Oral Medicine & Radiology', 'Which cells are the most radiosensitive?', array['Neurons','Muscle cells','Lymphocytes','Osteocytes']::text[], 2, 'Small lymphocytes are the most radiosensitive cells. Mature neurons and muscle cells are among the most radioresistant.', true, false, 'NEET MDS'),
(42, 'Oral Medicine & Radiology', 'A ''sunray'' or ''sunburst'' radiographic appearance is classically seen in:', array['Ewing sarcoma','Osteosarcoma','Fibrous dysplasia','Paget disease']::text[], 1, 'Spicules of tumour bone radiating outward give the sunburst appearance in osteosarcoma. Ewing sarcoma gives ''onion-peel''.', true, true, 'NEET MDS'),
(43, 'Oral Medicine & Radiology', '''Ground-glass'' appearance of the jaw is typical of:', array['Fibrous dysplasia','Osteomyelitis','Cherubism','Ameloblastoma']::text[], 0, 'Fibrous dysplasia shows a ground-glass (orange-peel) appearance with poorly defined margins that blend into normal bone.', false, true, 'NEET MDS'),
(44, 'Orthodontics', 'Angle''s Class II Division 2 malocclusion shows:', array['Proclined maxillary incisors','Retroclined maxillary central incisors','Anterior open bite','Mesial molar relation']::text[], 1, 'Div 2 shows retroclined maxillary centrals, often with proclined laterals and a deep bite. Div 1 shows proclined incisors.', true, true, 'NEET MDS'),
(45, 'Orthodontics', 'The leeway space in the mandibular arch is approximately (per side):', array['0.9 mm','1.7 mm','2.5 mm','3.4 mm']::text[], 1, 'Leeway space is about 0.9 mm per side in the maxilla and 1.7 mm per side in the mandible.', true, true, 'NEET MDS'),
(46, 'Orthodontics', 'The Activator (functional appliance) was introduced by:', array['Frankel','Andresen','Clark','Bimler']::text[], 1, 'Viggo Andresen developed the activator (Norwegian system). Clark designed the Twin Block, and Frankel the Function Regulator.', true, false, 'NEET MDS'),
(47, 'Orthodontics', 'The Twin Block appliance was developed by:', array['William Clark','Rolf Frankel','Herbert Balters','Pierre Robin']::text[], 0, 'William J. Clark introduced the Twin Block in 1977. Balters designed the Bionator.', false, true, 'NEET MDS'),
(48, 'Pedodontics', 'Buckley''s formocresol contains formaldehyde at:', array['5%','19%','35%','50%']::text[], 1, 'Buckley''s formocresol is 19% formaldehyde, 35% cresol and 15% glycerine in water. A 1:5 dilution is commonly used.', true, true, 'NEET MDS'),
(49, 'Pedodontics', 'In nursing bottle (early childhood) caries, the teeth typically spared are the:', array['Maxillary incisors','Mandibular incisors','Maxillary first molars','Maxillary canines']::text[], 1, 'Mandibular incisors are protected by the tongue and by saliva from the sublingual and submandibular ducts.', true, true, 'NEET MDS'),
(50, 'Pedodontics', 'Duraphat fluoride varnish contains:', array['2% NaF','5% NaF (22,600 ppm F)','1.23% APF','8% SnF2']::text[], 1, 'Duraphat is 5% sodium fluoride, which equals 22,600 ppm fluoride.', true, false, 'NEET MDS'),
(51, 'Periodontics', 'A probe with a 0.5 mm ball tip and a colour band at 3.5–5.5 mm is the:', array['Williams probe','Nabers probe','WHO (CPITN) probe','Marquis probe']::text[], 2, 'The WHO/CPITN probe has a 0.5 mm ball end with markings at 3.5, 5.5, 8.5 and 11.5 mm.', true, true, 'NEET MDS'),
(52, 'Periodontics', 'Gracey curette 11/12 is designed for:', array['Anterior teeth','Mesial surfaces of posterior teeth','Distal surfaces of posterior teeth','Facial and lingual of premolars']::text[], 1, '11/12 is for mesial surfaces of posterior teeth and 13/14 for distal surfaces. 1/2 and 3/4 are for anteriors.', true, true, 'NEET MDS'),
(53, 'Periodontics', 'According to Gargiulo, the average biologic width is about:', array['1.07 mm','2.04 mm','3.00 mm','0.69 mm']::text[], 1, 'Biologic width ≈ 0.97 mm epithelial attachment + 1.07 mm connective tissue attachment = 2.04 mm. Sulcus depth is about 0.69 mm.', true, true, 'NEET MDS'),
(54, 'Periodontics', 'The Plaque Index was introduced by:', array['Löe and Silness','Silness and Löe','Greene and Vermillion','Russell']::text[], 1, 'Plaque Index – Silness & Löe (1964). Gingival Index – Löe & Silness (1963). OHI-S – Greene & Vermillion.', true, false, 'NEET MDS'),
(55, 'Prosthodontics', 'Kennedy Class I partially edentulous arch has:', array['Unilateral distal extension','Bilateral distal extension','Unilateral bounded space','Single anterior space crossing midline']::text[], 1, 'Class I = bilateral posterior edentulous areas; Class II = unilateral distal extension; Class III = unilateral bounded; Class IV = a single anterior area crossing the midline.', true, true, 'NEET MDS'),
(56, 'Prosthodontics', 'The posterior palatal seal of a maxillary denture is placed at:', array['Rugae area','Junction of hard and soft palate (vibrating line)','Incisive papilla','Fovea palatini only']::text[], 1, 'The posterior palatal seal lies between the anterior and posterior vibrating lines, at the junction of hard and soft palate.', true, true, 'NEET MDS'),
(57, 'Prosthodontics', 'A Gothic arch (needle-point) tracing is used to record:', array['Vertical dimension','Centric relation','Protrusive relation only','Face-bow transfer']::text[], 1, 'The apex of the arrow-point tracing marks centric relation, a horizontal jaw relation.', true, false, 'NEET MDS'),
(58, 'Prosthodontics', 'The organism most commonly implicated in denture stomatitis is:', array['Staphylococcus aureus','Candida albicans','Streptococcus mutans','Herpes simplex']::text[], 1, 'Candida albicans, helped by poor denture hygiene and continuous wearing, causes denture stomatitis.', false, true, 'NEET MDS'),
(59, 'Conservative & Endo', 'G.V. Black Class V cavities involve:', array['Pits and fissures','Proximal surfaces of posterior teeth','Gingival third of facial or lingual surfaces','Incisal angle of anterior teeth']::text[], 2, 'Class V = cervical (gingival third) lesions on facial or lingual surfaces.', true, false, 'NEET MDS'),
(60, 'Conservative & Endo', 'The approximate pH of calcium hydroxide is:', array['7.0','9.0','12.5','14.0']::text[], 2, 'Its high pH (about 12.5) makes it antibacterial and helps stimulate dentine bridge formation.', true, true, 'NEET MDS'),
(61, 'Conservative & Endo', 'The material of choice for repairing root perforations is:', array['Zinc oxide eugenol','Calcium hydroxide','MTA','Gutta-percha']::text[], 2, 'MTA is biocompatible, seals well even when moist, and induces hard-tissue formation. Biodentine is an alternative.', true, true, 'NEET MDS'),
(62, 'Conservative & Endo', 'Ideally, root canal working length should end at:', array['Radiographic apex','Apical constriction (minor diameter)','Major diameter (apical foramen)','2 mm beyond the apex']::text[], 1, 'The apical constriction (CDJ region) is about 0.5–1 mm short of the radiographic apex. It is the narrowest point and the ideal end point.', true, true, 'NEET MDS'),
(63, 'Conservative & Endo', 'Weine''s classification is used to describe:', array['Root canal configurations','Cavity designs','Pulp diseases','Crown fractures']::text[], 0, 'Weine classified canal configurations (Types I–IV). Vertucci''s classification has 8 types.', false, true, 'NEET MDS'),
(64, 'Oral Surgery', 'Le Fort I fracture is also known as:', array['Pyramidal fracture','Craniofacial dysjunction','Guerin''s fracture','Tripod fracture']::text[], 2, 'Le Fort I is a horizontal (Guerin''s) fracture above the apices of the teeth. Le Fort II is pyramidal and Le Fort III is craniofacial dysjunction.', true, true, 'NEET MDS'),
(65, 'Oral Surgery', 'Pell and Gregory classification of impacted mandibular third molars is based on:', array['Angulation only','Relationship to ramus and depth relative to occlusal plane','Root morphology','Relation to the inferior alveolar canal']::text[], 1, 'Class I–III describes the relation to the anterior ramus; position A–C describes depth relative to the occlusal plane. Winter''s classification is based on angulation.', true, true, 'NEET MDS'),
(66, 'Oral Surgery', 'Winter''s WAR lines are used in assessing:', array['TMJ ankylosis','Impacted mandibular third molars','Cleft palate','Orbital fractures']::text[], 1, 'White, Amber and Red lines on a radiograph estimate the depth and difficulty of a third molar impaction.', true, false, 'NEET MDS'),
(67, 'Oral Surgery', 'Dry socket (alveolar osteitis) most commonly follows extraction of:', array['Maxillary incisors','Mandibular third molar','Maxillary first molar','Mandibular premolars']::text[], 1, 'It is most common after mandibular third molar surgery, typically appearing 2–4 days after extraction.', false, true, 'NEET MDS'),
(68, 'Public Health Dentistry', 'The DMF index was introduced by:', array['Dean','Klein, Palmer and Knutson','Russell','Greene and Vermillion']::text[], 1, 'Klein, Palmer and Knutson introduced the DMF index in 1938.', true, true, 'NEET MDS'),
(69, 'Public Health Dentistry', 'Dental fluorosis is classically assessed by:', array['Russell''s index','Dean''s fluorosis index','Ramfjord index','CPITN']::text[], 1, 'Dean''s index (1934, modified 1942) is the classic fluorosis index. TF and TSIF are other indices.', true, true, 'NEET MDS'),
(70, 'Public Health Dentistry', 'The main mechanism by which fluoride prevents caries is:', array['Systemic incorporation before eruption','Topical action that enhances remineralisation','Killing all oral bacteria','Increasing salivary flow']::text[], 1, 'The current concept is that fluoride works mainly topically after eruption: it enhances remineralisation, inhibits demineralisation and affects bacterial enzymes.', false, true, 'NEET MDS'),
(71, 'General Medicine', 'The first-line drug to terminate status epilepticus is:', array['Phenytoin','IV lorazepam','Sodium valproate','Carbamazepine']::text[], 1, 'A benzodiazepine (IV lorazepam, or buccal/IM midazolam) is first-line; phenytoin/fosphenytoin or valproate follow if seizures continue.', false, true, 'NEET MDS'),
(72, 'General Medicine', 'The organism most often responsible for infective endocarditis following dental procedures is:', array['Staphylococcus aureus','Viridans streptococci','Enterococcus faecalis','Candida albicans']::text[], 1, 'Viridans group streptococci from the oral cavity cause most endocarditis linked to dental bacteraemia.', false, true, 'NEET MDS'),
(73, 'General Medicine', 'HbA1c reflects average blood glucose over the previous:', array['1 week','2–3 weeks','2–3 months','1 year']::text[], 2, 'Glycated haemoglobin reflects glycaemia over the red-cell lifespan, roughly 2–3 months.', false, true, 'NEET MDS'),
(74, 'General Medicine', 'Bell''s palsy is a:', array['Upper motor neuron lesion of the facial nerve','Lower motor neuron lesion of the facial nerve','Lesion of the trigeminal nerve','Lesion of the hypoglossal nerve']::text[], 1, 'Bell''s palsy is an idiopathic LMN facial palsy, so the forehead is also paralysed (unlike UMN lesions, which spare it).', false, true, 'NEET MDS'),
(75, 'General Medicine', 'Koilonychia (spoon-shaped nails) is characteristic of:', array['Vitamin B12 deficiency','Iron deficiency anaemia','Thalassaemia','Aplastic anaemia']::text[], 1, 'Koilonychia is a classic sign of chronic iron deficiency.', false, true, 'NEET MDS'),
(76, 'General Medicine', 'The usual target INR for a patient on warfarin for atrial fibrillation is:', array['1.0–1.5','2.0–3.0','3.5–4.5','5.0–6.0']::text[], 1, 'Most indications, including AF and venous thromboembolism, target an INR of 2–3; mechanical valves may need higher.', false, true, 'NEET MDS'),
(77, 'General Medicine', 'An adrenal (Addisonian) crisis in the dental chair is treated with:', array['IV hydrocortisone','IM adrenaline','Oral glucose only','IV atropine']::text[], 0, 'Give IV hydrocortisone (e.g. 100 mg), fluids and urgent transfer; steroid-dependent patients may need cover for stressful procedures.', false, true, 'NEET MDS'),
(78, 'General Medicine', 'The most common cause of community-acquired pneumonia is:', array['Klebsiella pneumoniae','Streptococcus pneumoniae','Pseudomonas aeruginosa','Mycoplasma pneumoniae']::text[], 1, 'Streptococcus pneumoniae (pneumococcus) is the commonest cause.', false, false, 'NEET MDS'),
(79, 'General Surgery', 'In an adult, by the "rule of nines", one entire upper limb represents what percentage of body surface area?', array['4.5%','9%','18%','1%']::text[], 1, 'Each upper limb 9%, each lower limb 18%, head and neck 9%, front and back of trunk 18% each, perineum 1%.', false, true, 'NEET MDS'),
(80, 'General Surgery', 'The lowest possible Glasgow Coma Scale score is:', array['0','1','3','5']::text[], 2, 'GCS ranges from 3 (no eye, verbal or motor response) to 15.', false, true, 'NEET MDS'),
(81, 'General Surgery', 'The most common type of thyroid carcinoma is:', array['Follicular','Papillary','Medullary','Anaplastic']::text[], 1, 'Papillary carcinoma is the commonest and has the best prognosis; it spreads mainly via lymphatics.', false, true, 'NEET MDS'),
(82, 'General Surgery', 'Warthin''s tumour occurs almost exclusively in the:', array['Submandibular gland','Parotid gland','Sublingual gland','Minor salivary glands of the palate']::text[], 1, 'Warthin''s tumour (papillary cystadenoma lymphomatosum) is almost always parotid, commonly in older male smokers, and can be bilateral.', false, true, 'NEET MDS'),
(83, 'General Surgery', 'ATLS class III haemorrhage corresponds to a blood loss of about:', array['Up to 15%','15–30%','30–40%','More than 40%']::text[], 2, 'Class III (30–40%, about 1.5–2 L in an adult) is when hypotension usually appears.', false, true, 'NEET MDS'),
(84, 'General Surgery', 'Virchow''s node is an enlarged lymph node in the:', array['Right supraclavicular fossa','Left supraclavicular fossa','Submandibular region','Axilla']::text[], 1, 'A left supraclavicular node (Troisier''s sign) suggests abdominal malignancy, classically gastric cancer.', false, false, 'NEET MDS'),
(85, 'General Surgery', 'A keloid differs from a hypertrophic scar because a keloid:', array['Stays within the wound margins','Extends beyond the original wound margins','Never recurs after excision','Only occurs in the elderly']::text[], 1, 'Keloids grow beyond the wound margins and often recur after excision; hypertrophic scars stay within the margins and may regress.', false, true, 'NEET MDS'),
(86, 'Pathology', 'Caseous necrosis is characteristic of:', array['Myocardial infarction','Tuberculosis','Acute pancreatitis','Gangrene of the foot']::text[], 1, 'Caseous ("cheese-like") necrosis is typical of tuberculous granulomas.', false, true, 'NEET MDS'),
(87, 'Pathology', 'The Philadelphia chromosome, t(9;22), is characteristic of:', array['Chronic myeloid leukaemia','Acute lymphoblastic leukaemia only','Hodgkin lymphoma','Multiple myeloma']::text[], 0, 'The BCR-ABL fusion from t(9;22) defines CML (it also occurs in a subset of ALL).', false, true, 'NEET MDS'),
(88, 'Pathology', 'The predominant cell in acute inflammation during the first 24 hours is the:', array['Lymphocyte','Neutrophil','Plasma cell','Macrophage']::text[], 1, 'Neutrophils dominate early (6–24 h) and are replaced by monocytes/macrophages after 24–48 hours.', false, true, 'NEET MDS'),
(89, 'Microbiology', 'Germ tube formation in serum within 2–3 hours identifies:', array['Candida albicans','Cryptococcus neoformans','Aspergillus niger','Candida glabrata']::text[], 0, 'A positive germ tube test is a rapid presumptive identification of Candida albicans.', false, true, 'NEET MDS'),
(90, 'Microbiology', 'Endotoxin of Gram-negative bacteria is chemically a:', array['Peptidoglycan','Lipopolysaccharide','Teichoic acid','Mycolic acid']::text[], 1, 'Endotoxin is the lipopolysaccharide (lipid A) of the Gram-negative outer membrane.', false, true, 'NEET MDS'),
(91, 'Microbiology', 'HIV belongs to which family?', array['Herpesviridae','Retroviridae','Picornaviridae','Hepadnaviridae']::text[], 1, 'HIV is a retrovirus (lentivirus) that uses reverse transcriptase to copy its RNA into DNA.', false, true, 'NEET MDS'),
(92, 'Pharmacology', 'Gray baby syndrome is caused by:', array['Tetracycline','Chloramphenicol','Gentamicin','Amoxicillin']::text[], 1, 'Neonates cannot glucuronidate chloramphenicol, leading to circulatory collapse with ashen-grey skin.', false, true, 'NEET MDS'),
(93, 'Pharmacology', 'Alcohol taken with metronidazole can cause:', array['Serotonin syndrome','A disulfiram-like reaction','Malignant hyperthermia','Hypertensive crisis']::text[], 1, 'Metronidazole inhibits aldehyde dehydrogenase, causing flushing, nausea and palpitations with alcohol; advise avoiding alcohol during and 48 hours after the course.', false, true, 'NEET MDS'),
(94, 'Pharmacology', 'Intrinsic tooth discolouration in children is caused by:', array['Amoxicillin','Tetracycline','Metronidazole','Erythromycin']::text[], 1, 'Tetracyclines chelate calcium in developing teeth; avoid in pregnancy and in children under about 8 years.', false, true, 'NEET MDS'),
(95, 'Dental Materials', 'The retarder in alginate impression material is:', array['Calcium sulphate','Trisodium phosphate','Diatomaceous earth','Potassium titanium fluoride']::text[], 1, 'Trisodium phosphate reacts first with calcium sulphate, delaying gel formation (working time).', false, true, 'NEET MDS'),
(96, 'Dental Materials', 'Syneresis of a hydrocolloid impression refers to:', array['Absorption of water','Loss of water by exudation onto the surface','Polymerisation shrinkage','Thermal expansion']::text[], 1, 'Syneresis is exudation of fluid; imbibition is absorption of water. Both distort the impression – pour promptly.', false, true, 'NEET MDS'),
(97, 'Dental Materials', 'Camphorquinone in light-cured composites is a:', array['Filler','Photoinitiator activated by blue light','Inhibitor','Coupling agent']::text[], 1, 'Camphorquinone absorbs blue light (peak around 470 nm) and, with an amine, starts free-radical polymerisation.', false, true, 'NEET MDS'),
(98, 'Periodontics', 'Which organism belongs to Socransky''s red complex?', array['Streptococcus sanguinis','Porphyromonas gingivalis','Actinomyces naeslundii','Veillonella parvula']::text[], 1, 'The red complex is P. gingivalis, Tannerella forsythia and Treponema denticola – strongly associated with deep pockets.', false, true, 'NEET MDS'),
(99, 'Periodontics', 'The usual concentration of chlorhexidine mouthwash is:', array['0.2%','2%','5%','0.002%']::text[], 0, 'Chlorhexidine gluconate mouthwash is used at 0.12–0.2%; 2% is used as an endodontic irrigant.', false, true, 'NEET MDS'),
(100, 'Periodontics', 'The width of attached gingiva is measured from the mucogingival junction to:', array['The gingival margin','The projection of the base of the sulcus or pocket on the external surface','The alveolar crest','The cemento-enamel junction']::text[], 1, 'Attached gingiva = total gingival width (margin to MGJ) minus the sulcus/pocket depth.', false, true, 'NEET MDS'),
(101, 'Biochemistry', 'Scurvy results from impaired hydroxylation of proline and lysine in collagen because of deficiency of:', array['Vitamin A','Vitamin C','Vitamin D','Vitamin K']::text[], 1, 'Ascorbic acid is a cofactor for prolyl and lysyl hydroxylases; deficiency gives weak collagen, bleeding swollen gums and poor healing.', false, true, 'NEET MDS'),
(102, 'Biochemistry', 'Vitamin K is required for the gamma-carboxylation of which clotting factors?', array['I, V, VIII, XIII','II, VII, IX, X','III, IV, XI, XII','VIII and IX only']::text[], 1, 'Factors II, VII, IX and X (and proteins C and S) need vitamin K; warfarin blocks vitamin K epoxide reductase.', false, true, 'NEET MDS'),
(103, 'Biochemistry', 'The rate-limiting enzyme of cholesterol synthesis is:', array['HMG-CoA synthase','HMG-CoA reductase','Acetyl-CoA carboxylase','Lipoprotein lipase']::text[], 1, 'HMG-CoA reductase is the rate-limiting step and the target of statins.', false, true, 'NEET MDS'),
(104, 'Physiology', 'The normal pH of resting whole saliva is approximately:', array['4.5–5.0','6.2–7.4','7.8–8.2','5.5 exactly']::text[], 1, 'Resting saliva is slightly acidic to neutral (about 6.2–7.4); flow stimulation raises bicarbonate and pH.', false, true, 'NEET MDS'),
(105, 'Physiology', 'The critical pH below which enamel demineralises is about:', array['4.5','5.5','6.5','7.0']::text[], 1, 'Hydroxyapatite dissolves below about pH 5.5; fluorapatite resists to about 4.5.', false, true, 'NEET MDS'),
(106, 'Physiology', 'Pain is carried rapidly as "first pain" by which fibres?', array['C fibres','A-delta fibres','A-beta fibres','B fibres']::text[], 1, 'Myelinated A-delta fibres carry sharp, well-localised first pain; unmyelinated C fibres carry dull, burning second pain.', false, true, 'NEET MDS'),
(107, 'Anatomy', 'The only muscle that opens the mouth among the muscles of mastication is the:', array['Masseter','Temporalis','Lateral pterygoid','Medial pterygoid']::text[], 2, 'The lateral pterygoid depresses and protrudes the mandible; the others elevate it.', false, true, 'NEET MDS'),
(108, 'Anatomy', 'The nerve injured most often during surgical removal of a lower third molar, causing loss of taste to the anterior tongue, is the:', array['Inferior alveolar nerve','Lingual nerve','Hypoglossal nerve','Mylohyoid nerve']::text[], 1, 'The lingual nerve carries general sensation and, via chorda tympani fibres, taste from the anterior two-thirds of the tongue.', false, true, 'NEET MDS'),
(109, 'Anatomy', 'The parotid duct opens opposite the:', array['Upper first premolar','Upper second molar','Lower first molar','Lower central incisor']::text[], 1, 'Stensen''s duct pierces the buccinator and opens on a papilla opposite the maxillary second molar crown.', false, true, 'NEET MDS'),
(110, 'Dental Anatomy', 'The permanent tooth that most often has two roots, buccal and palatal, is the:', array['Maxillary second premolar','Maxillary first premolar','Mandibular first premolar','Maxillary canine']::text[], 1, 'The maxillary first premolar is usually bifurcated (buccal and palatal roots).', false, true, 'NEET MDS'),
(111, 'Dental Anatomy', 'The first permanent tooth to erupt in the oral cavity is usually the:', array['Maxillary central incisor','Mandibular first molar','Mandibular central incisor','Maxillary first molar']::text[], 1, 'Mandibular first molars erupt around 6 years, often just before the lower central incisors.', false, true, 'NEET MDS'),
(112, 'Oral Pathology', 'A "soap-bubble" multilocular radiolucency in the posterior mandible of a 35-year-old is most typical of:', array['Radicular cyst','Ameloblastoma','Stafne bone cavity','Periapical granuloma']::text[], 1, 'Conventional ameloblastoma classically shows soap-bubble or honeycomb multilocularity with root resorption.', false, true, 'NEET MDS'),
(113, 'Oral Pathology', 'Hutchinson''s incisors and mulberry molars are features of:', array['Congenital syphilis','Ectodermal dysplasia','Fluorosis','Amelogenesis imperfecta']::text[], 0, 'Congenital syphilis (Treponema pallidum) affects developing incisors (notched, screwdriver-shaped) and first molars (mulberry).', false, true, 'NEET MDS'),
(114, 'Oral Medicine & Radiology', 'The radiographic "sunray" appearance of the jaw is classically associated with:', array['Osteosarcoma','Fibrous dysplasia','Paget''s disease','Cherubism']::text[], 0, 'Osteosarcoma produces sunray (sunburst) spicules and symmetric widening of the PDL space (Garrington sign).', false, true, 'NEET MDS'),
(115, 'Oral Medicine & Radiology', 'In the SLOB rule for tube-shift localisation, an object that moves in the same direction as the X-ray tube lies:', array['Buccally','Lingually (palatally)','In the same plane as the reference','Within the sinus']::text[], 1, 'Same Lingual, Opposite Buccal (Clark''s rule).', false, true, 'NEET MDS'),
(116, 'Oral Medicine & Radiology', 'The thyroid collar is particularly important when taking which radiograph?', array['Panoramic','Maxillary occlusal','Lateral cephalogram','Bitewing']::text[], 1, 'Thyroid shielding is advised for intraoral views, especially maxillary occlusals, where the gland is in the primary beam path; it may interfere with panoramics.', false, true, 'NEET MDS'),
(117, 'Oral Medicine & Radiology', 'Wickham''s striae are characteristic of:', array['Leukoplakia','Lichen planus','Candidiasis','Lupus erythematosus']::text[], 1, 'Fine white lace-like striae on reticular lesions are diagnostic of lichen planus.', false, true, 'NEET MDS'),
(118, 'Orthodontics', 'The Frankfort–mandibular plane angle (FMA) in Tweed''s triangle averages about:', array['15°','25°','35°','45°']::text[], 1, 'Tweed''s norms: FMA 25°, IMPA 90° and FMIA 65°.', false, true, 'NEET MDS'),
(119, 'Orthodontics', 'An ANB angle of 6° indicates a skeletal:', array['Class I relationship','Class II relationship','Class III relationship','Open bite']::text[], 1, 'Normal ANB is about 2° (0–4°); greater than 4° suggests skeletal Class II, negative values suggest Class III.', false, true, 'NEET MDS'),
(120, 'Orthodontics', 'The "leeway space" in the mandible on each side is about:', array['0.9 mm','1.7 mm','3.4 mm','5 mm']::text[], 1, 'Nance: about 1.7 mm per side in the mandible and 0.9 mm in the maxilla.', false, true, 'NEET MDS'),
(121, 'Pedodontics', 'The pulpotomy medicament now preferred over formocresol in primary molars is:', array['Calcium hydroxide','MTA','Zinc oxide eugenol','Glutaraldehyde']::text[], 1, 'MTA (and Biodentine) give the best success rates; formocresol is falling out of use due to toxicity concerns.', false, true, 'NEET MDS'),
(122, 'Pedodontics', 'Frankl''s behaviour rating scale "rating 4" denotes a child who is:', array['Definitely negative','Negative','Positive','Definitely positive']::text[], 3, 'Frankl ratings: 1 definitely negative, 2 negative, 3 positive, 4 definitely positive.', false, true, 'NEET MDS'),
(123, 'Prosthodontics', 'The posterior palatal seal is placed:', array['Along the anterior vibrating line only','Between the anterior and posterior vibrating lines','Over the rugae','Over the incisive papilla']::text[], 1, 'The posterior palatal seal area lies between the anterior and posterior vibrating lines at the junction of the hard and soft palate.', false, true, 'NEET MDS'),
(124, 'Prosthodontics', 'The ideal crown-to-root ratio for a fixed partial denture abutment is:', array['2:1','1:1','2:3','3:1']::text[], 2, 'A 2:3 ratio is ideal; 1:1 is the minimum acceptable (Ante''s law concerns root surface area).', false, true, 'NEET MDS'),
(125, 'Conservative & Endo', 'The most common cause of endodontic failure is:', array['Overfilling','Inadequate cleaning and missed canals/persistent intracanal infection','Use of sodium hypochlorite','Single-visit treatment']::text[], 1, 'Persistent bacteria from inadequate debridement, missed canals or coronal leakage is the main cause; Enterococcus faecalis is often found in failed cases.', false, true, 'NEET MDS'),
(126, 'Conservative & Endo', 'Ferrule effect requires a minimum vertical height of sound tooth structure of about:', array['0.5 mm','1.5–2 mm','4 mm','6 mm']::text[], 1, 'A 1.5–2 mm ferrule above the finish line greatly improves fracture resistance of post-core-crown teeth.', false, true, 'NEET MDS'),
(127, 'Oral Surgery', 'The maximum recommended dose of lignocaine with adrenaline is:', array['3 mg/kg','4.4 mg/kg','7 mg/kg','10 mg/kg']::text[], 2, 'Lignocaine alone about 4.4 mg/kg (max 300 mg); with adrenaline about 7 mg/kg (max 500 mg).', false, true, 'NEET MDS'),
(128, 'Oral Surgery', 'Winter''s lines are used to assess:', array['Mandibular fractures','The difficulty of impacted mandibular third molars','Maxillary sinus size','TMJ dislocation']::text[], 1, 'The white, amber and red lines on radiographs estimate depth and bone removal for impacted lower third molars.', false, true, 'NEET MDS'),
(129, 'Public Health Dentistry', 'The optimum fluoride concentration in drinking water in a tropical country such as India is about:', array['0.1 ppm','0.5–0.8 ppm','1.5–2 ppm','4 ppm']::text[], 1, 'In hot climates people drink more water, so lower levels (about 0.5–0.8 ppm, BIS limit ≤ 1 ppm) are optimal.', false, true, 'NEET MDS'),
(130, 'Public Health Dentistry', 'A study that follows exposed and unexposed groups forward in time to compare incidence is a:', array['Case-control study','Cohort study','Cross-sectional survey','Ecological study']::text[], 1, 'Cohort studies measure incidence and relative risk; case-control studies start from disease and estimate odds ratios.', false, true, 'NEET MDS'),
(131, 'Dental Anatomy', 'Enamel spindles are formed by:', array['Ameloblast processes','Odontoblast processes crossing the DEJ','Hypomineralised rod sheaths','Cracks filled with organic material']::text[], 1, 'Spindles are odontoblastic processes trapped in enamel before it mineralised.', false, true, 'NEET MDS'),
(132, 'Dental Anatomy', 'Perikymata are the surface manifestations of:', array['Hunter–Schreger bands','Striae of Retzius','Enamel lamellae','Cross-striations']::text[], 1, 'Striae of Retzius reach the enamel surface as shallow grooves called perikymata.', false, true, 'NEET MDS'),
(133, 'Dental Anatomy', 'Tomes'' granular layer is found in:', array['Coronal dentine beneath enamel','Root dentine beneath cementum','Pulp horns','Enamel near the DEJ']::text[], 1, 'It is a granular, hypomineralised zone in root dentine adjacent to cementum.', false, true, 'NEET MDS'),
(134, 'Dental Anatomy', 'The epithelial rests of Malassez are derived from:', array['Dental lamina','Hertwig''s epithelial root sheath','Reduced enamel epithelium','Stellate reticulum']::text[], 1, 'HERS fragments after root formation and persists in the PDL as the rests of Malassez – the source of radicular cysts.', false, true, 'NEET MDS'),
(135, 'Dental Anatomy', 'The most numerous principal fibres of the periodontal ligament are the:', array['Horizontal','Oblique','Apical','Alveolar crest']::text[], 1, 'Oblique fibres resist vertical masticatory forces.', false, true, 'NEET MDS'),
(136, 'Dental Anatomy', 'Cellular cementum is found mainly in the:', array['Cervical third of the root','Apical third and furcation areas','Crown','Middle third only']::text[], 1, 'Acellular (primary) cementum covers the cervical root; cellular (secondary) cementum is thicker apically and at furcations.', false, true, 'NEET MDS'),
(137, 'Anatomy', 'The facial nerve leaves the skull through the:', array['Foramen ovale','Stylomastoid foramen','Jugular foramen','Foramen rotundum']::text[], 1, 'After the facial canal it exits via the stylomastoid foramen and enters the parotid gland.', false, true, 'NEET MDS'),
(138, 'Anatomy', 'The mandibular nerve leaves the skull through the:', array['Foramen rotundum','Foramen ovale','Foramen spinosum','Superior orbital fissure']::text[], 1, 'V3 passes through foramen ovale; V2 through foramen rotundum; V1 through the superior orbital fissure.', false, true, 'NEET MDS'),
(139, 'Anatomy', 'Motor supply to the tongue muscles (except palatoglossus) is from the:', array['Glossopharyngeal nerve','Hypoglossal nerve','Lingual nerve','Vagus nerve']::text[], 1, 'Hypoglossal (XII) supplies all intrinsic and extrinsic tongue muscles except palatoglossus (vagus via pharyngeal plexus).', false, true, 'NEET MDS'),
(140, 'Anatomy', 'The first pharyngeal (branchial) arch gives rise to the:', array['Muscles of facial expression','Muscles of mastication','Stylopharyngeus','Laryngeal muscles']::text[], 1, 'First arch: mastication muscles, mylohyoid, anterior digastric, tensor tympani and veli palatini, Meckel''s cartilage; nerve V3. Second arch: facial expression, nerve VII.', false, true, 'NEET MDS'),
(141, 'Physiology', 'Haemophilia A is due to deficiency of factor:', array['VII','VIII','IX','XI']::text[], 1, 'Haemophilia A – factor VIII; haemophilia B (Christmas disease) – factor IX; both X-linked recessive.', false, true, 'NEET MDS'),
(142, 'Physiology', 'The prothrombin time (PT) mainly tests the:', array['Intrinsic pathway','Extrinsic and common pathways','Platelet function','Fibrinolysis']::text[], 1, 'PT/INR tests factors VII, X, V, II and fibrinogen; it is used to monitor warfarin.', false, true, 'NEET MDS'),
(143, 'Physiology', 'Parathyroid hormone raises serum calcium by all of the following EXCEPT:', array['Increasing bone resorption','Increasing renal calcium reabsorption','Stimulating renal 1-α-hydroxylase','Increasing renal phosphate reabsorption']::text[], 3, 'PTH increases phosphate excretion (phosphaturic) while retaining calcium.', false, true, 'NEET MDS'),
(144, 'Physiology', 'The main salivary gland producing resting (unstimulated) saliva is the:', array['Parotid','Submandibular','Sublingual','Minor glands']::text[], 1, 'Submandibular glands give about 65–70% of resting saliva; the parotid dominates stimulated flow.', false, true, 'NEET MDS'),
(145, 'Biochemistry', 'The main organic component of dentine is:', array['Type II collagen','Type I collagen','Amelogenin','Keratin']::text[], 1, 'Dentine organic matrix is about 90% type I collagen; amelogenin is an enamel protein.', false, true, 'NEET MDS'),
(146, 'Biochemistry', 'Fluoride inhibits which glycolytic enzyme in oral bacteria?', array['Hexokinase','Enolase','Pyruvate kinase','Aldolase']::text[], 1, 'Fluoride inhibits enolase, reducing bacterial acid production; it is also why fluoride tubes are used for blood glucose samples.', false, true, 'NEET MDS'),
(147, 'Dental Materials', 'Type IV gypsum (die stone) differs from type III mainly by having:', array['A higher water/powder ratio','Higher strength and lower setting expansion','β-hemihydrate particles','Greater porosity']::text[], 1, 'Die stone has the lowest W/P ratio (about 0.22–0.24), highest strength and low expansion.', false, true, 'NEET MDS'),
(148, 'Dental Materials', 'Setting of addition silicone impression material is inhibited by:', array['Water','Sulphur compounds in latex gloves','Alcohol','Zinc oxide']::text[], 1, 'Sulphur poisons the platinum (chloroplatinic acid) catalyst.', false, true, 'NEET MDS'),
(149, 'Dental Materials', 'The most hydrophilic elastomeric impression material is:', array['Polysulphide','Polyether','Condensation silicone','Addition silicone without surfactant']::text[], 1, 'Polyether is inherently hydrophilic; it also absorbs water, so it should not be stored wet.', false, true, 'NEET MDS'),
(150, 'Dental Materials', 'The C-factor of a Class I cavity is:', array['1','2','3','5']::text[], 3, 'Five bonded walls to one unbonded surface gives C = 5 – the highest shrinkage stress.', false, true, 'NEET MDS'),
(151, 'Dental Materials', 'Transformation toughening is a strengthening mechanism of:', array['Feldspathic porcelain','Zirconia','Lithium disilicate','Leucite glass-ceramic']::text[], 1, 'Stress at a crack tip changes tetragonal zirconia to monoclinic with volume expansion, closing the crack.', false, true, 'NEET MDS'),
(152, 'Dental Materials', 'Silica-based ceramics are etched before bonding with:', array['37% phosphoric acid','Hydrofluoric acid','Polyacrylic acid','EDTA']::text[], 1, 'HF (about 5–9.5%) creates micro-retention; silane then bonds resin to the ceramic.', false, true, 'NEET MDS'),
(153, 'Conservative & Endo', 'The bacterium most often isolated from failed, root-filled teeth is:', array['Streptococcus mutans','Enterococcus faecalis','Porphyromonas gingivalis','Lactobacillus casei']::text[], 1, 'E. faecalis survives high pH and starvation, resisting calcium hydroxide.', false, true, 'NEET MDS'),
(154, 'Conservative & Endo', 'The working length is ideally established at:', array['The radiographic apex','The apical constriction (minor diameter)','3 mm short of the apex','The CEJ']::text[], 1, 'The minor diameter, about 0.5–1 mm from the radiographic apex, is the ideal end point – confirmed by apex locator and radiograph.', false, true, 'NEET MDS'),
(155, 'Oral Surgery', 'Transient facial palsy after an inferior alveolar nerve block is due to:', array['Needle trauma to the lingual nerve','Anaesthetic deposited into the parotid capsule','Intravascular injection','Allergy to the anaesthetic']::text[], 1, 'Injecting too far posteriorly into the parotid anaesthetises facial nerve branches; reassure and protect the eye.', false, true, 'NEET MDS'),
(156, 'Oral Surgery', 'The tranexamic acid mouthwash used after extractions in haemophilia acts by:', array['Activating platelets','Inhibiting fibrinolysis','Replacing factor VIII','Constricting vessels']::text[], 1, 'Tranexamic acid blocks plasminogen activation, protecting the clot from salivary fibrinolysis.', false, true, 'NEET MDS'),
(157, 'Oral Medicine & Radiology', 'Recurrent aphthous ulcers characteristically occur on:', array['Hard palate and attached gingiva','Non-keratinised mucosa such as labial and buccal mucosa','Dorsum of tongue only','Vermilion border']::text[], 1, 'Aphthae favour non-keratinised mucosa; recurrent intraoral herpes favours keratinised mucosa.', false, true, 'NEET MDS'),
(158, 'Periodontics', 'Socransky''s fusospirochaetal complex is classically linked to:', array['Chronic gingivitis','Necrotising ulcerative gingivitis','Gingival enlargement','Desquamative gingivitis']::text[], 1, 'Fusobacterium and spirochaetes (Treponema) with Prevotella intermedia are associated with NUG.', false, true, 'NEET MDS'),
(159, 'Pedodontics', 'Fissure types most prone to caries (Nagano classification) are:', array['V and U','I and IK','U only','V only']::text[], 1, 'Narrow, deep I and IK fissures trap plaque and are hardest to clean.', false, true, 'NEET MDS'),
(160, 'General Medicine', 'In a patient with a prosthetic heart valve, the AHA-recommended adult oral prophylaxis before tooth extraction is:', array['Amoxicillin 500 mg','Amoxicillin 2 g 30–60 min before','Metronidazole 400 mg','Clindamycin 600 mg (first choice)']::text[], 1, 'Amoxicillin 2 g orally 30–60 minutes before; azithromycin/clarithromycin 500 mg or doxycycline 100 mg if penicillin-allergic.', false, true, 'NEET MDS'),
(161, 'Orthodontics', 'Cephalometrics was introduced in 1931 by:', array['Angle and Tweed','Broadbent and Hofrath','Downs and Steiner','Ricketts and McNamara']::text[], 1, 'Broadbent (USA) and Hofrath (Germany) independently introduced standardised cephalometry in 1931.', false, true, 'NEET MDS'),
(162, 'Orthodontics', 'The first cephalometric analysis described was by:', array['Steiner','Downs','Tweed','Ricketts']::text[], 1, 'Downs (1948) analysis was the first; Steiner (1953) is the most widely used.', false, true, 'NEET MDS'),
(163, 'Orthodontics', 'Hyalinisation during orthodontic tooth movement results from:', array['Light continuous forces','Heavy forces that occlude PDL blood vessels','Intermittent forces only','Tension on the PDL']::text[], 1, 'Heavy forces cause local ischaemia and a cell-free hyalinised zone; movement resumes after undermining resorption.', false, true, 'NEET MDS'),
(164, 'Orthodontics', 'The orthodontic movement requiring the lightest force is:', array['Tipping','Bodily movement','Intrusion','Root uprighting']::text[], 2, 'Intrusion concentrates force at the apex, so about 10–20 g is used.', false, true, 'NEET MDS'),
(165, 'Oral Pathology', 'Gustafson''s method is used for:', array['Sex determination','Age estimation in adults','Bite-mark analysis','Lip-print analysis']::text[], 1, 'Gustafson (1950) used six regressive changes in teeth (attrition, periodontosis, secondary dentine, cementum apposition, root resorption, root transparency).', false, true, 'NEET MDS'),
(166, 'Oral Pathology', 'The study of palatal rugae for identification is called:', array['Cheiloscopy','Rugoscopy','Odontometry','Dactyloscopy']::text[], 1, 'Rugoscopy (palatoscopy) uses rugae patterns; cheiloscopy uses lip prints; dactyloscopy uses fingerprints.', false, true, 'NEET MDS'),
(167, 'Oral Pathology', 'Fusion of two teeth by cementum alone is:', array['Gemination','Fusion','Concrescence','Twinning']::text[], 2, 'Concrescence occurs after root formation; it is common between maxillary second and third molars.', false, true, 'NEET MDS'),
(168, 'Oral Pathology', 'Opalescent teeth with bulbous crowns and obliterated pulp chambers are typical of:', array['Amelogenesis imperfecta','Dentinogenesis imperfecta','Regional odontodysplasia','Fluorosis']::text[], 1, 'Dentinogenesis imperfecta: amber-grey opalescent teeth, cervical constriction, pulp obliteration; type I occurs with osteogenesis imperfecta.', false, true, 'NEET MDS'),
(169, 'Oral Pathology', '"Ghost teeth" on radiographs are seen in:', array['Dentin dysplasia type I','Regional odontodysplasia','Taurodontism','Hypophosphatasia']::text[], 1, 'Regional odontodysplasia shows thin, poorly mineralised enamel and dentine with wide pulps, usually in one quadrant.', false, true, 'NEET MDS'),
(170, 'Oral Pathology', 'Chronic hyperplastic candidiasis (candidal leukoplakia) is important because it:', array['Always wipes off','Is potentially malignant','Only affects infants','Is caused by Staphylococcus']::text[], 1, 'It presents as a white patch that does not rub off, commonly at the commissures, and carries a risk of malignant change.', false, true, 'NEET MDS'),
(171, 'Oral Medicine & Radiology', 'Newton''s type III denture stomatitis is:', array['Pinpoint hyperaemia','Diffuse erythema','Papillary hyperplasia','Ulceration']::text[], 2, 'Type I – localised pinpoint hyperaemia; II – diffuse erythema of the denture-bearing area; III – granular/papillary hyperplasia.', false, true, 'NEET MDS'),
(172, 'Oral Medicine & Radiology', 'The salivary gland most often affected by sialoliths is the:', array['Parotid','Submandibular','Sublingual','Minor salivary glands']::text[], 1, 'About 80–90% occur in the submandibular gland: alkaline, mucous, calcium-rich saliva and a long uphill duct.', false, true, 'NEET MDS'),
(173, 'Oral Medicine & Radiology', 'Antibodies characteristic of Sjögren''s syndrome are:', array['Anti-dsDNA','Anti-Ro (SSA) and anti-La (SSB)','Anti-centromere','ANCA']::text[], 1, 'Anti-Ro and anti-La; labial gland biopsy shows focal lymphocytic sialadenitis.', false, true, 'NEET MDS'),
(174, 'Oral Medicine & Radiology', 'Stochastic effects of radiation:', array['Have a threshold dose','Increase in severity with dose','Have no threshold; probability increases with dose','Occur only above 2 Gy']::text[], 2, 'Cancer and genetic effects are stochastic; erythema and cataract are deterministic (threshold).', false, true, 'NEET MDS'),
(175, 'Oral Medicine & Radiology', 'The operator should stand during intraoral exposure at least:', array['0.5 m from the patient','2 m away at 90–135° to the beam','Directly behind the tube head','Holding the film for the patient']::text[], 1, 'Distance (inverse square law) and position out of the primary beam, or behind a barrier.', false, true, 'NEET MDS'),
(176, 'Conservative & Endo', 'G.V. Black Class V cavities involve:', array['Pits and fissures','Gingival third of facial or lingual surfaces','Proximal surfaces of posterior teeth','Incisal edges']::text[], 1, 'Class V: cervical third of facial or lingual surfaces of any tooth.', false, true, 'NEET MDS'),
(177, 'Conservative & Endo', 'The cavosurface margin for an amalgam preparation should be:', array['45° bevel','90° butt joint','30° bevel','Feather edge']::text[], 1, 'Amalgam has low edge strength, so a 90° margin avoids thin, fragile edges.', false, true, 'NEET MDS'),
(178, 'Periodontics', 'Glickman grade IV furcation involvement means:', array['Incipient involvement','Cul-de-sac defect','Through-and-through, covered by gingiva','Through-and-through and clinically visible']::text[], 3, 'Grade III is through-and-through covered by soft tissue; grade IV is exposed and visible.', false, true, 'NEET MDS'),
(179, 'Periodontics', 'Cervical enamel projections were classified by:', array['Glickman','Masters and Hoskins','Hamp','Miller']::text[], 1, 'Masters and Hoskins (1964) graded CEPs I–III; they predispose to furcation involvement.', false, true, 'NEET MDS'),
(180, 'Periodontics', 'The modified Widman flap was described by:', array['Ramfjord and Nissle','Nabers','Friedman','Kirkland']::text[], 0, 'Ramfjord and Nissle (1974); it uses an internal bevel incision and aims for close adaptation with minimal recession.', false, true, 'NEET MDS'),
(181, 'Periodontics', 'Root resection of a mandibular molar dividing it into two halves, retaining one or both, is called:', array['Root amputation','Hemisection','Tunnelling','Odontoplasty']::text[], 1, 'Hemisection splits a lower molar buccolingually; "bicuspidisation" retains both halves.', false, true, 'NEET MDS'),
(182, 'Oral Surgery', 'The forceps beak acts mainly as a:', array['Lever','Wedge','Wheel and axle','Pulley']::text[], 1, 'Beaks are driven apically into the PDL space as wedges, expanding the socket; elevators act as levers or wheel-and-axle.', false, true, 'NEET MDS'),
(183, 'Oral Surgery', 'Rotational movement during extraction is suitable for the:', array['Maxillary first premolar','Maxillary central incisor','Mandibular first molar','Maxillary first molar']::text[], 1, 'Conical single roots (upper central incisor, lower premolars) tolerate rotation; the bifurcated upper first premolar does not.', false, true, 'NEET MDS'),
(184, 'General Medicine', 'Koilonychia, glossitis and dysphagia due to an oesophageal web form:', array['Peutz–Jeghers syndrome','Plummer–Vinson syndrome','Melkersson–Rosenthal syndrome','Sjögren''s syndrome']::text[], 1, 'Plummer–Vinson (Paterson–Kelly) syndrome with iron deficiency; it is potentially malignant.', false, true, 'NEET MDS'),
(185, 'General Medicine', 'Megaloblastic anaemia with neuropathy and a beefy red tongue suggests deficiency of:', array['Iron','Vitamin B12','Vitamin C','Vitamin K']::text[], 1, 'B12 deficiency (e.g. pernicious anaemia) causes Hunter''s glossitis and neurological signs; folate deficiency lacks neuropathy.', false, true, 'NEET MDS'),
(186, 'General Medicine', 'A "hair-on-end" appearance of the skull is seen in:', array['Paget''s disease','Thalassaemia major','Hyperparathyroidism','Multiple myeloma']::text[], 1, 'Marrow hyperplasia in thalassaemia (and sickle cell) produces vertical trabeculae; myeloma gives "punched-out" lesions.', false, true, 'NEET MDS'),
(187, 'Pharmacology', 'Miconazole oral gel should be avoided in patients taking:', array['Metformin','Warfarin','Amoxicillin','Paracetamol']::text[], 1, 'Azoles inhibit CYP2C9 and raise warfarin levels – risk of serious bleeding.', false, true, 'NEET MDS'),
(188, 'Pharmacology', 'Pilocarpine is used for xerostomia because it is a:', array['Muscarinic agonist','Muscarinic antagonist','Beta blocker','Antihistamine']::text[], 0, 'Pilocarpine stimulates M3 receptors on residual salivary gland tissue; side effects include sweating and flushing.', false, true, 'NEET MDS'),
(189, 'Public Health Dentistry', 'The ICRP annual occupational effective dose limit is:', array['1 mSv','5 mSv','20 mSv (averaged over 5 years)','100 mSv']::text[], 2, 'Occupational limit 20 mSv/year averaged over 5 years (no more than 50 mSv in one year); public limit 1 mSv/year.', false, true, 'NEET MDS'),
(190, 'Dental Anatomy', 'The tooth most commonly showing dens invaginatus is the:', array['Mandibular central incisor','Maxillary lateral incisor','Maxillary canine','Mandibular second premolar']::text[], 1, 'Upper laterals are most often affected; the palatal pit should be sealed to prevent early pulp necrosis.', false, true, 'NEET MDS'),
(191, 'Prosthodontics', 'Hanau''s formula for lateral condylar guidance is:', array['L = H/8 + 12','L = H/12 + 8','L = 2H + 8','L = H/4 + 10']::text[], 0, 'L = H/8 + 12, where H is the horizontal condylar guidance from the protrusive record.', false, true, 'NEET MDS'),
(192, 'Prosthodontics', 'In an arcon articulator the condylar elements are attached to the:', array['Upper member','Lower member','Incisal pin','Face-bow']::text[], 1, 'ARcon = ARticulator + CONdyle; condyles on the lower member as in the skull (e.g. Whip-Mix). Hanau H2 is non-arcon.', false, true, 'NEET MDS'),
(193, 'Prosthodontics', 'Clicking of teeth during speech with new complete dentures suggests:', array['Reduced vertical dimension','Increased vertical dimension of occlusion','Underextended flanges','Insufficient post-dam']::text[], 1, 'Excess VDO removes the freeway space, so teeth contact during speech.', false, true, 'NEET MDS'),
(194, 'Prosthodontics', 'Ante''s law relates to:', array['Crown–root ratio','Root surface area of abutments versus teeth replaced','Span length and deflection','Pontic design']::text[], 1, 'Abutment root surface area should be equal to or greater than that of the teeth being replaced.', false, true, 'NEET MDS'),
(195, 'Prosthodontics', 'If the span of a pontic is doubled, its deflection increases:', array['2 times','4 times','8 times','16 times']::text[], 2, 'Deflection varies with the cube of the span length.', false, true, 'NEET MDS'),
(196, 'Prosthodontics', 'The preferred teeth for overdenture abutments are the:', array['Incisors','Canines','Second molars','Third molars']::text[], 1, 'Canines have long roots and strategic positions; premolars are next choice.', false, true, 'NEET MDS'),
(197, 'Prosthodontics', 'Racemic epinephrine retraction cord is contraindicated in a patient with:', array['Diabetes','Hyperthyroidism or cardiovascular disease','Asthma','Anaemia']::text[], 1, 'Systemic absorption of adrenaline from the sulcus can cause tachycardia and hypertension.', false, true, 'NEET MDS'),
(198, 'General Surgery', 'According to the Parkland formula, a 50 kg patient with 30% burns needs in the first 24 hours:', array['3 L','6 L','9 L','12 L']::text[], 1, '4 × 50 × 30 = 6000 mL; half (3 L) in the first 8 hours from the time of the burn.', false, true, 'NEET MDS'),
(199, 'General Surgery', 'A burn that is white, leathery and painless is:', array['Superficial','Superficial partial thickness','Full thickness','Epidermal']::text[], 2, 'Full-thickness burns destroy nerve endings, so they are painless; they need excision and grafting.', false, true, 'NEET MDS'),
(200, 'General Surgery', 'Tracheostomy is usually performed through the:', array['First tracheal ring','Second to fourth tracheal rings','Cricothyroid membrane','Thyrohyoid membrane']::text[], 1, 'Cutting the first ring risks subglottic stenosis; the cricothyroid membrane is used for cricothyroidotomy.', false, true, 'NEET MDS'),
(201, 'General Surgery', 'Supraomohyoid neck dissection removes lymph node levels:', array['I–III','II–IV','I–V','VI only']::text[], 0, 'Selective dissection of levels I–III for oral cavity cancer with a clinically N0 neck.', false, true, 'NEET MDS'),
(202, 'General Surgery', 'A chylous fistula after neck dissection is most likely on the:', array['Right side','Left side','Both sides equally','Midline only']::text[], 1, 'The thoracic duct enters the venous system at the left jugulosubclavian junction.', false, true, 'NEET MDS'),
(203, 'General Surgery', 'Radical neck dissection sacrifices all of the following EXCEPT:', array['Spinal accessory nerve','Internal jugular vein','Sternocleidomastoid','Vagus nerve']::text[], 3, 'The vagus, hypoglossal and phrenic nerves and carotid arteries are preserved.', false, true, 'NEET MDS'),
(204, 'Pedodontics', 'In early childhood caries, the teeth usually spared are the:', array['Maxillary incisors','Maxillary first molars','Mandibular incisors','Maxillary canines']::text[], 2, 'The tongue covers the lower incisors during sucking and saliva from nearby ducts protects them.', false, true, 'NEET MDS'),
(205, 'Pedodontics', 'Fluoride toothpaste amount recommended for a child under 3 years:', array['Pea-sized','Smear (rice-grain size)','Full brush length','None']::text[], 1, 'A smear under 3 years and a pea-sized amount from 3 to 6 years.', false, true, 'NEET MDS'),
(206, 'Pedodontics', 'Stainless steel crowns for primary molars were introduced by:', array['Hall','Humphrey','Black','Frankl']::text[], 1, 'Humphrey (1950); the Hall technique (Norna Hall) is a later no-preparation method.', false, true, 'NEET MDS'),
(207, 'Pedodontics', 'The luting cement of choice for stainless steel crowns is:', array['Zinc phosphate','Glass ionomer cement','Zinc oxide eugenol','Calcium hydroxide']::text[], 1, 'GIC bonds chemically, releases fluoride and is easy to clean up.', false, true, 'NEET MDS'),
(208, 'Pedodontics', 'Silver diamine fluoride is used in children mainly to:', array['Whiten teeth','Arrest carious lesions','Desensitise erupting teeth','Seal fissures']::text[], 1, '38% SDF arrests cavitated caries but stains the lesion black.', false, true, 'NEET MDS'),
(209, 'Conservative & Endo', 'Lingering pain to cold for more than 30 seconds indicates:', array['Normal pulp','Reversible pulpitis','Irreversible pulpitis','Pulp necrosis']::text[], 2, 'Reversible pulpitis pain stops within seconds of removing the stimulus.', false, true, 'NEET MDS'),
(210, 'Conservative & Endo', 'The most reliable test of pulp sensibility in routine practice is:', array['Heat test with gutta-percha','Cold test (refrigerant spray)','Test cavity','Transillumination']::text[], 1, 'Cold testing (e.g. tetrafluoroethane) is most reliable; the test cavity is a last resort.', false, true, 'NEET MDS'),
(211, 'Conservative & Endo', 'Chronic hyperplastic pulpitis (pulp polyp) occurs typically in:', array['Elderly patients with narrow canals','Young patients with large open carious cavities','Teeth with full crowns','Non-vital teeth']::text[], 1, 'A well-vascularised young pulp proliferates through a large open cavity.', false, true, 'NEET MDS'),
(212, 'Conservative & Endo', 'A diffuse periapical radiopacity at the apex of a carious tooth is:', array['Condensing osteitis','Periapical granuloma','Periapical cyst','Cementoblastoma']::text[], 0, 'Condensing osteitis is a bony reaction to low-grade, long-standing pulpal inflammation.', false, true, 'NEET MDS'),
(213, 'Oral Pathology', 'Wedge-shaped cervical lesions attributed to occlusal flexural stress are called:', array['Abrasion','Erosion','Abfraction','Attrition']::text[], 2, 'Grippo coined abfraction; lesions are often sharp and may be subgingival.', false, true, 'NEET MDS'),
(214, 'Oral Pathology', 'Erosion from gastro-oesophageal reflux typically affects the:', array['Labial surfaces of lower incisors','Palatal surfaces of maxillary anterior teeth','Buccal surfaces of molars','Occlusal surfaces only']::text[], 1, 'Intrinsic acid bathes the palatal surfaces; extrinsic dietary acid tends to affect labial surfaces.', false, true, 'NEET MDS'),
(215, 'Oral Pathology', '"Pink tooth of Mummery" is seen in:', array['External resorption','Internal resorption','Pulp necrosis','Fluorosis']::text[], 1, 'Internal resorption enlarges the pulp chamber so vascular pulp shows through the thinned crown.', false, true, 'NEET MDS'),
(216, 'Anatomy', 'The thoracic duct drains into the:', array['Right lymphatic duct','Left jugulosubclavian venous junction','Superior vena cava directly','Azygos vein']::text[], 1, 'This is why chyle leaks are a risk in left-sided neck dissection.', false, false, 'NEET MDS'),
(217, 'Dental Materials', 'Ferric sulphate is used in dentistry as a:', array['Impression material','Haemostatic agent','Luting cement','Bleaching agent']::text[], 1, 'It is used for gingival retraction and in primary molar pulpotomy; it stains tissue.', false, true, 'NEET MDS'),
(218, 'Oral Surgery', 'The emergency surgical airway in a "can''t intubate, can''t oxygenate" situation is:', array['Tracheostomy through the isthmus','Cricothyroidotomy','Nasal intubation','Laryngeal mask only']::text[], 1, 'Cricothyroidotomy is quick and has few major vessels in its path.', false, true, 'NEET MDS'),
(219, 'Orthodontics', 'Tongue thrusting is most commonly associated with:', array['Deep bite','Anterior open bite','Class III with crossbite only','Crowding of lower incisors']::text[], 1, 'The tongue sits between the incisors at rest or during swallowing.', false, false, 'NEET MDS'),
(220, 'Periodontics', 'The gingival col is absent when:', array['Teeth are in contact','There is a diastema (no contact point)','The patient is young','The gingiva is inflamed']::text[], 1, 'The col is the concave area under the contact point; with a diastema the gingiva is keratinised and flat.', false, false, 'NEET MDS'),
(1001, 'Medical emergencies', 'A 45-year-old (70 kg) develops widespread urticaria, wheeze and a falling blood pressure two minutes after a rubber-dam is placed. What is the first drug to give?', array['Hydrocortisone 200 mg IV','Adrenaline 0.5 mg (0.5 mL of 1:1000) IM into the anterolateral thigh','Promethazine 25 mg orally','Salbutamol 4 puffs via spacer only']::text[], 1, 'Anaphylaxis (likely latex): adrenaline IM 0.01 mg/kg, max 0.5 mg, into the anterolateral thigh, repeated every 5 minutes if needed. Call an ambulance and lie the patient flat. Antihistamines and steroids are not first-line.', false, true, 'ADC'),
(1002, 'Medical emergencies', 'A patient with known angina develops central chest pain while you are preparing a crown. He is alert and his blood pressure is normal. What do you give first?', array['Aspirin 300 mg and wait 15 minutes','Glyceryl trinitrate 400 microgram spray under the tongue','Adrenaline 0.5 mg IM','Midazolam buccal']::text[], 1, 'Stop treatment, sit the patient up and give sublingual GTN. If pain persists after the first dose, call an ambulance; aspirin 300 mg is given for suspected acute coronary syndrome if not contraindicated.', false, true, 'ADC'),
(1003, 'Medical emergencies', 'A patient with type 1 diabetes skipped lunch and becomes sweaty, shaky and confused but can still swallow. What is the most appropriate management?', array['Glucagon 1 mg IM immediately','15–20 g of fast-acting oral glucose, then recheck','Insulin from the patient''s pen','Lie flat and give oxygen only']::text[], 1, 'Conscious hypoglycaemia: oral fast-acting glucose (e.g. glucose tablets, juice), recheck after 10–15 minutes, then a longer-acting carbohydrate. Glucagon IM is for a patient who cannot swallow safely.', false, true, 'ADC'),
(1004, 'Medical emergencies', 'A young patient faints in the chair before an injection. Pulse is slow but present and breathing is normal. What is the first step?', array['Sit the patient upright','Lay the patient flat and raise the legs','Give adrenaline IM','Start CPR']::text[], 1, 'Vasovagal syncope: lay flat, raise the legs to improve venous return, loosen tight clothing and give oxygen. Recovery is usually rapid; if not, reassess for other causes.', false, false, 'ADC'),
(1005, 'Therapeutics', 'A patient taking warfarin (INR 2.4 measured yesterday) needs a simple extraction of a lower first molar. What is the best approach?', array['Stop warfarin for 5 days before the extraction','Proceed without stopping warfarin, using local haemostatic measures','Switch to aspirin for a week','Refer to hospital for vitamin K']::text[], 1, 'For simple extractions with a stable INR in the therapeutic range (generally ≤ 3), continue warfarin and use local measures: atraumatic technique, haemostatic dressing, sutures and tranexamic acid mouthwash. Stopping warfarin risks thromboembolism.', false, true, 'ADC'),
(1006, 'Therapeutics', 'Which patient needs antibiotic prophylaxis against infective endocarditis before a dental extraction?', array['Mitral valve prolapse without regurgitation','A patient with a prosthetic heart valve','Controlled hypertension','A coronary stent placed 2 years ago']::text[], 1, 'Prophylaxis is limited to highest-risk cardiac conditions, such as prosthetic valves, previous infective endocarditis, some congenital heart disease and rheumatic heart disease in Aboriginal and Torres Strait Islander patients. Stents, hypertension and MVP alone do not qualify.', false, true, 'ADC'),
(1007, 'Therapeutics', 'Following an endocarditis-risk assessment, which oral regimen is standard prophylaxis for an adult with no penicillin allergy?', array['Amoxicillin 2 g orally, 60 minutes before the procedure','Amoxicillin 500 mg three times daily for 5 days after','Metronidazole 400 mg 1 hour before','Doxycycline 100 mg the night before']::text[], 0, 'A single 2 g oral dose of amoxicillin about an hour before the procedure. Antibiotics are not continued afterwards for prophylaxis.', false, false, 'ADC'),
(1008, 'Therapeutics', 'A 68-year-old receiving IV zoledronic acid for metastatic breast cancer needs a lower molar removed. What is the best approach?', array['Extract and prescribe antibiotics for a week','Avoid extraction where possible; consider root canal treatment and crown removal (decoronation) with specialist advice','Stop zoledronic acid for one week and extract','There is no added risk; extract routinely']::text[], 1, 'High-dose IV antiresorptives for cancer carry the highest risk of medication-related osteonecrosis of the jaw. Prefer non-surgical options and seek specialist advice. A short drug holiday does not remove the risk from bisphosphonates.', false, false, 'ADC'),
(1009, 'Ethics & law', 'A dentist forms a reasonable belief that a colleague has repeatedly treated patients while intoxicated with alcohol. What must the dentist do?', array['Speak to the colleague privately and take no further action','Make a mandatory notification to AHPRA','Report only if a patient complains','Tell the practice owner and let them decide']::text[], 1, 'Practising while intoxicated by alcohol or drugs is notifiable conduct under the National Law; registered practitioners must notify AHPRA when they form a reasonable belief.', false, true, 'ADC'),
(1010, 'Ethics & law', 'Which Australian High Court case established that a practitioner must warn patients of material risks of treatment?', array['Rogers v Whitaker (1992)','Bolam v Friern Hospital (1957)','Gillick v West Norfolk (1985)','Montgomery v Lanarkshire (2015)']::text[], 0, 'Rogers v Whitaker: a risk is material if a reasonable person in the patient''s position would attach significance to it, or if the practitioner knows this particular patient would. Bolam, Gillick and Montgomery are UK cases.', false, true, 'ADC'),
(1011, 'Ethics & law', 'A 15-year-old attends alone and wants a filling. She clearly understands the procedure, risks and alternatives. Can she consent?', array['No – only a parent can consent for anyone under 18','Yes – a minor who has sufficient maturity and understanding (a "mature minor") can consent','Only with written permission from the school','Only if the treatment is free']::text[], 1, 'Australian common law (Gillick, adopted in Marion''s case) allows a mature minor to consent when they understand fully what is proposed. Assess and document competence; encourage involving parents where appropriate.', false, false, 'ADC'),
(1012, 'Infection control', 'Under the Spaulding classification, which item must be sterile at the point of use?', array['Mouth mirror used for examination','Surgical extraction forceps','Blood-pressure cuff','Dental chair headrest']::text[], 1, 'Critical items that penetrate soft tissue or bone must be sterile. Semi-critical items such as mirrors contact mucosa only and need sterilisation where possible (or high-level disinfection). Non-critical items touch intact skin.', false, true, 'ADC'),
(1013, 'Infection control', 'Your hands are not visibly soiled and you are about to touch a new patient. What is the recommended hand hygiene?', array['Alcohol-based hand rub','Surgical scrub with chlorhexidine for 3 minutes','Rinse with water only','Put gloves on over unwashed hands']::text[], 0, 'Alcohol-based hand rub is preferred when hands are not visibly soiled ("5 moments" of hand hygiene). Visibly soiled hands need soap and water; surgical scrub is for surgical procedures.', false, false, 'ADC'),
(1014, 'Infection control', 'A dental assistant sustains a needlestick injury from a used LA needle. What is the immediate first step?', array['Squeeze the wound hard and apply bleach','Wash the area with soap and running water, then report and arrange risk assessment','Finish the patient''s treatment first','Start antiretroviral medication immediately without assessment']::text[], 1, 'First aid: wash with soap and water (do not scrub or use bleach), report the incident, assess the source patient''s risk with consent, and arrange medical follow-up within hours in case post-exposure prophylaxis is needed.', false, false, 'ADC'),
(1015, 'Radiology', 'Which change reduces patient radiation dose most for intraoral radiographs?', array['Round collimation with a longer exposure','Rectangular collimation','Using a lead apron only','Using D-speed film']::text[], 1, 'Rectangular collimation greatly reduces the irradiated area compared with round collimation. Fast receptors (F-speed or digital) also reduce dose; routine lead aprons add little benefit for intraoral imaging.', false, false, 'ADC'),
(1016, 'Paediatric dentistry', 'A 10-year-old''s permanent upper central incisor was avulsed 20 minutes ago. Which storage medium should the parent use if the tooth cannot be replanted immediately?', array['Tap water','Cold milk','Dry tissue paper','Alcohol-based mouthwash']::text[], 1, 'Milk preserves periodontal ligament cell viability far better than water or dry storage (Hank''s solution is better still if available). Replant as soon as possible and splint flexibly for about 2 weeks.', false, true, 'ADC'),
(1017, 'Paediatric dentistry', 'A 3-year-old has avulsed a primary upper central incisor. What is the correct management?', array['Replant and splint for 2 weeks','Do not replant; check for injury to soft tissues and the developing permanent tooth','Replant without a splint','Place a space maintainer immediately']::text[], 1, 'Avulsed primary teeth are not replanted because of the risk to the developing successor. Advise on soft diet, hygiene and follow-up.', false, false, 'ADC'),
(1018, 'Paediatric dentistry', 'Under Australian guidance for fluoride use, what is advised for a 12-month-old with low caries risk?', array['Brush with a smear of adult toothpaste twice daily','Clean teeth with a soft brush but no toothpaste unless a professional advises otherwise','Fluoride supplements daily','Professional fluoride varnish every month']::text[], 1, 'Children under 18 months should not use toothpaste unless advised by a health professional. From 18 months to 5 years, a pea-sized amount of low-strength fluoride toothpaste is used.', false, false, 'ADC'),
(1019, 'Endodontics', 'A lower molar has sharp pain to cold that lingers for over a minute and wakes the patient at night. The tooth is not tender to percussion. What is the pulpal diagnosis?', array['Reversible pulpitis','Symptomatic irreversible pulpitis','Pulp necrosis','Normal pulp']::text[], 1, 'Lingering pain after a thermal stimulus plus spontaneous night pain indicates symptomatic irreversible pulpitis. Treatment is pulpotomy or pulpectomy and root canal treatment, or extraction.', false, false, 'ADC'),
(1020, 'Periodontics', 'A 45-year-old non-smoker has 6 mm interdental attachment loss, bone loss extending to the middle third of the root, and has lost 2 teeth to periodontitis. What is the 2017 World Workshop stage?', array['Stage I','Stage II','Stage III','Stage IV']::text[], 2, 'Stage III: interdental CAL ≥ 5 mm, bone loss into the middle third or beyond, and tooth loss due to periodontitis of 4 teeth or fewer. Stage IV involves ≥ 5 teeth lost or complex rehabilitation needs.', false, false, 'ADC'),
(1021, 'Oral medicine', 'A 60-year-old smoker has a painless, non-healing ulcer on the lateral tongue for 4 weeks with an indurated margin. What is the next step?', array['Review in 6 months','Prescribe antifungal and review in 2 weeks','Urgent referral for biopsy to exclude squamous cell carcinoma','Reassure – likely a traumatic ulcer']::text[], 2, 'Any ulcer persisting beyond 2–3 weeks after removing likely causes, especially indurated and in a high-risk site and patient, needs urgent specialist referral and biopsy.', false, true, 'ADC'),
(1022, 'Public health', 'Which brief intervention model is recommended for smoking cessation in Australian primary care, including dental practice?', array['Ask, Advise, Help','Refer every smoker to a cardiologist','Only advise patients who ask','Prescribe nicotine replacement to all smokers without assessment']::text[], 0, 'Ask about smoking, Advise to quit, Help by offering referral to Quitline (13 7848) and discussing pharmacotherapy. It takes a few minutes and is effective.', false, false, 'ADC')
